import { describe, it, expect, vi, beforeEach } from 'vitest';
import { render, screen, waitFor } from '@testing-library/react';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { BrowserRouter } from 'react-router-dom';
import userEvent from '@testing-library/user-event';
import InventoryPage from '../pages/inventory/InventoryPage';
import { demoIngredients } from '../data/mockData';
import { inventoryService } from '../services/inventoryService';

// Mock the inventory service
vi.mock('../services/inventoryService', () => ({
  inventoryService: {
    getAllItems: vi.fn(),
    getLowStockAlerts: vi.fn(),
    getExpiryAlerts: vi.fn(),
    searchItems: vi.fn(),
    deleteItem: vi.fn(),
    updateStock: vi.fn(),
  }
}));

// Helper to render with providers
const renderWithProviders = (component: React.ReactElement) => {
  const queryClient = new QueryClient({
    defaultOptions: {
      queries: { retry: false },
      mutations: { retry: false },
    },
  });

  return render(
    <QueryClientProvider client={queryClient}>
      <BrowserRouter>
        {component}
      </BrowserRouter>
    </QueryClientProvider>
  );
};

describe('InventoryPage', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    
    // Default mocks
    vi.mocked(inventoryService.getAllItems).mockResolvedValue({ items: demoIngredients });
    vi.mocked(inventoryService.getLowStockAlerts).mockResolvedValue([]);
    vi.mocked(inventoryService.getExpiryAlerts).mockResolvedValue([]);
    vi.mocked(inventoryService.searchItems).mockResolvedValue([]); 
  });

  // Cleanup timers
  afterEach(() => {
    vi.useRealTimers();
  });

  it('renders inventory page with title', () => {
    renderWithProviders(<InventoryPage />);
    expect(screen.getByText('Warehouse Dashboard')).toBeInTheDocument();
  });

  it('displays all ingredients in the table', async () => {
    renderWithProviders(<InventoryPage />);
    
    await waitFor(() => {
      expect(screen.getByText('Premium Cocoa Butter')).toBeInTheDocument();
      expect(screen.getByText('Dark Chocolate (70% Cocoa)')).toBeInTheDocument();
      expect(screen.getByText('Organic Cane Sugar')).toBeInTheDocument();
    });
  });

  it('shows low stock badge count', async () => {
    vi.mocked(inventoryService.getLowStockAlerts).mockResolvedValue(
      demoIngredients.filter(i => i.quantity < i.reorder_level)
    );

    renderWithProviders(<InventoryPage />);
    
    await waitFor(() => {
      // Find the card/text that shows count. 
      // Based on InventoryPage.tsx, it renders <p ...>{lowStockCount}</p> inside a "Low Stock Alerts" card.
      const lowStockCardTitle = screen.getByText('Low Stock Alerts');
      expect(lowStockCardTitle).toBeInTheDocument();
      
      // We can also check for the number, but it depends on mock data count.
      // demoIngredients item 4 (Whole Milk) has qty 12.5, min 30.
      // item 2 (Dark choc) qty 45.2, min 50.
      // So at least 2 items are low stock.
    });
  });

  it('filters ingredients by search term', async () => {
    const user = userEvent.setup();
    
    // Setup search mock
    vi.mocked(inventoryService.searchItems).mockResolvedValue([demoIngredients[0]]); // Premium Cocoa Butter
    
    renderWithProviders(<InventoryPage />);
    
    const searchInput = screen.getByPlaceholderText(/Search inventory/i);
    await user.type(searchInput, 'Cocoa');
    
    await waitFor(() => {
      expect(inventoryService.searchItems).toHaveBeenCalledWith('Cocoa');
      expect(screen.getByText('Premium Cocoa Butter')).toBeInTheDocument();
    }, { timeout: 2000 }); // Increase timeout to be safe
  });

  it('displays stock status correctly', async () => {
    renderWithProviders(<InventoryPage />);
    
    await waitFor(() => {
      // Should show "In Stock" for items above minimum
      // Premium Cocoa Butter (250.5 > 100) -> In Stock
      expect(screen.getAllByText('In Stock').length).toBeGreaterThan(0);
    });
  });
});

import { useState } from 'react';
import { Button } from './ui/Button';
import { useSendAIMessage, useGetAIStatus } from '../services/aiService';
import { Card, CardHeader, CardContent, CardFooter } from './ui/Card';
import { Input } from './ui/Input';
import { X, Send } from 'lucide-react';
import { cn } from '../lib/utils'; // Fixed path
import { useAuthStore } from '../store/authStore';

const AIChatWidget = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<{role: 'user' | 'assistant', text: string}[]>([
    { role: 'assistant', text: 'Hello! I am your ChocoOps AI assistant. How can I help you today?' }
  ]);
  const [input, setInput] = useState('');
  const user = useAuthStore((state) => state.user);

  const { mutate: sendMessageFn, isPending } = useSendAIMessage();
  const { data: aiStatus } = useGetAIStatus();
  const [chatHistory, setChatHistory] = useState<{role: string, content: string}[]>([]);

  const toggleChat = () => setIsOpen(!isOpen);

  const sendMessage = () => {
    if (!input.trim()) return;
    
    const userText = input;
    setMessages(prev => [...prev, { role: 'user', text: userText }]);
    setInput('');

    // Build history for the backend from previous messages
    const historyForBackend = chatHistory.map(h => ({ role: h.role, content: h.content }));

    sendMessageFn({ 
        message: userText,
        language: 'en',
        context: { 
          user_role: user?.role ?? 'manager',
          history: historyForBackend
        } 
    }, {
        onSuccess: (response) => {
            const botReply = response.message ?? response.response ?? 'No response received.';
            setMessages(prev => [...prev, { role: 'assistant', text: botReply }]);
            // Update history for next turn
            setChatHistory(prev => [...prev, { role: 'user', content: userText }, { role: 'assistant', content: botReply }]);
        },
        onError: (error) => {
            console.error('AI Chat Error:', error);
            setMessages(prev => [...prev, { role: 'assistant', text: "I'm having trouble connecting right now. Please try again later or check if the AI service is configured." }]);
        }
    });
  };

  return (
    <div className="fixed bottom-6 right-6 z-50 flex flex-col items-end">
        {/* Chat Window */}
        {isOpen && (
            <Card className="w-96 h-[500px] mb-4 flex flex-col shadow-2xl border-2 border-amber-200 bg-gradient-to-br from-white to-amber-50">
                <CardHeader className="bg-gradient-to-r from-amber-700 via-amber-600 to-amber-700 text-white p-4 rounded-t-lg flex flex-row items-center justify-between">
                    <span className="font-bold flex items-center gap-2 text-lg">
                        🍫 ChocoBot AI
                        {aiStatus && (
                            <span className="flex items-center gap-1 text-[10px] font-normal bg-black/20 px-2 py-0.5 rounded-full ml-2">
                                <div className={`w-2 h-2 rounded-full ${aiStatus.provider === 'mock' ? 'bg-amber-400' : 'bg-green-400'} animate-pulse`} />
                                {aiStatus.provider === 'anthropic' ? 'Claude' : aiStatus.provider === 'gemini' ? 'Gemini' : aiStatus.provider === 'deepseek' ? 'DeepSeek' : 'Sim Mode'}
                            </span>
                        )}
                    </span>
                    <Button variant="ghost" size="icon" className="h-8 w-8 text-white hover:bg-amber-800 rounded-full" onClick={toggleChat}>
                        <X className="h-5 w-5" />
                    </Button>
                </CardHeader>
                <CardContent className="flex-1 overflow-y-auto p-4 space-y-3 bg-gradient-to-b from-amber-50/30 to-white">
                    {messages.map((msg, idx) => (
                        <div key={idx} className={cn(
                            "max-w-[85%] rounded-2xl p-3 text-sm shadow-sm animate-in slide-in-from-bottom-2 duration-300",
                            msg.role === 'user'
                                ? "bg-gradient-to-br from-amber-500 to-amber-600 text-white ml-auto shadow-amber-200"
                                : "bg-white text-slate-700 mr-auto border border-amber-100 shadow-amber-100"
                        )}>
                            {msg.role === 'assistant' && <span className="text-amber-600 font-semibold text-xs">🤖 ChocoBot:</span>}
                            <p className={msg.role === 'assistant' ? 'mt-1' : ''}>{msg.text}</p>
                        </div>
                    ))}
                    {isPending && (
                        <div className="flex items-center gap-2 text-amber-600 text-sm">
                            <div className="flex gap-1">
                                <div className="w-2 h-2 bg-amber-600 rounded-full animate-bounce" style={{animationDelay: '0ms'}}></div>
                                <div className="w-2 h-2 bg-amber-600 rounded-full animate-bounce" style={{animationDelay: '150ms'}}></div>
                                <div className="w-2 h-2 bg-amber-600 rounded-full animate-bounce" style={{animationDelay: '300ms'}}></div>
                            </div>
                            <span>Thinking...</span>
                        </div>
                    )}
                </CardContent>
                <CardFooter className="p-3 border-t border-amber-100 bg-white">
                    <div className="flex w-full gap-2">
                        <Input
                            value={input}
                            onChange={(e) => setInput(e.target.value)}
                            onKeyDown={(e) => e.key === 'Enter' && !isPending && sendMessage()}
                            placeholder="Ask about inventory, recipes, or production..."
                            className="flex-1 border-amber-200 focus:border-amber-400 focus:ring-amber-400"
                            disabled={isPending}
                        />
                        <Button
                            size="icon"
                            onClick={sendMessage}
                            className="bg-gradient-to-r from-amber-600 to-amber-700 hover:from-amber-700 hover:to-amber-800 shadow-lg shadow-amber-200"
                            disabled={isPending || !input.trim()}
                        >
                            {isPending ? (
                                <div className="animate-spin h-4 w-4 border-2 border-white border-t-transparent rounded-full" />
                            ) : (
                                <Send className="h-4 w-4" />
                            )}
                        </Button>
                    </div>
                </CardFooter>
            </Card>
        )}

      {/* Toggle Button */}
      <Button
        onClick={toggleChat}
        className="h-16 w-16 rounded-full bg-gradient-to-br from-amber-600 via-amber-700 to-amber-800 hover:from-amber-700 hover:via-amber-800 hover:to-amber-900 shadow-2xl shadow-amber-300 flex items-center justify-center transition-all duration-300 hover:scale-110 border-2 border-amber-400"
      >
        {isOpen ? <X className="h-7 w-7 text-white" /> : <span className="text-3xl">🍫</span>}
      </Button>
    </div>
  );
};

export default AIChatWidget;

import React, { useState, useRef, useEffect } from 'react';
import { Send, Mic, MicOff, Loader2 } from 'lucide-react';
import { Button } from '../ui/Button';
import { cn } from '../../lib/utils';

// Define Speech Recognition types locally since they aren't standard yet
interface SpeechRecognitionEvent extends Event {
  results: SpeechRecognitionResultList;
  resultIndex: number;
}

interface SpeechRecognitionResultList {
  length: number;
  item(index: number): SpeechRecognitionResult;
  [index: number]: SpeechRecognitionResult;
}

interface SpeechRecognitionResult {
  isFinal: boolean;
  length: number;
  item(index: number): SpeechRecognitionAlternative;
  [index: number]: SpeechRecognitionAlternative;
}

interface SpeechRecognitionAlternative {
  transcript: string;
  confidence: number;
}

interface SpeechRecognition extends EventTarget {
  continuous: boolean;
  interimResults: boolean;
  lang: string;
  start(): void;
  stop(): void;
  abort(): void;
  onresult: ((event: SpeechRecognitionEvent) => void) | null;
  onend: ((event: Event) => void) | null;
  onerror: ((event: Event) => void) | null;
}

interface SpeechRecognitionConstructor {
  new (): SpeechRecognition;
}

declare global {
  interface Window {
    webkitSpeechRecognition?: SpeechRecognitionConstructor;
    SpeechRecognition?: SpeechRecognitionConstructor;
  }
}

interface ChatInputProps {
  onSend: (message: string) => void;
  loading: boolean;
  language: string;
  context: string;
  onContextChange: (context: string) => void;
}

// Placeholder translations
const placeholders: Record<string, string> = {
  en: 'Ask me anything about inventory, production, QC...',
  ar: 'اسألني أي شيء عن المخزون، الإنتاج، مراقبة الجودة...',
  he: 'שאל אותי משהו על מלאי, ייצור, בקרת איכות...',
  am: 'ስለ ክምችት፣ ምርት፣ QC... ማንኛውንም ነገር ጠይቀኝ',
  ru: 'Спросите меня о складе, производстве, контроле качества...',
  uk: 'Запитайте мене про склад, виробництво, контроль якості...',
};

const ChatInput: React.FC<ChatInputProps> = ({
  onSend,
  loading,
  language,
  context,
  onContextChange,
}) => {
  const [message, setMessage] = useState('');
  const [isListening, setIsListening] = useState(false);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const recognitionRef = useRef<SpeechRecognition | null>(null);

  // Auto-resize textarea
  useEffect(() => {
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
      textareaRef.current.style.height = `${Math.min(textareaRef.current.scrollHeight, 150)}px`;
    }
  }, [message]);

  // Initialize speech recognition
  useEffect(() => {
    if (typeof window !== 'undefined' && ('webkitSpeechRecognition' in window || 'SpeechRecognition' in window)) {
      const SpeechRecognition = window.webkitSpeechRecognition ?? window.SpeechRecognition;
      if (SpeechRecognition) {
        recognitionRef.current = new SpeechRecognition();
        recognitionRef.current.continuous = false;
        recognitionRef.current.interimResults = true;

        // Map language codes to speech recognition language codes
        const langMap: Record<string, string> = {
          en: 'en-US',
          ar: 'ar-SA',
          he: 'he-IL',
          am: 'am-ET',
          ru: 'ru-RU',
          uk: 'uk-UA',
        };
        recognitionRef.current.lang = langMap[language] ?? 'en-US';

        recognitionRef.current.onresult = (event: SpeechRecognitionEvent) => {
          const transcript = Array.from(event.results)
            .map((result) => result[0].transcript)
            .join('');
          setMessage(transcript);
        };

        recognitionRef.current.onend = () => {
          setIsListening(false);
        };

        recognitionRef.current.onerror = () => {
          setIsListening(false);
        };
      }
    }

    return () => {
      if (recognitionRef.current) {
        recognitionRef.current.abort();
      }
    };
  }, [language]);

  const handleSubmit = () => {
    if (!message.trim() || loading) return;
    onSend(message.trim());
    setMessage('');
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSubmit();
    }
  };

  const toggleVoiceInput = () => {
    if (!recognitionRef.current) return;

    if (isListening) {
      recognitionRef.current.stop();
      setIsListening(false);
    } else {
      recognitionRef.current.start();
      setIsListening(true);
    }
  };

  const placeholder = placeholders[language] ?? placeholders.en;

  return (
    <div className="space-y-3">
      {/* Context selector */}
      <div className="flex gap-2 overflow-x-auto pb-2">
        {(['general', 'inventory', 'production', 'qc'] as const).map((ctx) => (
          <button
            key={ctx}
            onClick={() => onContextChange(ctx)}
            className={cn(
              "px-3 py-1.5 rounded-full text-xs font-medium whitespace-nowrap transition-colors",
              context === ctx
                ? "bg-cocoa-600 text-white"
                : "bg-slate-100 text-slate-600 hover:bg-slate-200"
            )}
          >
            {ctx === 'general' && '💡 General'}
            {ctx === 'inventory' && '📦 Inventory'}
            {ctx === 'production' && '🏭 Production'}
            {ctx === 'qc' && '✅ QC'}
          </button>
        ))}
      </div>

      {/* Input area */}
      <div className="flex items-end gap-2">
        {/* Voice input button */}
        {(typeof window !== 'undefined' && ('webkitSpeechRecognition' in window || 'SpeechRecognition' in window)) && (
          <Button
            type="button"
            variant={isListening ? 'default' : 'outline'}
            size="sm"
            onClick={toggleVoiceInput}
            className={cn(
              "flex-shrink-0",
              isListening && "bg-red-500 hover:bg-red-600 animate-pulse"
            )}
            title={isListening ? 'Stop listening' : 'Voice input'}
          >
            {isListening ? (
              <MicOff className="w-4 h-4" />
            ) : (
              <Mic className="w-4 h-4" />
            )}
          </Button>
        )}

        {/* Textarea */}
        <div className="flex-1 relative">
          <textarea
            ref={textareaRef}
            value={message}
            onChange={(e) => setMessage(e.target.value)}
            onKeyDown={handleKeyDown}
            placeholder={placeholder}
            disabled={loading}
            rows={1}
            className={cn(
              "w-full px-4 py-3 pr-12 border-2 border-slate-200 rounded-xl resize-none",
              "focus:outline-none focus:border-cocoa-500 transition-colors",
              "placeholder:text-slate-400 text-slate-700",
              "disabled:opacity-50 disabled:cursor-not-allowed",
              isListening && "border-red-300 bg-red-50"
            )}
            style={{ maxHeight: '150px' }}
            dir={language === 'ar' || language === 'he' ? 'rtl' : 'ltr'}
          />
          {/* Character count */}
          {message.length > 0 && (
            <span className="absolute bottom-1 right-14 text-xs text-slate-400">
              {message.length}
            </span>
          )}
        </div>

        {/* Send button */}
        <Button
          type="button"
          aria-label="Send message"
          onClick={handleSubmit}
          disabled={!message.trim() || loading}
          className="flex-shrink-0 bg-cocoa-600 hover:bg-cocoa-700"
        >
          {loading ? (
            <Loader2 className="w-4 h-4 animate-spin" />
          ) : (
            <Send className="w-4 h-4" />
          )}
        </Button>
      </div>

      {/* Keyboard hint */}
      <p className="text-xs text-slate-400 text-center">
        Press <kbd className="px-1.5 py-0.5 bg-slate-100 rounded text-slate-500">Enter</kbd> to send,{' '}
        <kbd className="px-1.5 py-0.5 bg-slate-100 rounded text-slate-500">Shift+Enter</kbd> for new line
      </p>
    </div>
  );
};

export default ChatInput;

import React, { useState } from 'react';
import { Bot, User, Copy, Check } from 'lucide-react';
import ReactMarkdown from 'react-markdown';
import { ChatMessage as ChatMessageType } from '../../hooks/useAIChat';
import { cn } from '../../lib/utils';

export interface ChatMessageProps {
  message: ChatMessageType;
  onCopy?: () => void;
}

const ChatMessage: React.FC<ChatMessageProps> = ({ message, onCopy }) => {
  const [copied, setCopied] = useState(false);
  const isUser = message.isUser;

  const handleCopy = () => {
    navigator.clipboard.writeText(message.content);
    setCopied(true);
    onCopy?.();
    setTimeout(() => setCopied(false), 2000);
  };

  const formatTime = (date: Date) => {
    return new Date(date).toLocaleTimeString('en-US', {
      hour: '2-digit',
      minute: '2-digit',
    });
  };

  return (
    <div className={cn(
      "flex gap-3 group",
      isUser ? "flex-row-reverse" : "flex-row"
    )}>
      {/* Avatar */}
      <div className={cn(
        "w-8 h-8 rounded-full flex items-center justify-center flex-shrink-0",
        isUser
          ? "bg-cocoa-600"
          : "bg-gradient-to-br from-cocoa-500 to-chocolate-600"
      )}>
        {isUser ? (
          <User className="w-4 h-4 text-white" />
        ) : (
          <Bot className="w-4 h-4 text-white" />
        )}
      </div>

      {/* Message bubble */}
      <div className={cn(
        "relative max-w-[80%] rounded-2xl px-4 py-3",
        isUser
          ? "bg-cocoa-700 text-white rounded-tr-none"
          : "bg-white border border-slate-200 text-slate-800 rounded-tl-none shadow-sm"
      )}>
        {/* Message content */}
        <div className={cn(
          "prose prose-sm max-w-none",
          isUser && "prose-invert"
        )}>
          {isUser ? (
            <p className="m-0 whitespace-pre-wrap">{message.content}</p>
          ) : (
            <ReactMarkdown
              components={{
                p: ({ children }) => <p className="mb-2 last:mb-0">{children}</p>,
                ul: ({ children }) => <ul className="my-2 pl-4 list-disc">{children}</ul>,
                ol: ({ children }) => <ol className="my-2 pl-4 list-decimal">{children}</ol>,
                li: ({ children }) => <li className="mb-1">{children}</li>,
                code: ({ className, children }) => {
                  const isInline = !className;
                  return isInline ? (
                    <code className="bg-slate-100 px-1 py-0.5 rounded text-cocoa-700 text-sm">
                      {children}
                    </code>
                  ) : (
                    <code className="block bg-slate-900 text-slate-100 p-3 rounded-lg overflow-x-auto text-sm my-2">
                      {children}
                    </code>
                  );
                },
                pre: ({ children }) => <pre className="m-0">{children}</pre>,
                strong: ({ children }) => <strong className="font-semibold">{children}</strong>,
                a: ({ href, children }) => (
                  <a href={href} target="_blank" rel="noopener noreferrer" className="text-cocoa-600 hover:underline">
                    {children}
                  </a>
                ),
                h1: ({ children }) => <h1 className="text-lg font-bold mt-3 mb-2">{children}</h1>,
                h2: ({ children }) => <h2 className="text-base font-bold mt-2 mb-1">{children}</h2>,
                h3: ({ children }) => <h3 className="text-sm font-bold mt-2 mb-1">{children}</h3>,
                blockquote: ({ children }) => (
                  <blockquote className="border-l-4 border-cocoa-300 pl-3 my-2 italic text-slate-600">
                    {children}
                  </blockquote>
                ),
                table: ({ children }) => (
                  <div className="overflow-x-auto my-2">
                    <table className="min-w-full border border-slate-200 rounded">
                      {children}
                    </table>
                  </div>
                ),
                th: ({ children }) => (
                  <th className="bg-slate-100 px-3 py-1 text-left text-sm font-semibold border-b">
                    {children}
                  </th>
                ),
                td: ({ children }) => (
                  <td className="px-3 py-1 text-sm border-b border-slate-100">
                    {children}
                  </td>
                ),
              }}
            >
              {message.content}
            </ReactMarkdown>
          )}
        </div>

        {/* Timestamp */}
        <div className={cn(
          "text-xs mt-1",
          isUser ? "text-cocoa-200" : "text-slate-400"
        )}>
          {formatTime(message.timestamp)}
        </div>

        {/* Copy button */}
        <button
          onClick={handleCopy}
          className={cn(
            "absolute -right-2 -top-2 p-1.5 rounded-full transition-all",
            "opacity-0 group-hover:opacity-100",
            isUser
              ? "bg-cocoa-800 text-cocoa-200 hover:text-white"
              : "bg-white border shadow-sm text-slate-400 hover:text-slate-600"
          )}
          title="Copy message"
        >
          {copied ? (
            <Check className="w-3 h-3 text-green-500" />
          ) : (
            <Copy className="w-3 h-3" />
          )}
        </button>
      </div>
    </div>
  );
};

export default ChatMessage;

import React, { useState, useRef, useEffect } from 'react';
import { Globe, ChevronDown, Check } from 'lucide-react';
import { cn } from '../../lib/utils';

interface LanguageSelectorProps {
  value: string;
  onChange: (lang: string) => void;
}

interface Language {
  code: string;
  name: string;
  nativeName: string;
  flag: string;
}

const languages: Language[] = [
  { code: 'en', name: 'English', nativeName: 'English', flag: '🇬🇧' },
  { code: 'ar', name: 'Arabic', nativeName: 'العربية', flag: '🇸🇦' },
  { code: 'he', name: 'Hebrew', nativeName: 'עברית', flag: '🇮🇱' },
  { code: 'am', name: 'Amharic', nativeName: 'አማርኛ', flag: '🇪🇹' },
  { code: 'ru', name: 'Russian', nativeName: 'Русский', flag: '🇷🇺' },
  { code: 'uk', name: 'Ukrainian', nativeName: 'Українська', flag: '🇺🇦' },
];

const LanguageSelector: React.FC<LanguageSelectorProps> = ({ value, onChange }) => {
  const [isOpen, setIsOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  const selectedLanguage = languages.find((l) => l.code === value) || languages[0];

  // Close dropdown on outside click
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    };

    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleSelect = (code: string) => {
    onChange(code);
    setIsOpen(false);
  };

  return (
    <div className="relative" ref={dropdownRef}>
      {/* Trigger button */}
      <button
        onClick={() => setIsOpen(!isOpen)}
        className={cn(
          "flex items-center gap-2 px-3 py-2 rounded-lg border transition-all",
          "bg-white hover:bg-slate-50 border-slate-200",
          isOpen && "border-cocoa-500 ring-2 ring-cocoa-100"
        )}
      >
        <Globe className="w-4 h-4 text-slate-500" />
        <span className="text-lg">{selectedLanguage.flag}</span>
        <span className="text-sm font-medium text-slate-700 hidden sm:inline">
          {selectedLanguage.nativeName}
        </span>
        <ChevronDown className={cn(
          "w-4 h-4 text-slate-400 transition-transform",
          isOpen && "rotate-180"
        )} />
      </button>

      {/* Dropdown */}
      {isOpen && (
        <div className="absolute right-0 top-full mt-2 w-56 bg-white rounded-xl border border-slate-200 shadow-lg z-50 overflow-hidden">
          <div className="p-2">
            <p className="text-xs text-slate-500 px-2 py-1 font-medium">
              Select Language
            </p>
          </div>
          <div className="max-h-64 overflow-y-auto">
            {languages.map((language) => (
              <button
                key={language.code}
                onClick={() => handleSelect(language.code)}
                className={cn(
                  "w-full flex items-center gap-3 px-4 py-2.5 text-left transition-colors",
                  "hover:bg-cocoa-50",
                  value === language.code && "bg-cocoa-50"
                )}
              >
                <span className="text-xl">{language.flag}</span>
                <div className="flex-1 min-w-0">
                  <p className="text-sm font-medium text-slate-800">
                    {language.nativeName}
                  </p>
                  <p className="text-xs text-slate-500">
                    {language.name}
                  </p>
                </div>
                {value === language.code && (
                  <Check className="w-4 h-4 text-cocoa-600" />
                )}
              </button>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

export default LanguageSelector;

import React, { useEffect, useCallback } from 'react';
import { X } from 'lucide-react';
import { cn } from '../../lib/utils';
import { createPortal } from 'react-dom';

type ModalSize = 'sm' | 'md' | 'lg' | 'xl' | 'full';

interface ModalProps {
  isOpen: boolean;
  onClose: () => void;
  title?: string;
  description?: string;
  children: React.ReactNode;
  footer?: React.ReactNode;
  size?: ModalSize;
  className?: string;
  closeOnOverlayClick?: boolean;
  closeOnEscape?: boolean;
  showCloseButton?: boolean;
}

const sizeClasses: Record<ModalSize, string> = {
  sm: 'max-w-sm',
  md: 'max-w-lg',
  lg: 'max-w-2xl',
  xl: 'max-w-4xl',
  full: 'max-w-[95vw] w-full',
};

export const Modal: React.FC<ModalProps> = ({
  isOpen,
  onClose,
  title,
  description,
  children,
  footer,
  size = 'md',
  className,
  closeOnOverlayClick = true,
  closeOnEscape = true,
  showCloseButton = true,
}) => {
  const handleEscape = useCallback((e: KeyboardEvent) => {
    if (e.key === 'Escape' && closeOnEscape) onClose();
  }, [onClose, closeOnEscape]);

  const handleOverlayClick = useCallback((e: React.MouseEvent<HTMLDivElement>) => {
    if (e.target === e.currentTarget && closeOnOverlayClick) {
      onClose();
    }
  }, [onClose, closeOnOverlayClick]);

  useEffect(() => {
    if (isOpen) {
      document.addEventListener('keydown', handleEscape);
      document.body.style.overflow = 'hidden';
    }

    return () => {
      document.removeEventListener('keydown', handleEscape);
      document.body.style.overflow = 'unset';
    };
  }, [isOpen, handleEscape]);

  if (!isOpen) return null;

  return createPortal(
    <div
      className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm animate-fade-in"
      onClick={handleOverlayClick}
    >
      <div
        className={cn(
          "bg-white dark:bg-slate-900 rounded-lg shadow-xl w-full border border-slate-200 dark:border-slate-800 flex flex-col max-h-[90vh]",
          sizeClasses[size],
          className
        )}
        role="dialog"
        aria-modal="true"
        aria-labelledby={title ? "modal-title" : undefined}
        aria-describedby={description ? "modal-description" : undefined}
      >
        {/* Header */}
        {(title || showCloseButton) && (
          <div className="flex items-center justify-between p-4 border-b border-slate-100 dark:border-slate-800">
            <div>
              {title && (
                <h2
                  id="modal-title"
                  className="text-xl font-bold font-serif text-cocoa-900 dark:text-cocoa-100"
                >
                  {title}
                </h2>
              )}
              {description && (
                <p
                  id="modal-description"
                  className="mt-1 text-sm text-slate-500 dark:text-slate-400"
                >
                  {description}
                </p>
              )}
            </div>
            {showCloseButton && (
              <button
                onClick={onClose}
                className="text-slate-500 hover:text-slate-700 dark:text-slate-400 dark:hover:text-slate-200 transition-colors rounded-md p-1 hover:bg-slate-100 dark:hover:bg-slate-800"
                aria-label="Close modal"
              >
                <X className="h-5 w-5" />
              </button>
            )}
          </div>
        )}

        {/* Body */}
        <div className="p-6 overflow-y-auto flex-1">{children}</div>

        {/* Footer */}
        {footer && (
          <div className="flex items-center justify-end gap-3 p-4 border-t border-slate-100 dark:border-slate-800 bg-slate-50 dark:bg-slate-800/50 rounded-b-lg">
            {footer}
          </div>
        )}
      </div>
    </div>,
    document.body
  );
};

// Convenience wrapper for confirmation dialogs
interface ConfirmModalProps {
  isOpen: boolean;
  onClose: () => void;
  onConfirm: () => void;
  title: string;
  message: string;
  confirmText?: string;
  cancelText?: string;
  variant?: 'danger' | 'warning' | 'default';
  isLoading?: boolean;
}

export const ConfirmModal: React.FC<ConfirmModalProps> = ({
  isOpen,
  onClose,
  onConfirm,
  title,
  message,
  confirmText = 'Confirm',
  cancelText = 'Cancel',
  variant = 'default',
  isLoading = false,
}) => {
  const variantClasses = {
    danger: 'bg-red-600 hover:bg-red-700 text-white',
    warning: 'bg-amber-500 hover:bg-amber-600 text-white',
    default: 'bg-primary hover:bg-primary/90 text-primary-foreground',
  };

  return (
    <Modal
      isOpen={isOpen}
      onClose={onClose}
      title={title}
      size="sm"
      footer={
        <>
          <button
            onClick={onClose}
            disabled={isLoading}
            className="px-4 py-2 text-sm font-medium text-slate-700 bg-white border border-slate-300 rounded-md hover:bg-slate-50 disabled:opacity-50"
          >
            {cancelText}
          </button>
          <button
            onClick={onConfirm}
            disabled={isLoading}
            className={cn(
              "px-4 py-2 text-sm font-medium rounded-md disabled:opacity-50",
              variantClasses[variant]
            )}
          >
            {isLoading ? 'Loading...' : confirmText}
          </button>
        </>
      }
    >
      <p className="text-slate-600 dark:text-slate-400">{message}</p>
    </Modal>
  );
};

