import React, { useEffect, useState, useRef } from 'react';
import { LucideIcon, TrendingUp, TrendingDown, Minus } from 'lucide-react';
import { Card, CardContent } from '../ui/Card';
import { cn } from '../../lib/utils';

interface MetricsCardProps {
  title: string;
  value: number;
  icon: LucideIcon;
  trend?: 'up' | 'down' | 'stable';
  trendValue?: number;
  color?: 'success' | 'warning' | 'danger' | 'default';
  subtitle?: string;
  prefix?: string;
  suffix?: string;
  onClick?: () => void;
  loading?: boolean;
  animate?: boolean;
}

const MetricsCard: React.FC<MetricsCardProps> = ({
  title,
  value,
  icon: Icon,
  trend,
  trendValue,
  color = 'default',
  subtitle,
  prefix = '',
  suffix = '',
  onClick,
  loading = false,
  animate = true,
}) => {
  const [displayValue, setDisplayValue] = useState(0);
  const animationRef = useRef<number | null>(null);
  const previousValueRef = useRef<number>(0);

  // Animated number counter
  useEffect(() => {
    if (loading || !animate) {
      setDisplayValue(value);
      return;
    }

    const startValue = previousValueRef.current;
    const endValue = value;
    const duration = 1000; // 1 second animation
    const startTime = performance.now();

    const animateValue = (currentTime: number) => {
      const elapsed = currentTime - startTime;
      const progress = Math.min(elapsed / duration, 1);

      // Easing function for smooth animation
      const easeOutQuart = 1 - Math.pow(1 - progress, 4);
      const current = startValue + (endValue - startValue) * easeOutQuart;

      setDisplayValue(current);

      if (progress < 1) {
        animationRef.current = requestAnimationFrame(animateValue);
      } else {
        previousValueRef.current = endValue;
      }
    };

    animationRef.current = requestAnimationFrame(animateValue);

    return () => {
      if (animationRef.current) {
        cancelAnimationFrame(animationRef.current);
      }
    };
  }, [value, loading, animate]);

  // Color mappings
  const colorMap = {
    success: {
      border: 'border-l-green-500',
      bg: 'bg-green-50',
      icon: 'bg-green-100 text-green-600',
      text: 'text-green-600',
    },
    warning: {
      border: 'border-l-amber-500',
      bg: 'bg-amber-50',
      icon: 'bg-amber-100 text-amber-600',
      text: 'text-amber-600',
    },
    danger: {
      border: 'border-l-red-500',
      bg: 'bg-red-50',
      icon: 'bg-red-100 text-red-600',
      text: 'text-red-600',
    },
    default: {
      border: 'border-l-cocoa-500',
      bg: 'bg-white',
      icon: 'bg-cocoa-100 text-cocoa-600',
      text: 'text-cocoa-600',
    },
  };

  const colors = colorMap[color];

  // Format number with commas
  const formatNumber = (num: number): string => {
    if (Number.isInteger(value)) {
      return Math.round(num).toLocaleString();
    }
    return num.toFixed(1).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  };

  // Trend icon and color
  const TrendIcon = trend === 'up' ? TrendingUp : trend === 'down' ? TrendingDown : Minus;
  const trendColor = trend === 'up' ? 'text-green-500' : trend === 'down' ? 'text-red-500' : 'text-gray-400';

  return (
    <Card
      className={cn(
        "relative overflow-hidden transition-all duration-300 border-l-4",
        colors.border,
        onClick && "cursor-pointer hover:shadow-lg hover:scale-[1.02]",
        loading && "animate-pulse"
      )}
      onClick={onClick}
    >
      <CardContent className="p-4">
        {/* Loading skeleton */}
        {loading ? (
          <div className="space-y-3">
            <div className="flex items-center justify-between">
              <div className="h-4 w-24 bg-gray-200 rounded animate-pulse" />
              <div className="h-10 w-10 bg-gray-200 rounded-lg animate-pulse" />
            </div>
            <div className="h-8 w-20 bg-gray-200 rounded animate-pulse" />
            <div className="h-3 w-32 bg-gray-200 rounded animate-pulse" />
          </div>
        ) : (
          <>
            {/* Header with icon */}
            <div className="flex items-start justify-between mb-3">
              <p className="text-sm font-medium text-slate-500 pr-2">
                {title}
              </p>
              <div className={cn(
                "p-2 rounded-lg transition-transform",
                colors.icon,
                onClick && "group-hover:scale-110"
              )}>
                <Icon className="w-5 h-5" />
              </div>
            </div>

            {/* Value with optional prefix/suffix */}
            <div className="flex items-baseline gap-1 mb-1">
              {prefix && (
                <span className="text-lg font-medium text-slate-400">{prefix}</span>
              )}
              <span className={cn(
                "text-3xl font-bold tracking-tight",
                colors.text
              )}>
                {formatNumber(displayValue)}
              </span>
              {suffix && (
                <span className="text-lg font-medium text-slate-400">{suffix}</span>
              )}
            </div>

            {/* Trend indicator */}
            {trend && trendValue !== undefined && (
              <div className={cn("flex items-center gap-1 mb-2", trendColor)}>
                <TrendIcon className="w-4 h-4" />
                <span className="text-sm font-medium">
                  {trend === 'up' ? '+' : trend === 'down' ? '-' : ''}{trendValue}%
                </span>
                <span className="text-xs text-slate-400 ml-1">vs last period</span>
              </div>
            )}

            {/* Subtitle */}
            {subtitle && (
              <p className="text-xs text-slate-400 mt-1 line-clamp-1">
                {subtitle}
              </p>
            )}

            {/* Hover indicator */}
            {onClick && (
              <div className="absolute bottom-0 left-0 right-0 h-1 bg-gradient-to-r from-transparent via-cocoa-300 to-transparent opacity-0 hover:opacity-100 transition-opacity" />
            )}
          </>
        )}
      </CardContent>
    </Card>
  );
};

export default MetricsCard;

import React, { useState, useEffect } from 'react';
import { X, Upload } from 'lucide-react';
import { useCreateTask, useUpdateTask } from '../../hooks/useTaskMutations';
import { useUsers } from '../../hooks/useUsers';

import { Task, User, TaskStatus, TaskPriority } from '../../types';

interface TaskModalProps {
  isOpen: boolean;
  onClose: () => void;
  task?: Task;
  onSuccess: () => void;
}

const TaskModal: React.FC<TaskModalProps> = ({
  isOpen,
  onClose,
  task,
  onSuccess
}) => {
  const [formData, setFormData] = useState({
    title: '',
    description: '',
    assigned_to: '',
    priority: 'medium' as TaskPriority,
    due_date: '',
    status: 'pending' as TaskStatus
  });

  const { mutate: createTask, isPending: isCreating } = useCreateTask();
  const { mutate: updateTask, isPending: isUpdating } = useUpdateTask();
  const { users } = useUsers();

  useEffect(() => {
    if (task) {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setFormData({
        title: task.title ?? '',
        description: task.description ?? '',
        assigned_to: task.assigned_to ?? '',
        priority: task.priority ?? 'medium',
        due_date: task.due_date ? new Date(task.due_date).toISOString().split('T')[0] : '',
        status: task.status ?? 'pending'
      });
    } else {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setFormData({
        title: '',
        description: '',
        assigned_to: '',
        priority: 'medium',
        due_date: '',
        status: 'pending'
      });
    }
  }, [task]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    if (!formData.title.trim()) {
      alert('Title is required');
      return;
    }

    if (!formData.assigned_to) {
      alert('Please assign the task to someone');
      return;
    }

    const data = {
      ...formData,
      due_date: formData.due_date || undefined
    };

    if (task) {
      updateTask({ id: task.id, ...data }, {
        onSuccess: () => {
          onSuccess();
          onClose();
        }
      });
    } else {
      createTask(data, {
        onSuccess: () => {
          onSuccess();
          onClose();
        }
      });
    }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
      <div className="bg-white rounded-2xl shadow-2xl max-w-2xl w-full max-h-[90vh] overflow-y-auto">
        {/* Header */}
        <div className="sticky top-0 bg-gradient-to-r from-blue-500 to-indigo-500 text-white p-6 rounded-t-2xl flex items-center justify-between">
          <h2 className="text-2xl font-bold">
            {task ? 'Edit Task' : 'Create New Task'}
          </h2>
          <button
            onClick={onClose}
            className="p-2 hover:bg-white/20 rounded-lg transition-colors"
          >
            <X className="w-6 h-6" />
          </button>
        </div>

        {/* Content */}
        <form onSubmit={handleSubmit} className="p-6 space-y-6">
          {/* Title */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              Task Title *
            </label>
            <input
              type="text"
              value={formData.title}
              onChange={(e) => setFormData(prev => ({ ...prev, title: e.target.value }))}
              className="w-full px-4 py-2 border-2 border-gray-200 rounded-lg focus:border-blue-500 focus:outline-none"
              placeholder="Enter task title"
              required
            />
          </div>

          {/* Description */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              Description
            </label>
            <textarea
              value={formData.description}
              onChange={(e) => setFormData(prev => ({ ...prev, description: e.target.value }))}
              rows={4}
              className="w-full px-4 py-2 border-2 border-gray-200 rounded-lg focus:border-blue-500 focus:outline-none resize-none"
              placeholder="Enter task description"
            />
          </div>

          {/* Assign To */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              Assign To *
            </label>
            <select
              value={formData.assigned_to}
              onChange={(e) => setFormData(prev => ({ ...prev, assigned_to: e.target.value }))}
              className="w-full px-4 py-2 border-2 border-gray-200 rounded-lg focus:border-blue-500 focus:outline-none"
              required
            >
              <option value="">Select a user</option>
              {users?.map((user: User) => (
                <option key={user.id} value={user.id}>
                  {user.full_name} ({user.role})
                </option>
              ))}
            </select>
          </div>

          {/* Priority and Due Date */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {/* Priority */}
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                Priority
              </label>
              <select
                value={formData.priority}
                onChange={(e) => setFormData(prev => ({ ...prev, priority: e.target.value as TaskPriority }))}
                className="w-full px-4 py-2 border-2 border-gray-200 rounded-lg focus:border-blue-500 focus:outline-none"
              >
                <option value="low">Low</option>
                <option value="medium">Medium</option>
                <option value="high">High</option>
              </select>
            </div>

            {/* Due Date */}
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                Due Date
              </label>
              <input
                type="date"
                value={formData.due_date}
                onChange={(e) => setFormData(prev => ({ ...prev, due_date: e.target.value }))}
                min={new Date().toISOString().split('T')[0]}
                className="w-full px-4 py-2 border-2 border-gray-200 rounded-lg focus:border-blue-500 focus:outline-none"
              />
            </div>
          </div>

          {/* Status (only when editing) */}
          {task && (
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                Status
              </label>
              <select
                value={formData.status}
                onChange={(e) => setFormData(prev => ({ ...prev, status: e.target.value as TaskStatus }))}
                className="w-full px-4 py-2 border-2 border-gray-200 rounded-lg focus:border-blue-500 focus:outline-none"
              >
                <option value="pending">Pending</option>
                <option value="in_progress">In Progress</option>
                <option value="completed">Completed</option>
                <option value="cancelled">Cancelled</option>
              </select>
            </div>
          )}

          {/* Attachments (Optional - placeholder) */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              Attachments (Optional)
            </label>
            <div className="border-2 border-dashed border-gray-300 rounded-lg p-6 text-center hover:border-blue-500 transition-colors cursor-pointer">
              <Upload className="w-8 h-8 mx-auto text-gray-400 mb-2" />
              <p className="text-sm text-gray-600">Click to upload or drag and drop</p>
              <p className="text-xs text-gray-400 mt-1">PDF, DOC, XLS, PNG, JPG (max 10MB)</p>
            </div>
          </div>

          {/* Buttons */}
          <div className="flex gap-3 pt-4">
            <button
              type="button"
              onClick={onClose}
              className="flex-1 px-6 py-3 bg-gray-100 text-gray-700 rounded-lg hover:bg-gray-200 transition-colors font-medium"
            >
              Cancel
            </button>
            <button
              type="submit"
              disabled={isCreating || isUpdating}
              className="flex-1 px-6 py-3 bg-gradient-to-r from-blue-500 to-indigo-500 text-white rounded-lg hover:from-blue-600 hover:to-indigo-600 transition-all font-medium disabled:opacity-50"
            >
              {isCreating || isUpdating ? 'Saving...' : task ? 'Update Task' : 'Create Task'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default TaskModal;

import React, { useState, FormEvent } from 'react';
import { Wrench, Save } from 'lucide-react';
import { toast } from 'sonner';
import { Modal } from '../common/Modal';
import { Button } from '../ui/Button';
import { Input } from '../ui/Input';
import { useMechanic } from '../../hooks/useMechanic';
import { Machine } from '../../types';

export interface MaintenanceLogModalProps {
  isOpen: boolean;
  onClose: () => void;
  machineId?: string;
  onSuccess?: () => void;
}

const MAINTENANCE_TYPES = [
  { value: 'preventive', label: 'Preventive', description: 'Scheduled maintenance' },
  { value: 'corrective', label: 'Corrective', description: 'Fix identified issues' },
  { value: 'emergency', label: 'Emergency', description: 'Urgent unplanned repair' },
];

const MaintenanceLogModal: React.FC<MaintenanceLogModalProps> = ({
  isOpen,
  onClose,
  machineId,
  onSuccess,
}) => {
  const { useMachines, useCreateMaintenanceLog } = useMechanic();
  const { data: machines = [] } = useMachines();
  const createLogMutation = useCreateMaintenanceLog();

  const [formData, setFormData] = useState({
    machineId: machineId || '',
    maintenanceType: 'preventive' as 'preventive' | 'corrective' | 'emergency',
    description: '',
    partsReplaced: '',
    durationMinutes: '',
    cost: '',
  });

  const [validationError, setValidationError] = useState('');

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    setValidationError('');

    if (!formData.machineId) {
      setValidationError('Please select a machine');
      return;
    }

    if (!formData.description.trim()) {
      setValidationError('Description is required');
      return;
    }

    const partsReplaced = formData.partsReplaced
      ? formData.partsReplaced.split(',').map((p) => p.trim()).filter(Boolean)
      : undefined;

    createLogMutation.mutate(
      {
        machine_id: formData.machineId,
        maintenance_type: formData.maintenanceType,
        description: formData.description,
        parts_replaced: partsReplaced,
        duration_minutes: formData.durationMinutes ? parseInt(formData.durationMinutes, 10) : undefined,
        cost: formData.cost ? parseFloat(formData.cost) : undefined,
        date: new Date().toISOString(),
      },
      {
        onSuccess: () => {
          toast.success('Maintenance Logged', {
            description: 'The maintenance record has been saved.',
          });
          setFormData({
            machineId: machineId || '',
            maintenanceType: 'preventive',
            description: '',
            partsReplaced: '',
            durationMinutes: '',
            cost: '',
          });
          onSuccess?.();
          onClose();
        },
        onError: (error) => {
          toast.error('Failed to log maintenance', {
            description: error.message || 'Please try again.',
          });
        },
      }
    );
  };

  return (
    <Modal isOpen={isOpen} onClose={onClose} title="Log Maintenance" size="lg">
      <div className="space-y-6">
        {/* Validation Error */}
        {validationError && (
          <div className="p-3 bg-red-50 border border-red-200 rounded-lg text-red-700 text-sm">
            {validationError}
          </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-4">
          {/* Machine Selector */}
          {!machineId && (
            <div>
              <label
                htmlFor="machineId"
                className="block text-sm font-medium text-chocolate-700 mb-2"
              >
                Select Machine <span className="text-red-500">*</span>
              </label>
              <select
                id="machineId"
                value={formData.machineId}
                onChange={(e) =>
                  setFormData((prev) => ({ ...prev, machineId: e.target.value }))
                }
                className="w-full px-3 py-2 bg-white border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-2 focus:ring-chocolate-500 focus:border-chocolate-500 sm:text-sm"
                disabled={createLogMutation.isPending}
                required
              >
                <option value="">Select a machine...</option>
                {machines.map((machine: Machine) => (
                  <option key={machine.id} value={machine.id}>
                    {machine.name} ({machine.machine_code})
                  </option>
                ))}
              </select>
            </div>
          )}

          {/* Maintenance Type */}
          <div>
            <label className="block text-sm font-medium text-chocolate-700 mb-2">
              Maintenance Type <span className="text-red-500">*</span>
            </label>
            <div className="grid grid-cols-3 gap-3">
              {MAINTENANCE_TYPES.map((type) => (
                <button
                  key={type.value}
                  type="button"
                  onClick={() =>
                    setFormData((prev) => ({
                      ...prev,
                      maintenanceType: type.value as any,
                    }))
                  }
                  className={`p-3 rounded-lg border-2 transition-all text-left ${
                    formData.maintenanceType === type.value
                      ? type.value === 'emergency'
                        ? 'bg-red-50 border-red-500'
                        : type.value === 'corrective'
                        ? 'bg-amber-50 border-amber-500'
                        : 'bg-green-50 border-green-500'
                      : 'bg-white border-chocolate-200 hover:border-chocolate-400'
                  }`}
                  disabled={createLogMutation.isPending}
                >
                  <span
                    className={`font-semibold text-sm ${
                      formData.maintenanceType === type.value
                        ? type.value === 'emergency'
                          ? 'text-red-700'
                          : type.value === 'corrective'
                          ? 'text-amber-700'
                          : 'text-green-700'
                        : 'text-chocolate-700'
                    }`}
                  >
                    {type.label}
                  </span>
                  <p className="text-xs text-gray-500 mt-1">{type.description}</p>
                </button>
              ))}
            </div>
          </div>

          {/* Description */}
          <div>
            <label
              htmlFor="description"
              className="block text-sm font-medium text-chocolate-700 mb-2"
            >
              Description <span className="text-red-500">*</span>
            </label>
            <textarea
              id="description"
              rows={4}
              placeholder="Describe the maintenance work performed..."
              value={formData.description}
              onChange={(e) =>
                setFormData((prev) => ({ ...prev, description: e.target.value }))
              }
              className="w-full px-4 py-2.5 border border-chocolate-200 rounded-lg focus:ring-2 focus:ring-chocolate-500 focus:border-transparent transition-all resize-none text-chocolate-800"
              disabled={createLogMutation.isPending}
              required
            />
          </div>

          {/* Parts Replaced */}
          <div>
            <Input
              label="Parts Replaced (comma-separated, optional)"
              id="partsReplaced"
              type="text"
              placeholder="e.g., Belt, Motor, Sensor"
              value={formData.partsReplaced}
              onChange={(e) =>
                setFormData((prev) => ({ ...prev, partsReplaced: e.target.value }))
              }
              disabled={createLogMutation.isPending}
            />
          </div>

          {/* Duration and Cost */}
          <div className="grid grid-cols-2 gap-4">
            <div>
              <Input
                label="Duration (minutes)"
                id="durationMinutes"
                type="number"
                min="0"
                placeholder="e.g., 45"
                value={formData.durationMinutes}
                onChange={(e) =>
                  setFormData((prev) => ({ ...prev, durationMinutes: e.target.value }))
                }
                disabled={createLogMutation.isPending}
              />
            </div>
            <div>
              <Input
                label="Cost (optional)"
                id="cost"
                type="number"
                min="0"
                step="0.01"
                placeholder="e.g., 150.00"
                value={formData.cost}
                onChange={(e) =>
                  setFormData((prev) => ({ ...prev, cost: e.target.value }))
                }
                disabled={createLogMutation.isPending}
              />
            </div>
          </div>

          {/* Action Buttons */}
          <div className="flex items-center gap-3 pt-4 border-t">
            <Button
              type="button"
              variant="outline"
              onClick={onClose}
              disabled={createLogMutation.isPending}
              className="flex-1"
            >
              Cancel
            </Button>
            <Button
              type="submit"
              variant="default"
              isLoading={createLogMutation.isPending}
              disabled={createLogMutation.isPending}
              className="flex-1"
            >
              <Save className="w-4 h-4 mr-2" />
              Save Log
            </Button>
          </div>
        </form>
      </div>
    </Modal>
  );
};

export default MaintenanceLogModal;

import React, { useState, FormEvent } from 'react';
import { AlertTriangle, Clock, Wrench, User, CheckCircle } from 'lucide-react';
import { toast } from 'sonner';
import { Modal } from '../common/Modal';
import { Button } from '../ui/Button';
import { Input } from '../ui/Input';
import { Badge } from '../ui/Badge';
import { useMechanic } from '../../hooks/useMechanic';
import { SOSAlert } from '../../types';

export interface ResolveAlertModalProps {
  isOpen: boolean;
  onClose: () => void;
  alert: SOSAlert;
  onResolved?: () => void;
}

const ResolveAlertModal: React.FC<ResolveAlertModalProps> = ({
  isOpen,
  onClose,
  alert,
  onResolved,
}) => {
  const { useResolveAlert } = useMechanic();
  const resolveAlertMutation = useResolveAlert();

  const [formData, setFormData] = useState({
    resolutionNotes: '',
    partsUsed: '',
    timeSpent: '',
  });

  const [validationError, setValidationError] = useState('');

  const formatTimeAgo = (dateString: string): string => {
    const date = new Date(dateString);
    const now = new Date();
    const diffMs = now.getTime() - date.getTime();
    const diffMins = Math.floor(diffMs / 60000);
    const diffHours = Math.floor(diffMins / 60);
    const diffDays = Math.floor(diffHours / 24);

    if (diffDays > 0) return `${diffDays} days ago`;
    if (diffHours > 0) return `${diffHours} hours ago`;
    if (diffMins > 0) return `${diffMins} minutes ago`;
    return 'Just now';
  };

  const getPriorityVariant = (priority: string) => {
    switch (priority) {
      case 'critical':
      case 'high':
        return 'error';
      case 'medium':
        return 'warning';
      default:
        return 'default';
    }
  };

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    setValidationError('');

    if (!formData.resolutionNotes.trim()) {
      setValidationError('Resolution notes are required');
      return;
    }

    resolveAlertMutation.mutate(
      {
        id: alert.id,
        notes: formData.resolutionNotes,
      },
      {
        onSuccess: () => {
          toast.success('Alert Resolved', {
            description: 'The SOS alert has been marked as resolved.',
          });
          setFormData({
            resolutionNotes: '',
            partsUsed: '',
            timeSpent: '',
          });
          onResolved?.();
          onClose();
        },
        onError: (error) => {
          toast.error('Failed to resolve alert', {
            description: error.message || 'Please try again.',
          });
        },
      }
    );
  };

  return (
    <Modal isOpen={isOpen} onClose={onClose} title="Resolve SOS Alert" size="lg">
      <div className="space-y-6">
        {/* Alert Information */}
        <div className="bg-red-50 border border-red-200 rounded-lg p-4">
          <div className="flex items-start gap-3">
            <div className="p-2 bg-red-600 rounded-lg">
              <AlertTriangle className="w-5 h-5 text-white" />
            </div>
            <div className="flex-1">
              <div className="flex items-center gap-2 mb-2">
                <Badge variant={getPriorityVariant(alert.priority) as any} className="uppercase text-xs">
                  {alert.priority}
                </Badge>
                <span className="text-xs text-gray-500 flex items-center gap-1">
                  <Clock className="w-3 h-3" />
                  {formatTimeAgo(alert.reported_at)}
                </span>
              </div>
              <div className="flex items-center gap-2 mb-1">
                <Wrench className="w-4 h-4 text-chocolate-600" />
                <span className="font-semibold text-chocolate-800">
                  {alert.machine_name || 'Unknown Machine'}
                </span>
                {alert.machine_code && (
                  <span className="text-xs font-mono text-gray-500">
                    ({alert.machine_code})
                  </span>
                )}
              </div>
              <p className="text-sm text-gray-700 mt-2">
                {alert.problem_description}
              </p>
              <div className="flex items-center gap-1 mt-2 text-xs text-gray-500">
                <User className="w-3 h-3" />
                Reported by: {alert.reported_by_name || 'Unknown'}
              </div>
            </div>
          </div>
        </div>

        {/* Validation Error */}
        {validationError && (
          <div className="p-3 bg-red-50 border border-red-200 rounded-lg text-red-700 text-sm">
            {validationError}
          </div>
        )}

        {/* Resolution Form */}
        <form onSubmit={handleSubmit} className="space-y-4">
          {/* Resolution Notes */}
          <div>
            <label
              htmlFor="resolutionNotes"
              className="block text-sm font-medium text-chocolate-700 mb-2"
            >
              Resolution Notes <span className="text-red-500">*</span>
            </label>
            <textarea
              id="resolutionNotes"
              rows={4}
              placeholder="Describe what was done to resolve the issue..."
              value={formData.resolutionNotes}
              onChange={(e) =>
                setFormData((prev) => ({ ...prev, resolutionNotes: e.target.value }))
              }
              className="w-full px-4 py-2.5 border border-chocolate-200 rounded-lg focus:ring-2 focus:ring-chocolate-500 focus:border-transparent transition-all resize-none text-chocolate-800"
              disabled={resolveAlertMutation.isPending}
              required
            />
          </div>

          {/* Parts Used */}
          <div>
            <Input
              label="Parts Used (optional)"
              id="partsUsed"
              type="text"
              placeholder="e.g., Belt, Motor, Sensor..."
              value={formData.partsUsed}
              onChange={(e) =>
                setFormData((prev) => ({ ...prev, partsUsed: e.target.value }))
              }
              disabled={resolveAlertMutation.isPending}
            />
          </div>

          {/* Time Spent */}
          <div>
            <Input
              label="Time Spent (minutes, optional)"
              id="timeSpent"
              type="number"
              min="0"
              placeholder="e.g., 45"
              value={formData.timeSpent}
              onChange={(e) =>
                setFormData((prev) => ({ ...prev, timeSpent: e.target.value }))
              }
              disabled={resolveAlertMutation.isPending}
            />
          </div>

          {/* Action Buttons */}
          <div className="flex items-center gap-3 pt-4 border-t">
            <Button
              type="button"
              variant="outline"
              onClick={onClose}
              disabled={resolveAlertMutation.isPending}
              className="flex-1"
            >
              Cancel
            </Button>
            <Button
              type="submit"
              variant="success"
              isLoading={resolveAlertMutation.isPending}
              disabled={resolveAlertMutation.isPending}
              className="flex-1"
            >
              <CheckCircle className="w-4 h-4 mr-2" />
              Mark as Resolved
            </Button>
          </div>
        </form>
      </div>
    </Modal>
  );
};

export default ResolveAlertModal;

import React from 'react';
import { Clock, User, Wrench, AlertTriangle } from 'lucide-react';
import { Badge } from '../ui/Badge';
import { Button } from '../ui/Button';
import { SOSAlert, AlertPriority, AlertStatus } from '../../types';

export interface SOSAlertCardProps {
  alert: SOSAlert;
  onRespond?: () => void;
  onResolve?: () => void;
  compact?: boolean;
}

const SOSAlertCard: React.FC<SOSAlertCardProps> = ({
  alert,
  onRespond,
  onResolve,
  compact = false,
}) => {
  const formatTimeAgo = (dateString: string): string => {
    const date = new Date(dateString);
    const now = new Date();
    const diffMs = now.getTime() - date.getTime();
    const diffMins = Math.floor(diffMs / 60000);
    const diffHours = Math.floor(diffMins / 60);
    const diffDays = Math.floor(diffHours / 24);

    if (diffDays > 0) return `${diffDays}d ago`;
    if (diffHours > 0) return `${diffHours}h ago`;
    if (diffMins > 0) return `${diffMins}m ago`;
    return 'Just now';
  };

  const getPriorityConfig = (priority: AlertPriority) => {
    switch (priority) {
      case 'critical':
        return {
          variant: 'error' as const,
          className: 'animate-pulse bg-red-600',
          borderColor: 'border-red-500',
          bgColor: 'bg-red-50',
        };
      case 'high':
        return {
          variant: 'error' as const,
          className: 'bg-red-500',
          borderColor: 'border-red-400',
          bgColor: 'bg-red-50',
        };
      case 'medium':
        return {
          variant: 'warning' as const,
          className: 'bg-amber-500',
          borderColor: 'border-amber-400',
          bgColor: 'bg-amber-50',
        };
      case 'low':
        return {
          variant: 'default' as const,
          className: 'bg-gray-400',
          borderColor: 'border-gray-300',
          bgColor: 'bg-gray-50',
        };
      default:
        return {
          variant: 'default' as const,
          className: 'bg-gray-400',
          borderColor: 'border-gray-300',
          bgColor: 'bg-gray-50',
        };
    }
  };

  const getStatusVariant = (status: AlertStatus) => {
    switch (status) {
      case 'open':
        return 'error';
      case 'assigned':
        return 'warning';
      case 'in_progress':
        return 'warning';
      case 'resolved':
        return 'success';
      case 'closed':
        return 'default';
      default:
        return 'default';
    }
  };

  const priorityConfig = getPriorityConfig(alert.priority);

  if (compact) {
    return (
      <div
        className={`p-3 rounded-lg border-l-4 ${priorityConfig.borderColor} ${priorityConfig.bgColor} bg-white shadow-sm hover:shadow-md transition-shadow cursor-pointer`}
        onClick={onRespond}
      >
        <div className="flex items-start justify-between gap-2">
          <div className="flex-1 min-w-0">
            <div className="flex items-center gap-2 mb-1">
              <Badge variant={priorityConfig.variant} className="text-xs uppercase">
                {alert.priority}
              </Badge>
              <span className="text-xs text-gray-500 flex items-center gap-1">
                <Clock className="w-3 h-3" />
                {formatTimeAgo(alert.reported_at)}
              </span>
            </div>
            <p className="font-medium text-chocolate-800 text-sm truncate">
              {alert.machine_name || 'Unknown Machine'}
            </p>
            <p className="text-xs text-gray-600 truncate">
              {alert.problem_description}
            </p>
          </div>
          {alert.status === 'open' && onRespond && (
            <Button
              variant="destructive"
              size="sm"
              className="flex-shrink-0 text-xs h-7"
              onClick={(e) => {
                e.stopPropagation();
                onRespond();
              }}
            >
              Respond
            </Button>
          )}
        </div>
      </div>
    );
  }

  return (
    <div
      className={`p-4 rounded-xl border-2 ${priorityConfig.borderColor} ${priorityConfig.bgColor} shadow-sm hover:shadow-md transition-all`}
    >
      {/* Header */}
      <div className="flex items-start justify-between mb-3">
        <div className="flex items-center gap-2">
          <div className={`p-2 rounded-lg ${priorityConfig.className}`}>
            <AlertTriangle className="w-4 h-4 text-white" />
          </div>
          <div>
            <div className="flex items-center gap-2">
              <Badge variant={priorityConfig.variant} className="uppercase text-xs">
                {alert.priority}
              </Badge>
              <Badge variant={getStatusVariant(alert.status) as any} className="text-xs">
                {alert.status.replace('_', ' ')}
              </Badge>
            </div>
            <p className="text-xs text-gray-500 mt-1 flex items-center gap-1">
              <Clock className="w-3 h-3" />
              {formatTimeAgo(alert.reported_at)}
            </p>
          </div>
        </div>
      </div>

      {/* Machine Info */}
      <div className="mb-3">
        <div className="flex items-center gap-2 mb-1">
          <Wrench className="w-4 h-4 text-chocolate-600" />
          <span className="font-semibold text-chocolate-800">
            {alert.machine_name || 'Unknown Machine'}
          </span>
          {alert.machine_code && (
            <span className="text-xs font-mono text-gray-500">
              ({alert.machine_code})
            </span>
          )}
        </div>
      </div>

      {/* Problem Description */}
      <div className="mb-3">
        <p className="text-sm text-gray-700 line-clamp-2">
          {alert.problem_description}
        </p>
      </div>

      {/* Reporter Info */}
      <div className="flex items-center gap-4 text-xs text-gray-500 mb-4">
        <span className="flex items-center gap-1">
          <User className="w-3 h-3" />
          Reported by: {alert.reported_by_name || 'Unknown'}
        </span>
        {alert.assigned_to_name && (
          <span className="flex items-center gap-1">
            <Wrench className="w-3 h-3" />
            Assigned: {alert.assigned_to_name}
          </span>
        )}
      </div>

      {/* Resolution Notes (if resolved) */}
      {alert.status === 'resolved' && alert.resolution_notes && (
        <div className="p-3 bg-green-50 rounded-lg border border-green-200 mb-4">
          <p className="text-xs font-medium text-green-700 mb-1">Resolution Notes:</p>
          <p className="text-sm text-green-800">{alert.resolution_notes}</p>
        </div>
      )}

      {/* Actions */}
      <div className="flex items-center gap-2">
        {alert.status === 'open' && onRespond && (
          <Button
            variant="destructive"
            size="sm"
            className="flex-1"
            onClick={onRespond}
          >
            Assign to Me
          </Button>
        )}
        {(alert.status === 'assigned' || alert.status === 'in_progress') && onResolve && (
          <Button
            variant="success"
            size="sm"
            className="flex-1"
            onClick={onResolve}
          >
            Resolve
          </Button>
        )}
        {onRespond && alert.status !== 'open' && (
          <Button
            variant="outline"
            size="sm"
            className="flex-1"
            onClick={onRespond}
          >
            View Details
          </Button>
        )}
      </div>
    </div>
  );
};

