import { useState, useEffect } from 'react';
import { useTranslate, MULTILINGUAL_PHRASES } from '../../services/aiService';
import { Button } from '../ui/Button';
import { Modal } from '../common/Modal'; // Using common Modal component
import { Loader2, Languages, Volume2, Check } from 'lucide-react';

interface InstructionClarifierProps {
  instruction: string;
  stepNumber: number;
}

export function InstructionClarifier({ instruction, stepNumber }: InstructionClarifierProps) {
  const [showTranslation, setShowTranslation] = useState(false);
  const [workerLanguage, setWorkerLanguage] = useState('am'); // Default to Amharic for demo
  const { mutate: translate, isPending, data } = useTranslate();
  const [isSpeaking, setIsSpeaking] = useState(false);

  // Effect to clean up speech synthesis when component unmounts or modal closes
  useEffect(() => {
    if (!showTranslation) {
      window.speechSynthesis.cancel();
      setIsSpeaking(false);
    }
    return () => {
      window.speechSynthesis.cancel();
    };
  }, [showTranslation]);

  const handleExplain = (e: React.MouseEvent) => {
    e.stopPropagation(); // Prevent card click
    console.log('InstructionClarifier: handleExplain clicked', { instruction, stepNumber });
    setShowTranslation(true);
    
    // Initial translation if not already done or if language changed
    if (!data) {
        console.log('InstructionClarifier: requesting initial translation', { workerLanguage });
        requestTranslation(workerLanguage);
    }
  };

  const requestTranslation = (lang: string) => {
    console.log('InstructionClarifier: requestTranslation called', { lang, instruction });
    translate({
        text: instruction,
        targetLanguage: lang,
        context: { domain: 'recipe' }
      });
  };

  const handleLanguageChange = (lang: string) => {
    setWorkerLanguage(lang);
    requestTranslation(lang);
  };

  const handleSpeak = () => {
    if (isSpeaking) {
        window.speechSynthesis.cancel();
        setIsSpeaking(false);
        return;
    }

    const textToSpeak = data ?? instruction;
    const utterance = new SpeechSynthesisUtterance(textToSpeak);
    
    // Set voice/lang based on workerLanguage if possible
    // Note: Browser support for specific voices varies
    utterance.lang = workerLanguage === 'am' ? 'am-ET' : 
                     workerLanguage === 'ar' ? 'ar-SA' : 
                     workerLanguage === 'ru' ? 'ru-RU' : 'en-US';

    utterance.onend = () => setIsSpeaking(false);
    utterance.onerror = () => setIsSpeaking(false);

    setIsSpeaking(true);
    window.speechSynthesis.speak(utterance);
  };

  return (
    <>
      <Button 
        onClick={handleExplain} 
        variant="ghost" 
        size="sm"
        className="text-xs text-blue-600 hover:text-blue-800 hover:bg-blue-50 p-1 h-auto"
        title="Explain in my language"
      >
        <Languages className="h-3 w-3 mr-1" /> Explain
      </Button>

      <Modal 
        isOpen={showTranslation} 
        onClose={() => setShowTranslation(false)}
        title={`Step ${stepNumber} Translation`}
      >
        <div className="space-y-4">
            <div className="bg-slate-50 p-3 rounded-lg border border-slate-200">
                <p className="text-xs text-slate-500 mb-1 uppercase tracking-wider">Original (English)</p>
                <p className="text-slate-800">{instruction}</p>
            </div>
            
            <div className="flex justify-center">
                <div className="bg-blue-50 text-blue-600 rounded-full p-2">
                    <Languages className="h-5 w-5" />
                </div>
            </div>

            <div className="bg-blue-50 p-4 rounded-lg border border-blue-100">
                <div className="flex justify-between items-center mb-2">
                    <p className="text-xs text-blue-600 font-bold uppercase tracking-wider">
                        {workerLanguage === 'am' ? '🇪🇹 Amharic' : 
                         workerLanguage === 'ar' ? '🇸🇦 Arabic' :
                         workerLanguage === 'ru' ? '🇷🇺 Russian' : 'Translated'}
                    </p>
                    <div className="flex gap-1">
                        <button onClick={() => handleLanguageChange('am')} className={`text-xs px-2 py-1 rounded transition-all ${workerLanguage === 'am' ? 'bg-white shadow-sm scale-110 font-bold' : 'opacity-50 hover:opacity-100'}`}>🇪🇹</button>
                        <button onClick={() => handleLanguageChange('ar')} className={`text-xs px-2 py-1 rounded transition-all ${workerLanguage === 'ar' ? 'bg-white shadow-sm scale-110 font-bold' : 'opacity-50 hover:opacity-100'}`}>🇸🇦</button>
                        <button onClick={() => handleLanguageChange('ru')} className={`text-xs px-2 py-1 rounded transition-all ${workerLanguage === 'ru' ? 'bg-white shadow-sm scale-110 font-bold' : 'opacity-50 hover:opacity-100'}`}>🇷🇺</button>
                    </div>
                </div>
                
                {isPending ? (
                    <div className="flex items-center justify-center py-4 text-blue-600">
                        <Loader2 className="h-5 w-5 animate-spin mr-2" /> 
                        {MULTILINGUAL_PHRASES[workerLanguage]?.thinking || 'Translating...'}
                    </div>
                ) : (
                    <p className="text-lg font-medium text-slate-900 leading-relaxed" dir={workerLanguage === 'ar' ? 'rtl' : 'ltr'}>
                        {data ?? "Translation unavailable."}
                    </p>
                )}
            </div>

            <div className="flex gap-2 justify-end pt-2">
                <Button 
                    variant={isSpeaking ? "default" : "outline"} 
                    size="sm" 
                    onClick={handleSpeak} 
                    disabled={isPending || !data}
                    className={isSpeaking ? "bg-blue-100 text-blue-700 border-blue-200 animate-pulse" : ""}
                >
                    <Volume2 className={`h-4 w-4 mr-1 ${isSpeaking ? "animate-bounce" : ""}`} /> 
                    {isSpeaking ? "Speaking..." : "Read Aloud"}
                </Button>
                <Button size="sm" onClick={() => setShowTranslation(false)} className="bg-green-600 hover:bg-green-700">
                    <Check className="h-4 w-4 mr-1" /> Got it
                </Button>
            </div>
        </div>
      </Modal>
    </>
  );
}

import React, { useState } from 'react';
import { Eye, Star, ExternalLink } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { Button } from '../ui/Button';
import { Badge } from '../ui/Badge';
import QCDetailModal from './QCDetailModal';
import { QCCheck } from '../../types';

interface QCHistoryTableProps {
  qcChecks: QCCheck[];
  loading: boolean;
}

const QCHistoryTable: React.FC<QCHistoryTableProps> = ({
  qcChecks,
  loading,
}) => {
  const navigate = useNavigate();
  const [selectedQCId, setSelectedQCId] = useState<string | null>(null);
  const [isDetailModalOpen, setIsDetailModalOpen] = useState(false);

  const formatTimeAgo = (dateString: string): string => {
    const date = new Date(dateString);
    const now = new Date();
    const diffMs = now.getTime() - date.getTime();
    const diffMins = Math.floor(diffMs / 60000);
    const diffHours = Math.floor(diffMins / 60);
    const diffDays = Math.floor(diffHours / 24);

    if (diffDays > 0) return `${diffDays}d ago`;
    if (diffHours > 0) return `${diffHours}h ago`;
    if (diffMins > 0) return `${diffMins}m ago`;
    return 'Just now';
  };

  const getResultVariant = (result: string) => {
    switch (result) {
      case 'approved': return 'success';
      case 'rejected': return 'error';
      case 'quarantine': return 'warning';
      default: return 'default';
    }
  };

  const getResultLabel = (result: string) => {
      switch (result) {
        case 'approved': return 'Approved';
        case 'rejected': return 'Rejected';
        case 'quarantine': return 'Quarantine';
        default: return result;
      }
    };

  const getRowColor = (result: string) => {
    switch (result) {
      case 'approved':
        return 'hover:bg-green-50/50';
      case 'rejected':
        return 'hover:bg-red-50/50';
      case 'quarantine':
        return 'hover:bg-amber-50/50';
      default:
        return 'hover:bg-chocolate-50/50';
    }
  };

  const handleViewQC = (qcId: string) => {
    setSelectedQCId(qcId);
    setIsDetailModalOpen(true);
  };

  const ScoreDisplay: React.FC<{ score: number }> = ({ score }) => (
    <div className="flex items-center gap-1">
      {[1, 2, 3, 4, 5].map((star) => (
        <Star
          key={star}
          className={`w-3.5 h-3.5 ${
            star <= score
              ? 'text-gold-500 fill-gold-500'
              : 'text-chocolate-200'
          }`}
        />
      ))}
      <span className="ml-1 text-sm font-medium text-chocolate-700">
        {score}
      </span>
    </div>
  );

  if (loading) {
    return (
      <div className="overflow-x-auto p-6">
        <div className="space-y-4 animate-pulse">
             {[...Array(5)].map((_, i) => (
                 <div key={i} className="h-12 bg-gray-100 rounded-lg w-full"></div>
             ))}
        </div>
      </div>
    );
  }

  if (qcChecks.length === 0) {
    return (
      <div className="p-12 text-center">
        <Eye className="w-16 h-16 text-chocolate-300 mx-auto mb-4" />
        <h3 className="text-lg font-semibold text-chocolate-800 mb-2">
          No inspections yet
        </h3>
        <p className="text-chocolate-600">
          Submit your first QC inspection using the form above
        </p>
      </div>
    );
  }

  return (
    <>
      <div className="overflow-x-auto">
        <table className="w-full">
          <thead className="bg-chocolate-50 border-b border-chocolate-200">
            <tr>
              <th className="px-6 py-4 text-left text-xs font-semibold text-chocolate-700 uppercase">
                Batch
              </th>
              <th className="px-6 py-4 text-left text-xs font-semibold text-chocolate-700 uppercase">
                Inspector
              </th>
              <th className="px-6 py-4 text-left text-xs font-semibold text-chocolate-700 uppercase">
                Date/Time
              </th>
              <th className="px-6 py-4 text-left text-xs font-semibold text-chocolate-700 uppercase">
                Appearance
              </th>
              <th className="px-6 py-4 text-left text-xs font-semibold text-chocolate-700 uppercase">
                Texture
              </th>
              <th className="px-6 py-4 text-left text-xs font-semibold text-chocolate-700 uppercase">
                Taste
              </th>
              <th className="px-6 py-4 text-left text-xs font-semibold text-chocolate-700 uppercase">
                Result
              </th>
              <th className="px-6 py-4 text-left text-xs font-semibold text-chocolate-700 uppercase">
                Defects
              </th>
              <th className="px-6 py-4 text-right text-xs font-semibold text-chocolate-700 uppercase">
                Actions
              </th>
            </tr>
          </thead>
          <tbody className="bg-white divide-y divide-chocolate-100">
            {qcChecks.map((qc) => {
              const resultVariant = getResultVariant(qc.result);
              return (
                <tr
                  key={qc.id}
                  className={`transition-colors ${getRowColor(qc.result)}`}
                >
                  <td className="px-6 py-4">
                    <button
                      onClick={() => navigate(`/production/batches/${qc.batch_id}`)}
                      className="font-mono text-chocolate-700 hover:text-chocolate-900 hover:underline flex items-center gap-1 bg-white px-2 py-1 rounded border border-chocolate-100"
                    >
                      {qc.batch_number}
                      <ExternalLink className="w-3 h-3" />
                    </button>
                  </td>
                  <td className="px-6 py-4">
                    <span className="text-chocolate-800 text-sm font-medium">
                      {qc.inspector_name}
                    </span>
                  </td>
                  <td className="px-6 py-4">
                    <span className="text-sm text-chocolate-600">
                      {formatTimeAgo(qc.inspection_date)}
                    </span>
                  </td>
                  <td className="px-6 py-4">
                    <ScoreDisplay score={qc.appearance_score || 0} />
                  </td>
                  <td className="px-6 py-4">
                    <ScoreDisplay score={qc.texture_score || 0} />
                  </td>
                  <td className="px-6 py-4">
                    <ScoreDisplay score={qc.taste_score || 0} />
                  </td>
                  <td className="px-6 py-4">
                    <Badge variant={resultVariant}>
                      {getResultLabel(qc.result)}
                    </Badge>
                  </td>
                  <td className="px-6 py-4">
                    <span
                      className={`font-semibold ${
                        qc.defect_count > 0 ? 'text-red-600' : 'text-green-600'
                      }`}
                    >
                      {qc.defect_count}
                    </span>
                  </td>
                  <td className="px-6 py-4 text-right">
                    <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => handleViewQC(qc.id)}
                    className="h-8 w-8 text-chocolate-400 hover:text-chocolate-700"
                    title="View Details"
                    >
                        <Eye className="w-4 h-4" />
                    </Button>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      {/* QC Detail Modal */}
      {selectedQCId && (
        <QCDetailModal
          isOpen={isDetailModalOpen}
          onClose={() => {
            setIsDetailModalOpen(false);
            setSelectedQCId(null);
          }}
          qcCheckId={selectedQCId}
        />
      )}
    </>
  );
};

export default QCHistoryTable;

import React, { useState, FormEvent } from 'react';
import { Star, ThermometerSun, Droplets, AlertTriangle } from 'lucide-react';
import { Button } from '../ui/Button';
import { Input } from '../ui/Input';
import { Alert } from '../ui/Alert';
import { useQC } from '../../hooks/useQC';
import { useProduction } from '../../hooks/useProduction'; // Fixed import

interface QCInspectionFormProps {
  onSuccess?: () => void;
}

const DEFECT_TYPES = [
  'Discoloration',
  'Cracks',
  'Air bubbles',
  'Uneven coating',
  'Wrong size',
  'Contamination',
  'Melting',
  'Blooming',
  'Surface Scuffs',
  'Misshapen',
  'Other',
];

const QCInspectionForm: React.FC<QCInspectionFormProps> = ({ onSuccess }) => {
  const { useCreateQCCheck } = useQC();
  const { useBatches } = useProduction();
  const createQCMutation = useCreateQCCheck();
  
  // Only fetch completed or packaging batches for QC
  const { data: batchesData } = useBatches({ status: 'completed' }); 
  const batches = batchesData?.batches || [];

  const [formData, setFormData] = useState({
    batchId: '', // Changed to select from dropdown
    appearanceScore: 5,
    textureScore: 5,
    tasteScore: 5,
    temperature: '',
    humidity: '',
    defectCount: '0',
    defectTypes: [] as string[],
    result: 'approved' as const,
    notes: '',
  });

  const [validationError, setValidationError] = useState('');

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    setValidationError('');

    // Validation
    if (!formData.batchId.trim()) {
      setValidationError('Batch selection is required');
      return;
    }

    if (
      formData.appearanceScore < 1 ||
      formData.appearanceScore > 5 ||
      formData.textureScore < 1 ||
      formData.textureScore > 5 ||
      formData.tasteScore < 1 ||
      formData.tasteScore > 5
    ) {
      setValidationError('All scores must be between 1 and 5');
      return;
    }

    const defectCount = parseInt(formData.defectCount, 10);
    if (isNaN(defectCount) || defectCount < 0) {
      setValidationError('Defect count must be a positive number');
      return;
    }

    // Submit QC check
    createQCMutation.mutate(
      {
        batchId: formData.batchId,
        appearance_score: formData.appearanceScore,
        texture_score: formData.textureScore,
        taste_score: formData.tasteScore,
        temperature: formData.temperature ? parseFloat(formData.temperature) : undefined,
        humidity: formData.humidity ? parseFloat(formData.humidity) : undefined,
        defect_count: defectCount,
        defects: formData.defectTypes.map(t => ({ defect_type: t, severity: 'minor' })),
        result: formData.result,
        notes: formData.notes,
      },
      {
        onSuccess: () => {
          // Reset form
          setFormData({
            batchId: '',
            appearanceScore: 5,
            textureScore: 5,
            tasteScore: 5,
            temperature: '',
            humidity: '',
            defectCount: '0',
            defectTypes: [],
            result: 'approved',
            notes: '',
          });
          onSuccess?.();
        },
      }
    );
  };

  const handleScoreChange = (field: string, value: number) => {
    setFormData((prev) => ({ ...prev, [field]: value }));
  };

  const toggleDefectType = (defectType: string) => {
    setFormData((prev) => ({
      ...prev,
      defectTypes: prev.defectTypes.includes(defectType)
        ? prev.defectTypes.filter((d) => d !== defectType)
        : [...prev.defectTypes, defectType],
    }));
  };

  const StarRating: React.FC<{
    value: number;
    onChange: (value: number) => void;
    label: string;
  }> = ({ value, onChange, label }) => (
    <div>
      <label className="block text-sm font-medium text-chocolate-700 mb-2">
        {label}
      </label>
      <div className="flex items-center gap-2">
        {[1, 2, 3, 4, 5].map((star) => (
          <button
            key={star}
            type="button"
            onClick={() => onChange(star)}
            className="transition-transform hover:scale-110 focus:outline-none focus:scale-110 active:scale-95"
            disabled={createQCMutation.isPending}
          >
            <Star
              className={`w-8 h-8 transition-colors duration-200 ${
                star <= value
                  ? 'text-gold-500 fill-gold-500 drop-shadow-sm'
                  : 'text-chocolate-100 fill-chocolate-50'
              }`}
            />
          </button>
        ))}
        <span className="ml-2 text-lg font-semibold text-chocolate-800">
          {value}/5
        </span>
      </div>
    </div>
  );

  return (
    <div>
      {/* Success Message */}
      {createQCMutation.isSuccess && (
        <Alert variant="success" className="mb-4">
          <h4 className="font-bold">QC Inspection Submitted</h4>
          <p>The inspection data has been recorded successfully.</p>
        </Alert>
      )}

      {/* Error Message */}
      {createQCMutation.error && (
        <Alert variant="error" className="mb-4">
          <h4 className="font-bold">Submission Failed</h4>
          <p>{createQCMutation.error.message || 'Failed to submit QC inspection'}</p>
        </Alert>
      )}

      {/* Validation Error */}
      {validationError && (
        <Alert variant="error" className="mb-4">
          <h4 className="font-bold">Validation Error</h4>
          <p>{validationError}</p>
        </Alert>
      )}

      <form onSubmit={handleSubmit} className="space-y-6">
        {/* Batch Number */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div className="space-y-2">
            <label
              htmlFor="batchId"
              className="block text-sm font-medium text-chocolate-700"
            >
              Select Batch *
            </label>
            <select
              id="batchId"
              value={formData.batchId}
              onChange={(e) =>
                setFormData((prev) => ({ ...prev, batchId: e.target.value }))
              }
              className="w-full px-4 py-3 bg-white border border-chocolate-100 rounded-xl shadow-sm focus:outline-none focus:ring-2 focus:ring-chocolate-500/20 focus:border-chocolate-500 sm:text-sm transition-all hover:border-chocolate-300"
              disabled={createQCMutation.isPending}
              required
            >
              <option value="">Select a batch...</option>
              {batches.map((batch) => (
                <option key={batch.id} value={batch.id}>
                  {batch.batch_number || batch.id.slice(0, 8)} - {batch.recipe_name}
                </option>
              ))}
            </select>
          </div>

          <div>
             <Input
              label="Defect Count"
              id="defectCount"
              type="number"
              min="0"
              step="1"
              placeholder="0"
              value={formData.defectCount}
              onChange={(e) =>
                setFormData((prev) => ({ ...prev, defectCount: e.target.value }))
              }
              disabled={createQCMutation.isPending}
            />
          </div>
        </div>

        {/* Quality Scores */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-8 p-8 bg-white/50 backdrop-blur-sm rounded-3xl border border-chocolate-100/50 shadow-sm relative overflow-hidden">
          <div className="absolute top-0 right-0 w-64 h-64 bg-gold-500/5 rounded-full blur-3xl -z-10" />
          <StarRating
            label="Appearance Score *"
            value={formData.appearanceScore}
            onChange={(value) => handleScoreChange('appearanceScore', value)}
          />
          <StarRating
            label="Texture Score *"
            value={formData.textureScore}
            onChange={(value) => handleScoreChange('textureScore', value)}
          />
          <StarRating
            label="Taste Score *"
            value={formData.tasteScore}
            onChange={(value) => handleScoreChange('tasteScore', value)}
          />
        </div>

        {/* Environmental Conditions */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div>
            <div className="flex items-center gap-2 mb-2 text-sm font-medium text-chocolate-700">
                <ThermometerSun className="w-4 h-4" />
                Temperature (°C)
            </div>
            <Input
              id="temperature"
              type="number"
              step="0.1"
              placeholder="e.g., 22.5"
              value={formData.temperature}
              onChange={(e) =>
                setFormData((prev) => ({ ...prev, temperature: e.target.value }))
              }
              disabled={createQCMutation.isPending}
            />
          </div>

          <div>
             <div className="flex items-center gap-2 mb-2 text-sm font-medium text-chocolate-700">
                <Droplets className="w-4 h-4" />
                Humidity (%)
            </div>
            <Input
              id="humidity"
              type="number"
              step="0.1"
