              >
                {defectType}
              </button>
            ))}
          </div>
        </div>

        {/* Result */}
        <div>
          <label className="block text-sm font-medium text-chocolate-700 mb-3">
            Inspection Result *
          </label>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            {[
              { value: 'approved', label: 'Approved', icon: '✅', color: 'green' },
              { value: 'rejected', label: 'Rejected', icon: '❌', color: 'red' },
              {
                value: 'quarantine',
                label: 'Quarantine',
                icon: '⚠️',
                color: 'amber',
              },
            ].map((option) => (
              <button
                key={option.value}
                type="button"
                onClick={() =>
                  setFormData((prev) => ({ ...prev, result: option.value as any }))
                }
                className={`p-6 rounded-2xl border transition-all duration-300 group relative overflow-hidden ${
                  formData.result === option.value
                    ? `bg-${option.color}-50 border-${option.color}-200 shadow-lg ring-1 ring-${option.color}-200`
                    : 'bg-white border-chocolate-100 hover:border-chocolate-300 hover:shadow-md'
                }`}
                disabled={createQCMutation.isPending}
              >
                <span className="text-3xl mb-3 block transform group-hover:scale-110 transition-transform duration-200">{option.icon}</span>
                <span
                  className={`font-bold uppercase tracking-wide text-sm ${
                    formData.result === option.value
