  title,
  description,
  icon,
  variant = 'default',
  action,
  secondaryAction,
  className,
  children,
}) => {
  const Icon = icon || variantIcons[variant];
  const iconColor = variantColors[variant];

  return (
    <div
      className={cn(
        'flex flex-col items-center justify-center py-12 px-4 text-center',
        className
      )}
    >
      <div
        className={cn(
