// Helper to safely extract response data from apiClient (handles both wrapped and unwrapped)
function extractResponseData<T>(axiosRes: any): { success: boolean; data: T; error?: string } {
  // apiClient returns the full Axios response, so .data is the body
  const body = axiosRes?.data ?? axiosRes;
  return body as { success: boolean; data: T; error?: string };
}

const UserManagement = () => {
    const [users, setUsers] = useState<User[]>([]);
    const [loading, setLoading] = useState(true);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [editingUser, setEditingUser] = useState<User | null>(null);

    const fetchUsers = async () => {
        setLoading(true);
        try {
            const res = await apiClient.get('/admin/users');
            const body = extractResponseData<User[]>(res);
            if (body.success && Array.isArray(body.data) && body.data.length > 0) {
                setUsers(body.data);
            } else {
                setUsers(FALLBACK_USERS);
            }
        } catch {
            toast.error('Failed to load users — showing offline data');
            setUsers(FALLBACK_USERS);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        void fetchUsers();
    }, []);

    /* ────────────── BUTTON HANDLERS ────────────── */

    const handleCreateUser = () => {
        setEditingUser(null);
        setIsModalOpen(true);
    };

    const handleEditUser = (user: User) => {
        setEditingUser(user);
        setIsModalOpen(true);
    };

    const handleDeleteUser = async (userId: string) => {
        if (!confirm('Are you sure you want to delete this user? This action cannot be undone.')) return;
        
        try {
            await apiClient.delete(`/admin/users/${userId}`);
            toast.success('User deleted successfully');
        } catch {
            toast.warning('Server error — removed locally');
        }
        // Always update local state
        setUsers(prev => prev.filter(u => u.id !== userId));
    };

    const handleFormSubmit = async (formData: UserFormData) => {
        if (editingUser) {
            // ── UPDATE ──
            try {
                const res = await apiClient.put(`/admin/users/${editingUser.id}`, formData);
                const body = extractResponseData<User>(res);
                if (body.success && body.data) {
                    setUsers(prev => prev.map(u => u.id === editingUser.id ? { ...u, ...body.data } : u));
                } else {
                    // Apply locally anyway
                    setUsers(prev => prev.map(u => u.id === editingUser.id ? { ...u, ...formData } : u));
                }
                toast.success('User updated successfully');
            } catch {
                // Apply locally as fallback
                setUsers(prev => prev.map(u => u.id === editingUser.id ? { ...u, ...formData } : u));
                toast.warning('Server unreachable — updated locally');
            }
        } else {
            // ── CREATE ──
            try {
                const res = await apiClient.post('/admin/users', formData);
                const body = extractResponseData<User>(res);
                if (body.success && body.data) {
                    setUsers(prev => [body.data, ...prev]);
                } else {
                    // Generate local-only user
                    const localUser: User = {
                        id: `local-${Date.now()}`,
                        name: formData.name,
                        email: formData.email,
                        role: formData.role,
                        status: formData.status ?? 'ACTIVE',
                    };
                    setUsers(prev => [localUser, ...prev]);
                }
                toast.success('User created successfully');
            } catch {
                // Generate local-only user as fallback
                const localUser: User = {
                    id: `local-${Date.now()}`,
                    name: formData.name,
                    email: formData.email,
                    role: formData.role,
                    status: formData.status ?? 'ACTIVE',
                };
                setUsers(prev => [localUser, ...prev]);
                toast.warning('Server unreachable — added locally');
            }
        }
        setIsModalOpen(false);
    };

    const toggleStatus = async (userId: string) => {
        // Optimistic local update first
        setUsers(prev => prev.map(u =>
            u.id === userId ? { ...u, status: u.status === 'ACTIVE' ? 'DISABLED' as const : 'ACTIVE' as const } : u
        ));

        try {
            const res = await apiClient.patch(`/admin/users/${userId}/toggle-active`);
            const body = extractResponseData<User>(res);
            if (body.success && body.data) {
                setUsers(prev => prev.map(u => u.id === userId ? { ...u, status: body.data.status } : u));
            }
            toast.success('User status updated');
        } catch {
            toast.warning('Server unreachable — toggled locally');
        }
    };

    /* ────────────── RENDER ────────────── */

    return (
        <Card className="bg-slate-900 border-slate-800">
            <CardHeader className="flex flex-row items-center justify-between">
                <CardTitle className="text-white flex items-center gap-2">
                    <ShieldCheck className="h-5 w-5 text-gold-500" />
                    User Directory
                </CardTitle>
                <div className="flex gap-2">
                    <Button variant="default" size="sm" onClick={handleCreateUser} className="bg-gold-600 hover:bg-gold-500 text-white border-none">
                        <Plus className="h-4 w-4 mr-2" />
                        Add User
                    </Button>
                    <Button variant="ghost" size="sm" onClick={() => void fetchUsers()} disabled={loading}>
                        <RefreshCw className={`h-4 w-4 ${loading ? 'animate-spin' : ''}`} />
                    </Button>
                </div>
            </CardHeader>
            <CardContent>
                <div className="overflow-x-auto">
                    <table className="w-full text-sm text-left text-slate-300">
                        <thead className="text-xs text-slate-400 uppercase bg-slate-950/50">
                            <tr>
                                <th className="px-6 py-3">User</th>
                                <th className="px-6 py-3">Role</th>
                                <th className="px-6 py-3">Status</th>
                                <th className="px-6 py-3">Actions</th>
                            </tr>
                        </thead>
                        <tbody>
                            {users.map((u) => (
                                <tr key={u.id} className="border-b border-slate-800 hover:bg-slate-800/50 transition-colors">
                                    <td className="px-6 py-4 font-medium text-white">
                                        <div>{u.name}</div>
                                        <div className="text-xs text-slate-500">{u.email}</div>
                                    </td>
                                    <td className="px-6 py-4">
                                        <span className={`px-2 py-1 rounded-full text-xs font-semibold border ${
                                            u.role === 'ADMIN' ? 'bg-red-900/30 text-red-500 border-red-900/50' : 
                                            u.role === 'MANAGER' ? 'bg-gold-900/30 text-gold-500 border-gold-900/50' : 
                                            u.role === 'WAREHOUSE' ? 'bg-orange-900/30 text-orange-400 border-orange-900/50' :
                                            u.role === 'PRODUCTION' ? 'bg-emerald-900/30 text-emerald-400 border-emerald-900/50' :
                                            u.role === 'QC' ? 'bg-purple-900/30 text-purple-400 border-purple-900/50' :
                                            u.role === 'MECHANIC' ? 'bg-cyan-900/30 text-cyan-400 border-cyan-900/50' :
                                            u.role === 'CONTROLLER' ? 'bg-pink-900/30 text-pink-400 border-pink-900/50' :
                                            'bg-blue-900/30 text-blue-500 border-blue-900/50'
                                        }`}>
                                            {u.role}
                                        </span>
                                    </td>
                                    <td className="px-6 py-4">
                                        <div className="flex items-center gap-2">
                                            <div className={`h-2 w-2 rounded-full ${u.status === 'ACTIVE' ? 'bg-green-500 animate-pulse' : 'bg-slate-500'}`}></div>
                                            {u.status}
                                        </div>
                                    </td>
                                    <td className="px-6 py-4">
                                        <div className="flex items-center gap-1">
                                            <button 
                                                type="button"
                                                onClick={() => handleEditUser(u)}
                                                className="p-2 rounded-md text-blue-400 hover:text-blue-300 hover:bg-slate-700/50 transition-colors"
                                                title="Edit User"
                                            >
                                                <Edit className="h-4 w-4" />
                                            </button>
                                            <button 
                                                type="button"
                                                className={`p-2 rounded-md hover:bg-slate-700/50 transition-colors ${u.status === 'ACTIVE' ? 'text-amber-400 hover:text-amber-300' : 'text-green-400 hover:text-green-300'}`}
                                                onClick={() => void toggleStatus(u.id)}
                                                title={u.status === 'ACTIVE' ? "Disable User" : "Activate User"}
                                            >
                                                {u.status === 'ACTIVE' ? <UserX className="h-4 w-4" /> : <UserCheck className="h-4 w-4" />}
                                            </button>
                                            <button 
                                                type="button"
                                                onClick={() => void handleDeleteUser(u.id)}
                                                className="p-2 rounded-md text-red-400 hover:text-red-300 hover:bg-slate-700/50 transition-colors"
                                                title="Delete User"
                                            >
                                                <Trash2 className="h-4 w-4" />
                                            </button>
                                        </div>
                                    </td>
                                </tr>
                            ))}
                            {users.length === 0 && !loading && (
                                <tr>
                                    <td colSpan={4} className="text-center py-8 text-slate-500">No users found</td>
                                </tr>
                            )}
                        </tbody>
                    </table>
                </div>
            </CardContent>

            <UserFormModal
                isOpen={isModalOpen}
                onClose={() => setIsModalOpen(false)}
                onSubmit={handleFormSubmit}
                initialData={editingUser ?? undefined}
                isEditing={!!editingUser}
            />
        </Card>
    );
};

export default UserManagement;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import {
  Sparkles,
  Send,
  Mic,
  Bot,
  RefreshCw,
  Zap,
  Brain,
  MessageSquare,
  TrendingUp,
  AlertCircle,
  Wifi,
  WifiOff
} from 'lucide-react';
import { cn } from '../../lib/utils';
import { aiService, MULTILINGUAL_PHRASES, detectLanguage, useGetAIStatus } from '../../services/aiService';

type SupportedLanguage = 'en' | 'am' | 'ru' | 'he' | 'ar';

interface ChatMessage {
  id: string;
  content: string;
  isUser: boolean;
  timestamp: Date;
  language?: string;
}

const languages = [
  { code: 'en', label: 'EN', fullLabel: 'ENGLISH' },
  { code: 'am', label: 'AM', fullLabel: 'አማርኛ' },
  { code: 'ru', label: 'RU', fullLabel: 'РУССКИЙ' },
  { code: 'he', label: 'HE', fullLabel: 'עברית' },
  { code: 'ar', label: 'AR', fullLabel: 'العربية' },
];

const quickActions = [
  { icon: TrendingUp, label: 'Production Status', query: 'What is the current production status?' },
  { icon: AlertCircle, label: 'Low Stock Alerts', query: 'Show me low stock inventory items' },
  { icon: Brain, label: 'AI Recommendations', query: 'Give me optimization recommendations' },
  { icon: MessageSquare, label: 'Quality Report', query: 'Generate a quality control summary' },
];

const AIAssistantPage: React.FC = () => {
  const [inputValue, setInputValue] = useState('');
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [selectedLang, setSelectedLang] = useState<SupportedLanguage>('en');
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  // Get AI provider status
  const { data: aiStatus } = useGetAIStatus();
  const provider = aiStatus?.provider ?? 'demo';
  const isOnline = provider !== 'demo' && provider !== 'offline' && provider !== 'mock';

  // Auto-scroll to bottom
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, isLoading]);

  // Focus input on mount
  useEffect(() => {
    inputRef.current?.focus();
  }, []);

  const handleSendMessage = useCallback(async (messageText?: string) => {
    const text = messageText ?? inputValue.trim();
    if (!text || isLoading) return;

    setError(null);
    const detectedLang = detectLanguage(text) as SupportedLanguage;

    // Add user message
    const userMessage: ChatMessage = {
      id: `user-${Date.now()}`,
      content: text,
      isUser: true,
      timestamp: new Date(),
      language: detectedLang
    };

    setMessages(prev => [...prev, userMessage]);
    setInputValue('');
    setIsLoading(true);

    // Use auto-detected language from user input for natural conversation
    const responseLanguage = detectedLang ?? selectedLang;

    try {
      const response = await aiService.sendChatMessage({
        message: text,
        language: responseLanguage,
        context: { user_role: 'OPERATOR' }
      });

      const aiMessage: ChatMessage = {
        id: `ai-${Date.now()}`,
        content: response.message ?? response.response ?? 'Response received.',
        isUser: false,
        timestamp: new Date(response.timestamp ?? Date.now()),
        language: responseLanguage
      };

      setMessages(prev => [...prev, aiMessage]);
    } catch (err: unknown) {
      console.error('AI Chat Error:', err);
      const errorMsg = err instanceof Error ? err.message : 'Network Error';
      if (err && typeof err === 'object' && 'response' in err) {
        const axiosErr = err as { response?: { data?: { message?: string } } };
        setError(axiosErr.response?.data?.message ?? errorMsg);
      } else {
        setError(errorMsg);
      }

      const errorMessage: ChatMessage = {
        id: `error-${Date.now()}`,
        content: MULTILINGUAL_PHRASES[responseLanguage]?.error ?? MULTILINGUAL_PHRASES.en.error,
        isUser: false,
        timestamp: new Date()
      };
      setMessages(prev => [...prev, errorMessage]);
    } finally {
      setIsLoading(false);
    }
  }, [inputValue, isLoading, selectedLang]);

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSendMessage();
    }
  };

  const handleClearHistory = useCallback(async () => {
    try {
      await aiService.clearChatHistory();
    } catch {
      // Continue even if backend clear fails
    }
    setMessages([]);
    setError(null);
  }, []);

  const handleQuickAction = (query: string) => {
    handleSendMessage(query);
  };

  return (
    <div className="min-h-[calc(100vh-100px)] p-4 md:p-6 bg-gradient-to-br from-amber-50 via-orange-50 to-yellow-50">
      <div className="max-w-7xl mx-auto grid grid-cols-1 lg:grid-cols-4 gap-6">

        {/* Left Sidebar - Quick Actions */}
        <div className="lg:col-span-1 space-y-4">
          {/* Branding Card */}
          <div className="bg-gradient-to-br from-amber-800 via-amber-900 to-yellow-900 rounded-2xl p-5 text-white shadow-xl border border-amber-700/50">
            <div className="flex items-center gap-3 mb-4">
              <div className="w-12 h-12 bg-amber-700/50 rounded-xl flex items-center justify-center border border-amber-600/50 shadow-inner">
                <Sparkles className="w-6 h-6 text-amber-300" />
              </div>
              <div>
                <h2 className="text-lg font-bold tracking-wide">CocoaFlow</h2>
                <p className="text-amber-300 text-xs font-semibold tracking-widest uppercase">AI Intel</p>
              </div>
            </div>
            <p className="text-amber-200/80 text-sm leading-relaxed">
              Your intelligent factory companion for real-time insights and optimization.
            </p>
          </div>

          {/* Quick Actions Card */}
          <div className="bg-white/80 backdrop-blur-sm rounded-2xl p-4 shadow-lg border border-amber-100">
            <h3 className="text-sm font-bold text-amber-900 mb-3 flex items-center gap-2">
              <Zap className="w-4 h-4 text-amber-600" />
              Quick Actions
            </h3>
            <div className="space-y-2">
              {quickActions.map((action, idx) => (
                <button
                  key={idx}
                  onClick={() => handleQuickAction(action.query)}
                  disabled={isLoading}
                  className="w-full flex items-center gap-3 p-3 rounded-xl bg-amber-50 hover:bg-amber-100 text-amber-900 text-sm font-medium transition-all hover:shadow-md disabled:opacity-50 disabled:cursor-not-allowed border border-transparent hover:border-amber-200"
                >
                  <action.icon className="w-4 h-4 text-amber-700" />
                  {action.label}
                </button>
              ))}
            </div>
          </div>

          {/* Language Selector Card */}
          <div className="bg-white/80 backdrop-blur-sm rounded-2xl p-4 shadow-lg border border-amber-100">
            <h3 className="text-sm font-bold text-amber-900 mb-3">Language</h3>
            <div className="flex flex-wrap gap-2">
              {languages.map((lang) => (
                <button
                  key={lang.code}
                  onClick={() => setSelectedLang(lang.code as SupportedLanguage)}
                  className={cn(
                    "px-3 py-1.5 rounded-lg text-xs font-bold transition-all",
                    selectedLang === lang.code
                      ? "bg-amber-800 text-white shadow-md"
                      : "bg-amber-100 text-amber-800 hover:bg-amber-200"
                  )}
                >
                  {lang.label}
                </button>
              ))}
            </div>
          </div>
        </div>

        {/* Main Chat Area */}
        <div className="lg:col-span-3">
          <div className="bg-white/90 backdrop-blur-sm rounded-2xl shadow-xl border border-amber-100 overflow-hidden flex flex-col h-[calc(100vh-180px)] min-h-[500px]">

            {/* Chat Header */}
            <div className="bg-gradient-to-r from-amber-800 to-amber-900 text-white px-6 py-4 flex items-center justify-between shrink-0">
              <div className="flex items-center gap-4">
                <div className="w-10 h-10 bg-amber-700/50 rounded-xl flex items-center justify-center border border-amber-600/50">
                  <Brain className="w-5 h-5 text-amber-300" />
                </div>
                <div>
                  <h1 className="text-lg font-bold tracking-wide">CocoaFlow AI Intel</h1>
                  <p className="text-amber-300 text-xs font-medium tracking-wider">Global Factory Intelligence</p>
                </div>
              </div>
              <div className="flex items-center gap-3">
                <div className={cn(
                  "flex items-center gap-2 rounded-full px-3 py-1.5",
                  isOnline ? "bg-green-500/20" : "bg-amber-700/30"
                )}>
                  {isOnline ? (
                    <Wifi className="w-3 h-3 text-green-400" />
                  ) : (
                    <WifiOff className="w-3 h-3 text-amber-300" />
                  )}
                  <span className={cn(
                    "text-xs font-semibold capitalize",
                    isOnline ? "text-green-300" : "text-amber-200"
                  )}>
                    {provider === 'demo' || provider === 'mock' ? 'Demo Mode' : provider}
                  </span>
                </div>
                <button
                  onClick={handleClearHistory}
                  disabled={isLoading || messages.length === 0}
                  className="p-2 hover:bg-amber-700/50 rounded-lg transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                  title="Clear Chat"
                >
                  <RefreshCw className="w-4 h-4" />
                </button>
              </div>
            </div>

            {/* Error Banner */}
            {error && (
              <div className="bg-red-50 border-b border-red-100 px-4 py-2 flex items-center gap-2 text-red-700 text-sm">
                <AlertCircle className="w-4 h-4" />
                <span>{error}</span>
                <button
                  onClick={() => setError(null)}
                  className="ml-auto text-red-500 hover:text-red-700"
                >
                  Dismiss
                </button>
              </div>
            )}

            {/* Chat Messages */}
            <div className="flex-1 overflow-y-auto p-6 space-y-6 bg-gradient-to-b from-amber-50/50 to-white">
              {messages.length === 0 && (
                <div className="h-full flex flex-col items-center justify-center text-center py-12">
                  <div className="w-20 h-20 bg-amber-100 rounded-full flex items-center justify-center mb-4">
                    <Bot className="w-10 h-10 text-amber-700" />
                  </div>
                  <h3 className="text-amber-900 font-bold text-lg mb-2">CocoaFlow AI Intel Ready</h3>
                  <p className="text-amber-600 text-sm max-w-md">
                    Ask me about production status, inventory levels, quality control, or get AI-powered recommendations.
                  </p>
                </div>
              )}

              {messages.map((msg) => (
                <div key={msg.id} className={cn("flex w-full", msg.isUser ? "justify-end" : "justify-start")}>
                  {msg.isUser ? (
                    <div className="max-w-[85%] md:max-w-[70%]">
                      <div className="bg-gradient-to-br from-amber-700 to-amber-800 text-white p-4 rounded-2xl rounded-tr-md shadow-lg">
                        <p className="text-[10px] font-bold text-amber-300 mb-1 tracking-widest uppercase">
