                        <p className="text-[10px] font-bold text-amber-600 mb-2 tracking-widest uppercase pl-2">
                          CocoaFlow AI Intel
                        </p>
                        <div className="text-gray-800 text-base leading-relaxed whitespace-pre-wrap pl-2">
                          {msg.content}
                        </div>
                        <p className="text-[10px] text-gray-400 mt-3 pl-2">
                          {msg.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                        </p>
                      </div>
                    </div>
                  )}
                </div>
              ))}

              {isLoading && (
                <div className="flex justify-start w-full">
                  <div className="bg-white p-4 rounded-2xl rounded-tl-md border border-amber-100 shadow-md flex items-center gap-3">
                    <div className="flex gap-1.5">
                      <span className="w-2 h-2 bg-amber-600 rounded-full animate-bounce" style={{ animationDelay: '0ms' }}></span>
                      <span className="w-2 h-2 bg-amber-600 rounded-full animate-bounce" style={{ animationDelay: '150ms' }}></span>
                      <span className="w-2 h-2 bg-amber-600 rounded-full animate-bounce" style={{ animationDelay: '300ms' }}></span>
                    </div>
                    <span className="text-xs font-bold text-amber-700 uppercase tracking-widest">Processing...</span>
                  </div>
                </div>
              )}
              <div ref={messagesEndRef} />
            </div>

            {/* Input Area */}
            <div className="p-4 bg-white border-t border-amber-100 shrink-0">
              <div className="flex items-center gap-3">
                <div className="flex-1 relative">
                  <input
                    ref={inputRef}
                    type="text"
                    value={inputValue}
                    onChange={(e) => setInputValue(e.target.value)}
                    onKeyDown={handleKeyDown}
                    placeholder="Ask CocoaFlow AI Intel..."
                    className="w-full bg-amber-50 border-2 border-transparent focus:border-amber-200 hover:border-amber-100 rounded-xl py-3 pl-4 pr-12 text-gray-700 placeholder:text-gray-400 focus:outline-none transition-all text-base"
                    disabled={isLoading}
                  />
                  <button
                    className="absolute right-3 top-1/2 -translate-y-1/2 p-1.5 text-gray-400 hover:text-amber-700 transition-colors rounded-lg hover:bg-amber-100"
                    title="Voice Input (Coming Soon)"
                  >
                    <Mic className="w-5 h-5" />
                  </button>
                </div>
                <button
                  onClick={() => handleSendMessage()}
                  disabled={!inputValue.trim() || isLoading}
                  className={cn(
                    "p-3 rounded-xl transition-all shadow-md",
                    inputValue.trim() && !isLoading
                      ? "bg-gradient-to-br from-amber-600 to-amber-700 text-white hover:from-amber-700 hover:to-amber-800 active:scale-95"
