              <motion.div variants={itemVariants} initial="hidden" animate="visible" className="bg-white rounded-2xl p-5 border border-chocolate-100/50 shadow-sm hover:shadow-lg transition-all group">
                <div className="flex items-center justify-between mb-3">
                  <div className="p-2 bg-gold-100 rounded-xl group-hover:scale-110 transition-transform">
                    <DollarSign className="w-5 h-5 text-gold-600" />
                  </div>
                  <span className="text-[9px] font-black text-vibrant-green bg-vibrant-green/10 px-2 py-1 rounded-full flex items-center gap-1">
                    <TrendingUp className="w-3 h-3" /> +12.5%
                  </span>
                </div>
                <p className="text-2xl font-black text-chocolate-950">${totalRevenue.toLocaleString()}</p>
                <p className="text-[10px] font-bold text-chocolate-400 uppercase tracking-widest mt-1">Gross Revenue</p>
              </motion.div>

              <motion.div variants={itemVariants} initial="hidden" animate="visible" className="bg-white rounded-2xl p-5 border border-chocolate-100/50 shadow-sm hover:shadow-lg transition-all group">
                <div className="flex items-center justify-between mb-3">
                  <div className="p-2 bg-blue-100 rounded-xl group-hover:scale-110 transition-transform">
                    <CreditCard className="w-5 h-5 text-blue-600" />
                  </div>
                  <span className="text-[9px] font-black text-vibrant-green bg-vibrant-green/10 px-2 py-1 rounded-full flex items-center gap-1">
                    <TrendingUp className="w-3 h-3" /> +8.3%
                  </span>
                </div>
                <p className="text-2xl font-black text-chocolate-950">{totalInvoices}</p>
                <p className="text-[10px] font-bold text-chocolate-400 uppercase tracking-widest mt-1">Total Orders</p>
              </motion.div>

              <motion.div variants={itemVariants} initial="hidden" animate="visible" className="bg-white rounded-2xl p-5 border border-chocolate-100/50 shadow-sm hover:shadow-lg transition-all group">
                <div className="flex items-center justify-between mb-3">
                  <div className="p-2 bg-purple-100 rounded-xl group-hover:scale-110 transition-transform">
                    <Target className="w-5 h-5 text-purple-600" />
                  </div>
                  <span className="text-[9px] font-black text-vibrant-green bg-vibrant-green/10 px-2 py-1 rounded-full flex items-center gap-1">
                    <TrendingUp className="w-3 h-3" /> +5.2%
                  </span>
                </div>
                <p className="text-2xl font-black text-chocolate-950">${avgOrderValue.toFixed(0)}</p>
                <p className="text-[10px] font-bold text-chocolate-400 uppercase tracking-widest mt-1">Avg. Order Value</p>
              </motion.div>

              <motion.div variants={itemVariants} initial="hidden" animate="visible" className="bg-white rounded-2xl p-5 border border-chocolate-100/50 shadow-sm hover:shadow-lg transition-all group">
                <div className="flex items-center justify-between mb-3">
                  <div className="p-2 bg-green-100 rounded-xl group-hover:scale-110 transition-transform">
                    <Users className="w-5 h-5 text-green-600" />
                  </div>
                  <span className="text-[9px] font-black text-vibrant-green bg-vibrant-green/10 px-2 py-1 rounded-full flex items-center gap-1">
                    <TrendingUp className="w-3 h-3" /> +18.7%
                  </span>
                </div>
                <p className="text-2xl font-black text-chocolate-950">{totalCustomers.toLocaleString()}</p>
                <p className="text-[10px] font-bold text-chocolate-400 uppercase tracking-widest mt-1">Total Customers</p>
              </motion.div>

              <motion.div variants={itemVariants} initial="hidden" animate="visible" className="bg-white rounded-2xl p-5 border border-chocolate-100/50 shadow-sm hover:shadow-lg transition-all group">
                <div className="flex items-center justify-between mb-3">
                  <div className="p-2 bg-orange-100 rounded-xl group-hover:scale-110 transition-transform">
                    <Percent className="w-5 h-5 text-orange-600" />
                  </div>
                  <span className="text-[9px] font-black text-vibrant-green bg-vibrant-green/10 px-2 py-1 rounded-full flex items-center gap-1">
                    <TrendingUp className="w-3 h-3" /> +0.8%
                  </span>
                </div>
                <p className="text-2xl font-black text-chocolate-950">{conversionRate}%</p>
                <p className="text-[10px] font-bold text-chocolate-400 uppercase tracking-widest mt-1">Conversion Rate</p>
              </motion.div>

              <motion.div variants={itemVariants} initial="hidden" animate="visible" className="bg-white rounded-2xl p-5 border border-chocolate-100/50 shadow-sm hover:shadow-lg transition-all group">
                <div className="flex items-center justify-between mb-3">
                  <div className="p-2 bg-pink-100 rounded-xl group-hover:scale-110 transition-transform">
                    <Zap className="w-5 h-5 text-pink-600" />
                  </div>
                  <span className="text-[9px] font-black text-vibrant-green bg-vibrant-green/10 px-2 py-1 rounded-full flex items-center gap-1">
                    <TrendingUp className="w-3 h-3" /> +4.2%
                  </span>
                </div>
                <p className="text-2xl font-black text-chocolate-950">{returningCustomers}%</p>
                <p className="text-[10px] font-bold text-chocolate-400 uppercase tracking-widest mt-1">Returning Rate</p>
              </motion.div>
            </div>

            {/* Main Content Grid: Chart + Tasks */}
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
              {/* Revenue Chart (2/3 width) */}
              <motion.div
                variants={itemVariants}
                initial="hidden"
                animate="visible"
                className="lg:col-span-2 bg-white rounded-[2rem] border border-chocolate-100/50 p-8 shadow-sm relative overflow-hidden min-h-[450px]"
              >
                <div className="absolute top-0 left-0 w-64 h-64 bg-gold-500/5 rounded-full blur-3xl -translate-x-1/2 -translate-y-1/2" />
                <div className="flex items-center justify-between mb-6 relative z-10">
                  <div className="flex items-center gap-3">
                    <div className="p-2 bg-chocolate-50 rounded-xl">
                      <TrendingUp className="w-5 h-5 text-gold-600" />
                    </div>
                    <div>
                      <h3 className="font-black text-chocolate-950 text-xl tracking-tight uppercase">Weekly Performance</h3>
                      <p className="text-[10px] text-chocolate-400 font-bold tracking-widest">REVENUE VS ORDERS VS TARGET</p>
                    </div>
                  </div>
                  <div className="flex items-center gap-2">
                    <div className="bg-chocolate-50 p-1 rounded-lg flex">
                      {(['composed', 'area', 'bar'] as const).map((type) => (
                        <button
                          key={type}
                          onClick={() => setChartType(type)}
                          className={`px-3 py-1.5 rounded-md text-[10px] font-black uppercase tracking-wider transition-all ${
                            chartType === type ? 'bg-chocolate-950 text-white' : 'text-chocolate-400 hover:text-chocolate-600'
                          }`}
                        >
                          {type}
                        </button>
                      ))}
                    </div>
                    <span className="text-[10px] font-black text-gold-600 bg-gold-100/50 px-3 py-1.5 rounded-full border border-gold-200 animate-pulse tracking-widest uppercase">Live</span>
                  </div>
                </div>

                <div className="h-[340px] w-full relative z-10">
                  <ResponsiveContainer width="100%" height="100%">
                    {chartType === 'composed' ? (
                      <ComposedChart data={weeklyData}>
                        <defs>
                          <linearGradient id="colorRevenue" x1="0" y1="0" x2="0" y2="1">
                            <stop offset="5%" stopColor={CHART_COLORS.primary} stopOpacity={0.3}/>
                            <stop offset="95%" stopColor={CHART_COLORS.primary} stopOpacity={0}/>
                          </linearGradient>
                          <linearGradient id="colorOnline" x1="0" y1="0" x2="0" y2="1">
                            <stop offset="5%" stopColor={CHART_COLORS.accent} stopOpacity={0.8}/>
                            <stop offset="95%" stopColor={CHART_COLORS.accent} stopOpacity={0.3}/>
                          </linearGradient>
                          <linearGradient id="colorInStore" x1="0" y1="0" x2="0" y2="1">
                            <stop offset="5%" stopColor={CHART_COLORS.secondary} stopOpacity={0.8}/>
                            <stop offset="95%" stopColor={CHART_COLORS.secondary} stopOpacity={0.3}/>
                          </linearGradient>
                        </defs>
                        <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" opacity={0.5} />
                        <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{ fontSize: 11, fontWeight: 700, fill: '#8c594a' }} dy={10} />
                        <YAxis yAxisId="left" axisLine={false} tickLine={false} tick={{ fontSize: 11, fontWeight: 700, fill: '#8c594a' }} />
                        <YAxis yAxisId="right" orientation="right" axisLine={false} tickLine={false} tick={{ fontSize: 11, fontWeight: 700, fill: '#8c594a' }} />
                        <Tooltip
                          contentStyle={{
                            borderRadius: '16px',
                            border: 'none',
                            boxShadow: '0 10px 40px -5px rgba(0,0,0,0.15)',
                            fontWeight: 700,
                            padding: '12px 16px'
                          }}
                          formatter={(value: number, name: string) => [
                            name === 'orders' ? value : `$${value.toLocaleString()}`,
                            name.charAt(0).toUpperCase() + name.slice(1)
                          ]}
                        />
                        <Legend
                          wrapperStyle={{ paddingTop: '20px' }}
                          formatter={(value) => <span className="text-xs font-bold text-chocolate-600 uppercase tracking-wider">{value}</span>}
                        />
                        <Bar yAxisId="left" dataKey="online" stackId="a" fill="url(#colorOnline)" radius={[0, 0, 0, 0]} name="Online Sales" />
                        <Bar yAxisId="left" dataKey="inStore" stackId="a" fill="url(#colorInStore)" radius={[8, 8, 0, 0]} name="In-Store Sales" />
                        <Line yAxisId="left" type="monotone" dataKey="target" stroke={CHART_COLORS.warning} strokeWidth={2} strokeDasharray="5 5" dot={false} name="Target" />
                        <Line yAxisId="right" type="monotone" dataKey="orders" stroke={CHART_COLORS.success} strokeWidth={3} dot={{ fill: CHART_COLORS.success, strokeWidth: 2, r: 4 }} name="Orders" />
                      </ComposedChart>
                    ) : chartType === 'area' ? (
                      <AreaChart data={weeklyData}>
                        <defs>
                          <linearGradient id="areaRevenue" x1="0" y1="0" x2="0" y2="1">
                            <stop offset="5%" stopColor={CHART_COLORS.primary} stopOpacity={0.4}/>
                            <stop offset="95%" stopColor={CHART_COLORS.primary} stopOpacity={0}/>
                          </linearGradient>
                        </defs>
                        <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" opacity={0.5} />
                        <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{ fontSize: 11, fontWeight: 700, fill: '#8c594a' }} dy={10} />
                        <YAxis axisLine={false} tickLine={false} tick={{ fontSize: 11, fontWeight: 700, fill: '#8c594a' }} />
                        <Tooltip contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 10px 25px -5px rgba(0,0,0,0.1)', fontWeight: 700 }} formatter={(value: number) => [`$${value.toLocaleString()}`, 'Revenue']} />
                        <Area type="monotone" dataKey="revenue" stroke={CHART_COLORS.primary} strokeWidth={4} fillOpacity={1} fill="url(#areaRevenue)" />
                      </AreaChart>
                    ) : (
                      <BarChart data={weeklyData}>
                        <defs>
                          <linearGradient id="barGradient" x1="0" y1="0" x2="0" y2="1">
                            <stop offset="0%" stopColor={CHART_COLORS.primary} stopOpacity={1}/>
                            <stop offset="100%" stopColor={CHART_COLORS.secondary} stopOpacity={0.8}/>
                          </linearGradient>
                        </defs>
                        <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" opacity={0.5} />
                        <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{ fontSize: 11, fontWeight: 700, fill: '#8c594a' }} dy={10} />
                        <YAxis axisLine={false} tickLine={false} tick={{ fontSize: 11, fontWeight: 700, fill: '#8c594a' }} />
                        <Tooltip contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 10px 25px -5px rgba(0,0,0,0.1)', fontWeight: 700 }} formatter={(value: number) => [`$${value.toLocaleString()}`, 'Revenue']} />
                        <Bar dataKey="revenue" fill="url(#barGradient)" radius={[12, 12, 0, 0]} />
                      </BarChart>
                    )}
                  </ResponsiveContainer>
                </div>
              </motion.div>

              {/* Tasks Panel (1/3 width) */}
              <div className="h-full min-h-[450px]">
                 <SalesTasks />
              </div>
            </div>

            {/* Second Row: Hourly Sales + Category Breakdown + Performance */}
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
              {/* Hourly Sales Chart */}
              <motion.div
                variants={itemVariants}
                initial="hidden"
                animate="visible"
                className="bg-white rounded-[2rem] border border-chocolate-100/50 p-6 shadow-sm"
              >
                <div className="flex items-center gap-3 mb-6">
                  <div className="p-2 bg-blue-100 rounded-xl">
                    <BarChart3 className="w-5 h-5 text-blue-600" />
                  </div>
                  <div>
                    <h3 className="font-black text-chocolate-950 text-base uppercase tracking-tight">Today's Sales</h3>
                    <p className="text-[10px] text-chocolate-400 font-bold tracking-widest">HOURLY BREAKDOWN</p>
                  </div>
                </div>
                <div className="h-[200px]">
                  <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={hourlyData}>
                      <defs>
                        <linearGradient id="hourlyGradient" x1="0" y1="0" x2="0" y2="1">
                          <stop offset="0%" stopColor={CHART_COLORS.info} stopOpacity={0.9}/>
                          <stop offset="100%" stopColor={CHART_COLORS.accent} stopOpacity={0.6}/>
                        </linearGradient>
                      </defs>
                      <XAxis dataKey="hour" axisLine={false} tickLine={false} tick={{ fontSize: 9, fontWeight: 600, fill: '#8c594a' }} />
                      <YAxis hide />
                      <Tooltip
                        contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 4px 12px rgba(0,0,0,0.1)', fontSize: '12px', fontWeight: 600 }}
                        formatter={(value: number) => [`$${value}`, 'Sales']}
                      />
                      <Bar dataKey="sales" fill="url(#hourlyGradient)" radius={[6, 6, 0, 0]} />
                    </BarChart>
                  </ResponsiveContainer>
                </div>
              </motion.div>

              {/* Category Breakdown Pie Chart */}
              <motion.div
                variants={itemVariants}
                initial="hidden"
                animate="visible"
                className="bg-white rounded-[2rem] border border-chocolate-100/50 p-6 shadow-sm"
              >
                <div className="flex items-center gap-3 mb-4">
                  <div className="p-2 bg-purple-100 rounded-xl">
                    <Package className="w-5 h-5 text-purple-600" />
                  </div>
                  <div>
                    <h3 className="font-black text-chocolate-950 text-base uppercase tracking-tight">By Category</h3>
                    <p className="text-[10px] text-chocolate-400 font-bold tracking-widest">SALES DISTRIBUTION</p>
                  </div>
                </div>
                <div className="h-[180px] flex items-center justify-center">
                  <ResponsiveContainer width="100%" height="100%">
                    <PieChart>
                      <Pie
                        data={categoryData}
                        cx="50%"
                        cy="50%"
                        innerRadius={50}
                        outerRadius={75}
                        paddingAngle={3}
                        dataKey="value"
                      >
                        {categoryData.map((entry, index) => (
                          <Cell key={`cell-${index}`} fill={entry.color} />
                        ))}
                      </Pie>
                      <Tooltip
                        contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 4px 12px rgba(0,0,0,0.1)', fontSize: '12px', fontWeight: 600 }}
                        formatter={(value: number) => [`${value}%`, 'Share']}
                      />
                    </PieChart>
                  </ResponsiveContainer>
                </div>
                <div className="grid grid-cols-2 gap-2 mt-2">
                  {categoryData.slice(0, 4).map((cat, idx) => (
                    <div key={idx} className="flex items-center gap-2">
                      <div className="w-3 h-3 rounded-full" style={{ backgroundColor: cat.color }} />
                      <span className="text-[10px] font-bold text-chocolate-600 truncate">{cat.name}</span>
                    </div>
                  ))}
                </div>
              </motion.div>

              {/* Performance Radial */}
              <motion.div
                variants={itemVariants}
                initial="hidden"
                animate="visible"
                className="bg-white rounded-[2rem] border border-chocolate-100/50 p-6 shadow-sm"
              >
                <div className="flex items-center gap-3 mb-4">
                  <div className="p-2 bg-green-100 rounded-xl">
                    <Target className="w-5 h-5 text-green-600" />
                  </div>
                  <div>
                    <h3 className="font-black text-chocolate-950 text-base uppercase tracking-tight">KPI Status</h3>
                    <p className="text-[10px] text-chocolate-400 font-bold tracking-widest">PERFORMANCE METRICS</p>
                  </div>
                </div>
                <div className="h-[160px]">
                  <ResponsiveContainer width="100%" height="100%">
                    <RadialBarChart cx="50%" cy="50%" innerRadius="30%" outerRadius="90%" data={performanceData} startAngle={180} endAngle={0}>
                      <RadialBar background dataKey="value" cornerRadius={10} />
                      <Tooltip
                        contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 4px 12px rgba(0,0,0,0.1)', fontSize: '12px', fontWeight: 600 }}
                        formatter={(value: number) => [`${value}%`, 'Progress']}
                      />
                    </RadialBarChart>
                  </ResponsiveContainer>
                </div>
                <div className="space-y-2 mt-2">
                  {performanceData.map((item, idx) => (
                    <div key={idx} className="flex items-center justify-between">
                      <div className="flex items-center gap-2">
                        <div className="w-2 h-2 rounded-full" style={{ backgroundColor: item.fill }} />
                        <span className="text-[10px] font-bold text-chocolate-600">{item.name}</span>
                      </div>
                      <span className="text-[11px] font-black text-chocolate-950">{item.value}%</span>
                    </div>
                  ))}
                </div>
              </motion.div>
            </div>

            {/* Bottom Grid: Recent Orders + Top Products */}
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 pb-8">
              {/* Recent Orders */}
              <motion.div
                variants={itemVariants}
                initial="hidden"
                animate="visible"
                className="bg-white rounded-[2.5rem] border border-chocolate-100/50 shadow-sm flex flex-col relative overflow-hidden"
              >
                <div className="p-8 border-b border-chocolate-50 flex items-center justify-between relative z-10">
                  <div>
                    <h3 className="font-black text-chocolate-950 text-lg uppercase tracking-tight">Recent Transactions</h3>
                    <p className="text-[10px] text-gold-600 font-black tracking-widest mt-1">REAL-TIME LOG</p>
                  </div>
                  <span className="text-[10px] font-black text-chocolate-400 bg-chocolate-50 px-3 py-1.5 rounded-full">{combinedRecent.length} orders</span>
                </div>
                <div className="p-6 space-y-4 flex-1 max-h-[400px] overflow-y-auto relative z-10">
                  {loading ? (
                    <div className="flex items-center justify-center p-12 text-chocolate-400 text-sm font-black uppercase tracking-widest animate-pulse italic">Synchronizing...</div>
                  ) : combinedRecent.map((order, idx) => (
                    <div key={idx} className="flex items-center justify-between p-4 rounded-3xl border border-chocolate-50 bg-chocolate-50/20 hover:bg-chocolate-50 transition-all duration-300 group">
                      <div className="flex items-center gap-4">
                        <div className={`w-12 h-12 rounded-2xl flex items-center justify-center font-black text-sm shadow-sm ${order.color} group-hover:scale-110 transition-transform`}>
                          {order.initials}
                        </div>
                        <div>
                          <p className="text-[11px] font-black text-chocolate-950 uppercase tracking-widest mb-0.5">{order.user}</p>
                          <p className="text-[10px] text-chocolate-400 font-bold truncate max-w-[180px]">{order.item}</p>
                        </div>
                      </div>
                      <div className="text-right">
                        <p className="font-black text-sm text-gold-600 leading-none mb-1">${order.amount}</p>
                        <p className={`text-[9px] font-black px-2 py-0.5 rounded-full inline-block uppercase tracking-tighter ${
                          order.status === 'PAID' ? 'text-vibrant-green bg-vibrant-green/10' :
                          order.status === 'PROCESSING' ? 'text-orange-500 bg-orange-100' :
                          order.status === 'SHIPPED' ? 'text-blue-500 bg-blue-100' :
                          order.status === 'RECURRING' ? 'text-purple-500 bg-purple-100' :
                          'text-chocolate-500 bg-chocolate-100'
                        }`}>{order.status}</p>
                      </div>
                    </div>
                  ))}
                </div>
                <div className="p-6 border-t border-chocolate-50 bg-chocolate-50/10">
                   <Link to="/sales" className="w-full py-3 flex items-center justify-center gap-2 text-[10px] font-black text-chocolate-600 hover:text-gold-600 transition-colors uppercase tracking-[0.2em] active:scale-95">
                      View Full Ledger <ArrowUpRight className="w-4 h-4" />
                   </Link>
                </div>
              </motion.div>

              {/* Top Products */}
              <motion.div
                variants={itemVariants}
                initial="hidden"
                animate="visible"
                className="bg-white rounded-[2.5rem] border border-chocolate-100/50 shadow-sm relative overflow-hidden"
              >
                <div className="p-8 border-b border-chocolate-50 flex items-center justify-between">
                  <div>
                    <h3 className="font-black text-chocolate-950 text-lg uppercase tracking-tight">Top Performing Products</h3>
                    <p className="text-[10px] text-chocolate-400 font-black tracking-widest mt-1">REVENUE LEADERBOARD</p>
                  </div>
                </div>
                <div className="p-6 space-y-4">
                   {topProducts.map((product, idx) => (
                      <div key={idx} className="flex items-center justify-between p-4 rounded-2xl border border-chocolate-50 bg-chocolate-50/20 hover:bg-chocolate-50 transition-all duration-300 group">
                        <div className="flex items-center gap-4">
                           <div className="w-12 h-12 rounded-2xl bg-gradient-to-br from-chocolate-100 to-chocolate-50 flex items-center justify-center text-gold-600 shadow-sm group-hover:scale-110 transition-transform font-black text-lg">
                              #{idx + 1}
                           </div>
                           <div>
                             <p className="font-black text-sm text-chocolate-950 leading-tight mb-1">{product.name}</p>
                             <div className="flex items-center gap-3">
                               <span className="text-[10px] font-black px-2 py-0.5 rounded-full bg-chocolate-950 text-gold-500 uppercase tracking-widest">
                                 {product.units.toLocaleString()} units
                               </span>
                               <span className="text-[10px] font-bold text-chocolate-400">${product.revenue.toLocaleString()}</span>
                             </div>
                           </div>
                        </div>
                        <div className={`flex items-center gap-1.5 px-3 py-1.5 rounded-full border ${
                          product.trend >= 0
                            ? 'bg-vibrant-green/10 border-vibrant-green/20 text-vibrant-green'
                            : 'bg-red-100 border-red-200 text-red-500'
                        }`}>
                          {product.trend >= 0 ? <TrendingUp className="w-3 h-3" /> : <TrendingDown className="w-3 h-3" />}
                          <span className="text-[10px] font-black uppercase tracking-tighter">{product.trend >= 0 ? '+' : ''}{product.trend}%</span>
                        </div>
                      </div>
                   ))}
                </div>
              </motion.div>
            </div>
          </motion.div>
        ) : (
          <motion.div
            key="catalog"
            initial={{ opacity: 0, x: 20 }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: -20 }}
          >
             <ProductCatalog />
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default SalesDashboard;

import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  Search,
  Filter,
  Plus,
  Wrench,
  AlertTriangle,
  Calendar,
  MapPin,
  Settings,
} from 'lucide-react';
import PageHeader from '../../components/layout/PageHeader';
import { Card, CardContent } from '../../components/ui/Card';
import { Button } from '../../components/ui/Button';
import { Input } from '../../components/ui/Input';
import { Badge } from '../../components/ui/Badge';
import MaintenanceLogModal from '../../components/mechanic/MaintenanceLogModal';
import { useMechanic } from '../../hooks/useMechanic';
import { Machine, MachineStatus } from '../../types';

const MachinesPage: React.FC = () => {
  const navigate = useNavigate();
  const { useMachines } = useMechanic();
  const { data: machines = [], isLoading } = useMachines();

  // State
  const [searchQuery, setSearchQuery] = useState('');
  const [statusFilter, setStatusFilter] = useState<MachineStatus | 'all'>('all');
  const [isMaintenanceModalOpen, setIsMaintenanceModalOpen] = useState(false);
  const [selectedMachineId, setSelectedMachineId] = useState<string | undefined>();

  // Filter machines
  const filteredMachines = machines.filter((machine: Machine) => {
    // Status filter
    if (statusFilter !== 'all' && machine.status !== statusFilter) return false;

    // Search filter
    if (searchQuery) {
      const query = searchQuery.toLowerCase();
      return (
        machine.name.toLowerCase().includes(query) ||
        machine.machine_code.toLowerCase().includes(query) ||
        machine.type.toLowerCase().includes(query)
      );
    }
    return true;
  });

  // Sort by next maintenance date (urgent first)
  const sortedMachines = [...filteredMachines].sort((a, b) => {
    // Machines needing repair/maintenance first
    const statusOrder = { repair: 0, maintenance: 1, offline: 2, standby: 3, operational: 4 };
    const statusDiff = statusOrder[a.status] - statusOrder[b.status];
    if (statusDiff !== 0) return statusDiff;

    // Then by next maintenance date
    if (a.next_maintenance_date && b.next_maintenance_date) {
      return new Date(a.next_maintenance_date).getTime() - new Date(b.next_maintenance_date).getTime();
    }
    return 0;
  });

  const getStatusConfig = (status: MachineStatus) => {
    switch (status) {
      case 'operational':
        return { color: 'bg-green-500', bgColor: 'bg-green-50 border-green-200', textColor: 'text-green-700', variant: 'success' as const };
      case 'maintenance':
        return { color: 'bg-amber-500', bgColor: 'bg-amber-50 border-amber-200', textColor: 'text-amber-700', variant: 'warning' as const };
      case 'repair':
        return { color: 'bg-red-500', bgColor: 'bg-red-50 border-red-200', textColor: 'text-red-700', variant: 'error' as const };
      case 'offline':
        return { color: 'bg-gray-500', bgColor: 'bg-gray-50 border-gray-200', textColor: 'text-gray-700', variant: 'default' as const };
      case 'standby':
        return { color: 'bg-blue-500', bgColor: 'bg-blue-50 border-blue-200', textColor: 'text-blue-700', variant: 'default' as const };
      default:
        return { color: 'bg-gray-400', bgColor: 'bg-gray-50 border-gray-200', textColor: 'text-gray-600', variant: 'default' as const };
    }
  };

  const isMaintenanceDue = (machine: Machine): boolean => {
    if (!machine.next_maintenance_date) return false;
    const nextDate = new Date(machine.next_maintenance_date);
    const now = new Date();
    const oneWeekLater = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000);
    return nextDate <= oneWeekLater;
  };

  const handleLogMaintenance = (machineId: string) => {
    setSelectedMachineId(machineId);
    setIsMaintenanceModalOpen(true);
  };

  const statusOptions: { value: MachineStatus | 'all'; label: string }[] = [
    { value: 'all', label: 'All Statuses' },
    { value: 'operational', label: 'Operational' },
    { value: 'maintenance', label: 'Maintenance' },
    { value: 'repair', label: 'Repair' },
    { value: 'offline', label: 'Offline' },
    { value: 'standby', label: 'Standby' },
  ];

  // Stats
  const operationalCount = machines.filter((m: Machine) => m.status === 'operational').length;
  const maintenanceCount = machines.filter((m: Machine) => m.status === 'maintenance' || m.status === 'repair').length;
  const maintenanceDueCount = machines.filter((m: Machine) => isMaintenanceDue(m)).length;

  return (
    <div className="space-y-6">
      {/* Header */}
      <PageHeader
        title="Machines"
        subtitle="View and manage all factory machines"
        icon={Settings}
      />

      {/* Stats */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        <Card>
          <CardContent className="p-4">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-xs text-gray-600 font-medium">Total Machines</p>
                <p className="text-2xl font-bold text-gray-800">{machines.length}</p>
              </div>
              <Settings className="w-8 h-8 text-gray-400" />
            </div>
          </CardContent>
        </Card>
        <Card className="bg-green-50 border-green-200">
          <CardContent className="p-4">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-xs text-green-600 font-medium">Operational</p>
                <p className="text-2xl font-bold text-green-800">{operationalCount}</p>
              </div>
              <Wrench className="w-8 h-8 text-green-400" />
            </div>
          </CardContent>
        </Card>
        <Card className="bg-amber-50 border-amber-200">
          <CardContent className="p-4">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-xs text-amber-600 font-medium">Needs Attention</p>
                <p className="text-2xl font-bold text-amber-800">{maintenanceCount}</p>
              </div>
              <AlertTriangle className="w-8 h-8 text-amber-400" />
            </div>
          </CardContent>
        </Card>
        <Card className="bg-blue-50 border-blue-200">
          <CardContent className="p-4">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-xs text-blue-600 font-medium">Maintenance Due</p>
                <p className="text-2xl font-bold text-blue-800">{maintenanceDueCount}</p>
              </div>
              <Calendar className="w-8 h-8 text-blue-400" />
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Filters */}
      <div className="flex flex-col md:flex-row gap-4">
        {/* Search */}
        <div className="flex-1 relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
          <Input
            type="text"
            placeholder="Search by name or code..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="pl-10"
          />
        </div>

        {/* Status Filter */}
        <div className="flex items-center gap-2">
          <Filter className="w-4 h-4 text-gray-400" />
          <select
            value={statusFilter}
            onChange={(e) => setStatusFilter(e.target.value as MachineStatus | 'all')}
            className="px-3 py-2 bg-white border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-2 focus:ring-chocolate-500 focus:border-chocolate-500 text-sm"
          >
            {statusOptions.map((opt) => (
              <option key={opt.value} value={opt.value}>
                {opt.label}
              </option>
            ))}
          </select>
        </div>
      </div>

      {/* Machines Grid */}
      {isLoading ? (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {[...Array(6)].map((_, i) => (
            <div key={i} className="h-64 bg-gray-100 rounded-xl animate-pulse" />
          ))}
        </div>
      ) : sortedMachines.length === 0 ? (
        <Card className="py-12">
          <CardContent className="text-center">
            <Settings className="w-16 h-16 text-gray-300 mx-auto mb-4" />
            <h3 className="text-lg font-semibold text-gray-700 mb-2">
              No machines found
            </h3>
            <p className="text-gray-500">
              {searchQuery || statusFilter !== 'all'
                ? 'No machines match your search criteria.'
                : 'No machines have been registered yet.'}
            </p>
          </CardContent>
        </Card>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {sortedMachines.map((machine: Machine) => {
            const config = getStatusConfig(machine.status);
            const maintenanceDue = isMaintenanceDue(machine);

            return (
              <Card
                key={machine.id}
                className={`border-2 hover:shadow-lg transition-all cursor-pointer ${config.bgColor}`}
                onClick={() => navigate(`/mechanic/machines/${machine.id}`)}
              >
                <CardContent className="p-6">
                  {/* Header */}
                  <div className="flex items-start justify-between mb-4">
                    <div className="flex items-center gap-3">
                      <div className={`w-4 h-4 rounded-full ${config.color} ${machine.status === 'repair' ? 'animate-pulse' : ''}`} />
                      <Badge variant={config.variant}>{machine.status}</Badge>
                    </div>
                    <span className="text-xs font-mono text-gray-500">
                      {machine.machine_code}
                    </span>
                  </div>

                  {/* Machine Info */}
                  <h3 className="font-bold text-lg text-chocolate-800 mb-1">
                    {machine.name}
                  </h3>
                  <p className="text-sm text-gray-600 mb-3">{machine.type}</p>

                  {/* Location */}
                  <div className="flex items-center gap-2 text-sm text-gray-500 mb-4">
                    <MapPin className="w-4 h-4" />
                    <span>{machine.location}</span>
                  </div>

                  {/* Maintenance Info */}
                  <div className="space-y-2 text-sm">
                    {machine.last_maintenance_date && (
                      <div className="flex items-center justify-between text-gray-600">
                        <span>Last Maintenance:</span>
                        <span>{new Date(machine.last_maintenance_date).toLocaleDateString()}</span>
                      </div>
                    )}
                    {machine.next_maintenance_date && (
                      <div className={`flex items-center justify-between ${maintenanceDue ? 'text-amber-600 font-medium' : 'text-gray-600'}`}>
                        <span>Next Due:</span>
                        <span className="flex items-center gap-1">
                          {maintenanceDue && <AlertTriangle className="w-3 h-3" />}
                          {new Date(machine.next_maintenance_date).toLocaleDateString()}
                        </span>
                      </div>
                    )}
                  </div>

                  {/* Actions */}
                  <div className="flex gap-2 mt-4 pt-4 border-t border-gray-200">
                    <Button
                      variant="outline"
                      size="sm"
                      className="flex-1"
                      onClick={(e) => {
                        e.stopPropagation();
                        navigate(`/mechanic/machines/${machine.id}`);
                      }}
                    >
                      View Details
                    </Button>
                    <Button
                      variant="default"
                      size="sm"
                      className="flex-1"
                      onClick={(e) => {
                        e.stopPropagation();
                        handleLogMaintenance(machine.id);
                      }}
                    >
                      <Wrench className="w-3 h-3 mr-1" />
                      Log
                    </Button>
                  </div>
                </CardContent>
              </Card>
            );
          })}
        </div>
      )}

      {/* Results count */}
      {!isLoading && sortedMachines.length > 0 && (
        <p className="text-sm text-gray-500 text-center">
          Showing {sortedMachines.length} of {machines.length} machines
        </p>
      )}

      {/* Maintenance Log Modal */}
      <MaintenanceLogModal
        isOpen={isMaintenanceModalOpen}
        onClose={() => {
          setIsMaintenanceModalOpen(false);
          setSelectedMachineId(undefined);
        }}
        machineId={selectedMachineId}
      />
    </div>
  );
};

export default MachinesPage;

import React, { useState, useEffect, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  Wrench,
  AlertTriangle,
  Calendar,
  Settings,
  Activity,
  ChevronRight,
  Bell,
  Plus,
  Volume2,
  VolumeX,
  History,
  ShieldAlert,
  Thermometer,
  Zap
} from 'lucide-react';
import { toast } from 'sonner';
import PageHeader from '../../components/layout/PageHeader';
import { Card, CardContent, CardHeader, CardTitle } from '../../components/ui/Card';
import { Button } from '../../components/ui/Button';
import { useMechanic } from '../../hooks/useMechanic';
import { useAuth } from '../../hooks/useAuth';
import MaintenanceLogModal from '../../components/mechanic/MaintenanceLogModal';
import SOSAlertCard from '../../components/mechanic/SOSAlertCard';
import ResolveAlertModal from '../../components/mechanic/ResolveAlertModal';
import { SOSAlert, Machine, MachineStatus, MaintenanceLog } from '../../types';
import { motion } from 'framer-motion';
import { cn } from '../../lib/utils';
import {
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
  AreaChart,
  Area
} from 'recharts';

const HEALTH_DATA = [
  { time: '08:00', health: 98, temp: 42 },
  { time: '10:00', health: 95, temp: 45 },
  { time: '12:00', health: 92, temp: 58 },
  { time: '14:00', health: 88, temp: 65 },
  { time: '16:00', health: 85, temp: 72 },
  { time: '18:00', health: 89, temp: 60 },
];

const containerVariants = {
  hidden: { opacity: 0 },
  visible: {
    opacity: 1,
    transition: { staggerChildren: 0.1 }
  }
};

const itemVariants = {
  hidden: { y: 20, opacity: 0 },
  visible: { y: 0, opacity: 1 }
};

const MechanicDashboard: React.FC = () => {
  const navigate = useNavigate();
  const { useCurrentUser } = useAuth();
  const { data: user } = useCurrentUser();
  const { useMachines, useSOSAlerts, useMaintenanceLogs } = useMechanic();

  const { data: rawMachines = [], isLoading: machinesLoading } = useMachines();
  const machines = useMemo(() => Array.isArray(rawMachines) ? rawMachines : [], [rawMachines]);

  const { data: rawOpenAlerts = [], isLoading: alertsLoading, refetch: refetchAlerts } = useSOSAlerts({ status: 'open' });
  const openAlerts = useMemo(() => Array.isArray(rawOpenAlerts) ? rawOpenAlerts : [], [rawOpenAlerts]);
  
  const { data: rawInProgressAlerts = [] } = useSOSAlerts({ status: 'in_progress' });
  const inProgressAlerts = useMemo(() => Array.isArray(rawInProgressAlerts) ? rawInProgressAlerts : [], [rawInProgressAlerts]);
  
  const { data: rawMaintenanceLogs = [], isLoading: logsLoading } = useMaintenanceLogs({ limit: 5 });
  const maintenanceLogs = useMemo(() => Array.isArray(rawMaintenanceLogs) ? rawMaintenanceLogs : [], [rawMaintenanceLogs]);

  const [isMaintenanceModalOpen, setIsMaintenanceModalOpen] = useState(false);
  const [selectedAlert, setSelectedAlert] = useState<SOSAlert | null>(null);
  const [isResolveModalOpen, setIsResolveModalOpen] = useState(false);
  const [soundEnabled, setSoundEnabled] = useState(true);
  const [previousAlertCount, setPreviousAlertCount] = useState(0);

  const allActiveAlerts = useMemo(() => {
    return [...openAlerts, ...inProgressAlerts].sort((a, b) => {
      const priorityOrder = { critical: 0, high: 1, medium: 2, low: 3 };
      // @ts-ignore - Index signature for priorityOrder
      return (priorityOrder[a.priority] || 99) - (priorityOrder[b.priority] || 99);
    });
  }, [openAlerts, inProgressAlerts]);

  useEffect(() => {
    const criticalCount = openAlerts.filter(a => a.priority === 'critical').length;
    if (soundEnabled && criticalCount > previousAlertCount) {
      // Audio file missing, disabled for now to prevent errors
      // const audio = new Audio('/sounds/alert.mp3');
      // audio.play().catch(() => {});
      console.log('Playing alert sound (simulated)');
      toast.error('New Critical Alert!', {
        description: 'A critical SOS alert requires immediate attention.',
        duration: 10000,
      });
    }
    setPreviousAlertCount(criticalCount);
  }, [openAlerts, soundEnabled, previousAlertCount]);

  useEffect(() => {
    const interval = setInterval(() => {
      void refetchAlerts();
    }, 10000);
    return () => clearInterval(interval);
  }, [refetchAlerts]);

  const operationalMachines = machines.filter((m: Machine) => m.status === 'operational').length;
  const maintenanceDueThisWeek = machines.filter((m: Machine) => {
    if (!m.next_maintenance_date) return false;
    const nextMaintenance = new Date(m.next_maintenance_date);
    const now = new Date();
    const oneWeekLater = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000);
    return nextMaintenance <= oneWeekLater && nextMaintenance >= now;
  }).length;

  const handleViewAlert = (alert: SOSAlert) => {
    setSelectedAlert(alert);
    setIsResolveModalOpen(true);
  };

  const handleAlertResolved = () => {
    setIsResolveModalOpen(false);
    setSelectedAlert(null);
    void refetchAlerts();
  };

  const getStatusColor = (status: MachineStatus) => {
    switch (status) {
      case 'operational': return 'bg-emerald-500';
      case 'maintenance': return 'bg-amber-500';
      case 'repair': return 'bg-rose-500';
      case 'offline': return 'bg-slate-500';
      case 'standby': return 'bg-sky-500';
      default: return 'bg-slate-400';
    }
  };

  const hasCriticalAlerts = Array.isArray(openAlerts) && openAlerts.some((a: SOSAlert) => a.priority === 'critical' || a.priority === 'high');

  return (
    <motion.div 
      className="space-y-8 pb-20"
      initial="hidden"
      animate="visible"
      variants={containerVariants}
    >
      <div className="flex flex-col md:flex-row md:items-end justify-between gap-8">
        <PageHeader
          title="Maintenance Command"
          subtitle={`Unit Diagnostics & Asset Orchestration for Lead Mechanic ${user?.full_name?.split(' ')[1] ?? ''}.`}
        />
        <div className="flex items-center gap-4 bg-white/70 backdrop-blur-xl p-3 rounded-[2rem] border border-chocolate-100 shadow-xl shadow-chocolate-200/10">
          <Button
            variant="ghost"
            className="w-14 h-14 rounded-2xl bg-white shadow-inner border border-chocolate-50 hover:bg-chocolate-50 transition-all duration-500 group"
            onClick={() => setSoundEnabled(!soundEnabled)}
          >
            {soundEnabled ? (
              <Volume2 className="w-6 h-6 text-chocolate-900 group-hover:scale-110 transition-transform" />
            ) : (
              <VolumeX className="w-6 h-6 text-slate-300" />
            )}
          </Button>
          <Button
            variant="default"
            onClick={() => navigate('/mechanic/alerts')}
            className="h-14 px-8 rounded-2xl bg-chocolate-950 text-white font-black hover:bg-chocolate-900 transition-all shadow-xl shadow-chocolate-200/20 gap-3 group relative overflow-hidden"
          >
            <div className="absolute inset-0 bg-gold-500/10 translate-y-full group-hover:translate-y-0 transition-transform duration-500" />
            <Bell className="w-5 h-5 relative z-10 group-hover:rotate-12 transition-transform" />
            <span className="relative z-10 tracking-[0.1em]">LIVE ALERTS</span>
            {allActiveAlerts.length > 0 && (
              <span className="relative z-10 ml-2 px-3 py-1 bg-vibrant-amber text-chocolate-950 rounded-full text-[10px] font-black shadow-[0_0_10px_#f59e0b]">
                {allActiveAlerts.length}
              </span>
            )}
          </Button>
        </div>
      </div>

      {hasCriticalAlerts && (
        <motion.div 
          initial={{ scale: 0.98, opacity: 0 }}
          animate={{ scale: 1, opacity: 1 }}
          className="bg-vibrant-red rounded-[3rem] p-8 shadow-2xl relative overflow-hidden border-4 border-vibrant-red/50 group"
        >
          <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,_var(--tw-gradient-stops))] from-white/10 via-transparent to-transparent opacity-50 group-hover:scale-110 transition-transform duration-1000" />
          <div className="absolute top-0 right-0 p-10 opacity-10">
            <ShieldAlert className="w-48 h-48 text-white group-hover:rotate-12 transition-transform duration-1000" />
          </div>
          <div className="relative z-10">
            <div className="flex items-center gap-6 mb-8">
              <div className="p-4 bg-white/20 rounded-3xl backdrop-blur-xl shadow-2xl ring-1 ring-white/30">
                <AlertTriangle className="w-10 h-10 text-white animate-pulse" />
              </div>
              <div>
                <h2 className="text-3xl font-black text-white tracking-tight uppercase">Emergency Response Vector</h2>
                <p className="text-white/80 font-bold uppercase tracking-widest text-xs mt-1">
                  {openAlerts.filter((a: SOSAlert) => a.priority === 'critical').length} Critical Faults • {openAlerts.filter((a: SOSAlert) => a.priority === 'high').length} High Priority Interrupts
                </p>
              </div>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {openAlerts
                .filter((a: SOSAlert) => a.priority === 'critical' || a.priority === 'high')
                .slice(0, 3)
                .map((alert: SOSAlert) => (
                  <SOSAlertCard
                    key={alert.id}
                    alert={alert}
                    onRespond={() => handleViewAlert(alert)}
                    compact
                  />
                ))}
            </div>
          </div>
        </motion.div>
      )}

      <motion.div className="grid grid-cols-1 md:grid-cols-3 gap-8" variants={itemVariants}>
        <div className="bg-vibrant-green text-white p-8 rounded-[2.5rem] shadow-xl shadow-vibrant-green/10 relative overflow-hidden group hover:scale-[1.02] transition-all duration-500">
          <div className="absolute -right-4 -bottom-4 w-32 h-32 bg-white/10 rounded-full blur-3xl group-hover:bg-white/20 transition-colors" />
          <Wrench className="absolute -bottom-6 -right-6 w-32 h-32 opacity-10 group-hover:rotate-12 transition-transform duration-700" />
          <p className="text-[10px] font-black uppercase tracking-[0.2em] opacity-60 mb-2">Operational Fleet</p>
          <div className="flex items-baseline gap-3 relative z-10">
            <h4 className="text-5xl font-black tracking-tight">{operationalMachines}</h4>
            <span className="text-sm font-bold opacity-60 uppercase tracking-widest">/ {machines.length} Units</span>
          </div>
        </div>
        <div className={`p-8 rounded-[2.5rem] shadow-xl relative overflow-hidden group hover:scale-[1.02] transition-all duration-500 ${allActiveAlerts.length > 0 ? 'bg-chocolate-950 text-white shadow-chocolate-950/10' : 'bg-white border border-chocolate-100 text-chocolate-300'}`}>
          <div className="absolute -right-4 -bottom-4 w-32 h-32 bg-vibrant-red/10 rounded-full blur-3xl" />
          <AlertTriangle className="absolute -bottom-6 -right-6 w-32 h-32 opacity-10 group-hover:scale-110 transition-transform duration-700" />
          <p className="text-[10px] font-black uppercase tracking-[0.2em] opacity-60 mb-2">Incident Vector</p>
          <h4 className="text-5xl font-black tracking-tight relative z-10">{allActiveAlerts.length}</h4>
          {openAlerts.filter(a => a.priority === 'critical').length > 0 && (
            <span className="inline-block mt-3 px-3 py-1 bg-vibrant-red text-white rounded-full text-[9px] font-black tracking-widest uppercase animate-pulse shadow-[0_0_15px_rgba(239,68,68,0.5)]">CRITICAL FAULT</span>
          )}
        </div>
        <div className="bg-gold-500 text-chocolate-950 p-8 rounded-[2.5rem] shadow-xl shadow-gold-500/10 relative overflow-hidden group hover:scale-[1.02] transition-all duration-500">
          <div className="absolute -right-4 -bottom-4 w-32 h-32 bg-white/20 rounded-full blur-3xl" />
          <Calendar className="absolute -bottom-6 -right-6 w-32 h-32 opacity-10 group-hover:-rotate-12 transition-transform duration-700" />
          <p className="text-[10px] font-black uppercase tracking-[0.2em] opacity-60 mb-2">Preventative Queue</p>
          <h4 className="text-5xl font-black tracking-tight relative z-10">{maintenanceDueThisWeek}</h4>
          <span className="text-[10px] font-black uppercase tracking-widest opacity-60">Next 168 Hours</span>
        </div>
      </motion.div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <motion.div className="lg:col-span-2 space-y-8" variants={itemVariants}>
          <Card className="rounded-[3rem] border-none bg-white p-1 shadow-xl shadow-chocolate-900/5 overflow-hidden">
            <CardHeader className="flex flex-row items-center justify-between border-b border-chocolate-50 p-10">
              <div>
                <CardTitle className="text-2xl font-black text-chocolate-950 flex items-center gap-4 uppercase tracking-tight">
                  <div className="p-3 bg-chocolate-100 rounded-2xl">
                    <Settings className="w-6 h-6 text-chocolate-600" />
                  </div>
                  Asset Health Matrix
                </CardTitle>
                <p className="text-[10px] font-black text-chocolate-400 tracking-[0.2em] uppercase mt-2">Fleet Diagnostic Overview</p>
              </div>
              <Button variant="ghost" className="text-[10px] font-black text-chocolate-400 hover:text-gold-600 transition-colors uppercase tracking-[0.2em] group" onClick={() => navigate('/mechanic/machines')}>
                FULL INVENTORY <ChevronRight className="w-3 h-3 ml-2 group-hover:translate-x-1 transition-transform" />
              </Button>
            </CardHeader>
            <CardContent className="p-10">
              {machinesLoading ? (
                <div className="grid grid-cols-2 md:grid-cols-3 gap-4 animate-pulse">
                  {Array.from({ length: 6 }).map((_, i) => <div key={i} className="h-40 bg-chocolate-50 rounded-2xl" />)}
                </div>
              ) : (
                <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
                  {machines.slice(0, 6).map((machine: Machine) => (
                    <button
                      key={machine.id}
                      onClick={() => navigate(`/mechanic/machines/${machine.id}`)}
                      className={`p-6 rounded-[2.5rem] border border-chocolate-100/50 transition-all duration-500 hover:shadow-2xl hover:shadow-chocolate-200/40 hover:-translate-y-2 text-left relative overflow-hidden group bg-white`}
                    >
                      <div className="absolute inset-0 bg-gradient-to-br from-white via-white to-chocolate-50/30" />
                      <div className="relative z-10">
                        <div className="flex items-center justify-between mb-6">
                          <div className={`w-3.5 h-3.5 rounded-full ${getStatusColor(machine.status)} ${machine.status === 'repair' ? 'animate-pulse shadow-[0_0_15px_rgba(244,63,94,0.8)]' : ''}`} />
                          <span className="text-[10px] font-black text-chocolate-300 font-mono tracking-widest uppercase">{machine.machine_code}</span>
                        </div>
                        <h4 className="font-black text-chocolate-950 text-base mb-1 truncate tracking-tight uppercase group-hover:text-gold-600 transition-colors">{machine.name}</h4>
                        <p className="text-[10px] text-chocolate-400 font-bold mb-6 uppercase tracking-widest">{machine.type}</p>
                        <div className="flex items-center justify-between mt-auto">
                           <div className={cn(
                             "text-[9px] font-black uppercase rounded-xl px-3 py-1 tracking-widest border shadow-sm",
                             machine.status === 'operational' ? 'bg-vibrant-green/10 text-vibrant-green border-vibrant-green/20' :
                             machine.status === 'maintenance' ? 'bg-vibrant-amber/10 text-vibrant-amber border-vibrant-amber/20' :
                             'bg-vibrant-red/10 text-vibrant-red border-vibrant-red/20'
                           )}>
                             {machine.status}
                           </div>
                           <Activity className="w-5 h-5 text-chocolate-100 group-hover:text-gold-500 group-hover:scale-110 transition-all duration-500" />
                        </div>
                      </div>
                    </button>
                  ))}
                </div>
              )}
            </CardContent>
          </Card>

          <Card className="rounded-3xl border-none bg-white/70 backdrop-blur-md shadow-sm overflow-hidden p-6">
             <div className="flex items-center justify-between mb-8">
                <h3 className="text-xl font-black text-chocolate-900 uppercase tracking-tighter flex items-center gap-2">
                  <Thermometer className="w-6 h-6 text-rose-500" /> System Telemetry
                </h3>
                <div className="flex gap-4 text-[10px] font-black uppercase">
                   <span className="flex items-center gap-1 text-chocolate-400"><div className="w-2 h-2 rounded-full bg-emerald-500" /> HEALTH</span>
                   <span className="flex items-center gap-1 text-chocolate-400"><div className="w-2 h-2 rounded-full bg-rose-500" /> TEMP</span>
                </div>
             </div>
             <div className="h-[250px]">
                <ResponsiveContainer width="100%" height="100%">
                   <AreaChart data={HEALTH_DATA}>
                      <defs>
                        <linearGradient id="colorHealth" x1="0" y1="0" x2="0" y2="1">
                          <stop offset="5%" stopColor="#10b981" stopOpacity={0.1}/>
                          <stop offset="95%" stopColor="#10b981" stopOpacity={0}/>
                        </linearGradient>
                      </defs>
                      <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                      <XAxis dataKey="time" axisLine={false} tickLine={false} tick={{ fontSize: 10, fontWeight: 'bold' }} />
                      <YAxis hide />
                      <Tooltip contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 20px 25px -5px rgb(0 0 0 / 0.1)' }} />
                      <Area type="monotone" dataKey="health" stroke="#10b981" strokeWidth={3} fillOpacity={1} fill="url(#colorHealth)" />
                      <Line type="monotone" dataKey="temp" stroke="#f43f5e" strokeWidth={2} dot={false} strokeDasharray="5 5" />
                   </AreaChart>
                </ResponsiveContainer>
             </div>
          </Card>
        </motion.div>

        <motion.div className="space-y-8" variants={itemVariants}>
          <Card className="rounded-3xl border-none bg-chocolate-900 text-white shadow-xl overflow-hidden relative min-h-[400px]">
            <img src="/assets/edit 6.png" className="absolute inset-0 w-full h-full object-cover opacity-20" alt="Repair" />
            <CardHeader className="relative z-10 p-6 border-b border-white/10">
              <CardTitle className="text-xl font-black flex items-center gap-3 uppercase tracking-tighter">
                <ShieldAlert className="w-6 h-6 text-amber-400" />
                Active Incident Log
              </CardTitle>
            </CardHeader>
            <CardContent className="relative z-10 p-6">
              {alertsLoading ? (
                <div className="space-y-4 animate-pulse">
                   {Array.from({ length: 3 }).map((_, i) => <div key={i} className="h-20 bg-white/5 rounded-2xl" />)}
                </div>
              ) : allActiveAlerts.length === 0 ? (
                <div className="text-center py-12 flex flex-col items-center">
                   <Zap className="w-12 h-12 text-amber-400 mb-4 opacity-20" />
                   <p className="text-sm font-black text-white/40 uppercase tracking-widest">Zero Active Incidents</p>
                </div>
              ) : (
                <div className="space-y-4 max-h-[500px] overflow-y-auto pr-2 custom-scrollbar">
                  {allActiveAlerts.map((alert: SOSAlert) => (
                    <SOSAlertCard
                      key={alert.id}
                      alert={alert}
                      onRespond={() => handleViewAlert(alert)}
                      compact
                    />
                  ))}
                </div>
              )}
            </CardContent>
          </Card>

          <Card className="rounded-3xl border-none bg-white/70 backdrop-blur-md shadow-sm overflow-hidden p-6">
             <h3 className="text-lg font-black text-chocolate-900 mb-6 flex items-center gap-3 uppercase tracking-tight">
               <History className="w-6 h-6 text-chocolate-400" />
               Recent Clearances
             </h3>
             <div className="space-y-4">
                {logsLoading ? (
                  <div className="space-y-3 animate-pulse">
                     {Array.from({ length: 3 }).map((_, i) => <div key={i} className="h-12 bg-chocolate-50 rounded-xl" />)}
                  </div>
                ) : (
                  maintenanceLogs.slice(0, 4).map((log: MaintenanceLog) => (
                    <div key={log.id} className="p-4 bg-chocolate-50/50 rounded-2xl border border-chocolate-100 hover:bg-white transition-all group">
                       <div className="flex items-center justify-between mb-2">
                          <span className="text-xs font-black text-chocolate-900 uppercase tracking-tighter truncate w-2/3">{log.machine_name}</span>
                          <span className="text-[8px] font-black px-2 py-0.5 rounded-full bg-chocolate-200 text-chocolate-700 uppercase">{log.maintenance_type}</span>
                       </div>
                       <p className="text-[10px] text-chocolate-400 font-medium line-clamp-1">{log.description}</p>
                    </div>
                  ))
                )}
             </div>
          </Card>
        </motion.div>
      </div>

      <motion.div 
        initial={{ y: 50, opacity: 0 }}
        animate={{ y: 0, opacity: 1 }}
        className="fixed bottom-8 right-8 flex flex-col gap-4 z-50"
      >
        <Button
          variant="default"
          size="lg"
          className="rounded-full w-20 h-20 bg-chocolate-950 text-white shadow-2xl hover:bg-black hover:scale-110 transition-all duration-500 flex items-center justify-center group ring-8 ring-chocolate-950/10"
          onClick={() => setIsMaintenanceModalOpen(true)}
        >
          <div className="absolute inset-0 bg-gold-500/10 scale-0 group-hover:scale-100 transition-transform duration-700 rounded-full" />
          <Plus className="w-10 h-10 group-hover:rotate-180 transition-transform duration-700 relative z-10" />
        </Button>
      </motion.div>

      <MaintenanceLogModal
        isOpen={isMaintenanceModalOpen}
        onClose={() => setIsMaintenanceModalOpen(false)}
      />

      {selectedAlert && (
        <ResolveAlertModal
          isOpen={isResolveModalOpen}
          onClose={() => {
            setIsResolveModalOpen(false);
            setSelectedAlert(null);
          }}
          alert={selectedAlert}
          onResolved={handleAlertResolved}
        />
      )}
    </motion.div>
  );
};

export default MechanicDashboard;

import React, { useState, useEffect } from 'react';
import {
  AlertTriangle,
  Filter,
  Search,
  RefreshCw,
  Bell,
  Clock,
  CheckCircle,
} from 'lucide-react';
import { toast } from 'sonner';
import PageHeader from '../../components/layout/PageHeader';
import { Card, CardContent } from '../../components/ui/Card';
import { Button } from '../../components/ui/Button';
import { Input } from '../../components/ui/Input';
import { Badge } from '../../components/ui/Badge';
import SOSAlertCard from '../../components/mechanic/SOSAlertCard';
import ResolveAlertModal from '../../components/mechanic/ResolveAlertModal';
import { useMechanic } from '../../hooks/useMechanic';
import { SOSAlert, AlertPriority, AlertStatus } from '../../types';

type TabType = 'open' | 'in_progress' | 'resolved' | 'all';

const SOSAlertsPage: React.FC = () => {
  const { useSOSAlerts } = useMechanic();

  // State
  const [activeTab, setActiveTab] = useState<TabType>('open');
  const [searchQuery, setSearchQuery] = useState('');
  const [priorityFilter, setPriorityFilter] = useState<AlertPriority | 'all'>('all');
  const [selectedAlert, setSelectedAlert] = useState<SOSAlert | null>(null);
  const [isResolveModalOpen, setIsResolveModalOpen] = useState(false);

  // Fetch alerts based on active tab
  const statusFilter = activeTab === 'all' ? undefined : activeTab;
  const {
    data: rawAlerts = [],
    isLoading,
    refetch,
    isRefetching
  } = useSOSAlerts({
    status: statusFilter as AlertStatus | undefined,
    priority: priorityFilter === 'all' ? undefined : priorityFilter,
  });
  
  const alerts = Array.isArray(rawAlerts) ? rawAlerts : [];

  // Auto-refresh alerts every 15 seconds
  useEffect(() => {
    const interval = setInterval(() => {
      void refetch();
    }, 15000);
    return () => clearInterval(interval);
  }, [refetch]);

  // Filter alerts by search query
  const filteredAlerts = alerts.filter((alert: SOSAlert) => {
    if (!searchQuery) return true;
    const query = searchQuery.toLowerCase();
    return (
      alert.machine_name?.toLowerCase().includes(query) ||
      alert.machine_code?.toLowerCase().includes(query) ||
      alert.problem_description.toLowerCase().includes(query)
    );
  });

  // Sort alerts by priority and time
  const sortedAlerts = [...filteredAlerts].sort((a, b) => {
    const priorityOrder = { critical: 0, high: 1, medium: 2, low: 3 };
    const priorityDiff = priorityOrder[a.priority] - priorityOrder[b.priority];
    if (priorityDiff !== 0) return priorityDiff;
    return new Date(b.reported_at).getTime() - new Date(a.reported_at).getTime();
  });

  const handleRespond = (alert: SOSAlert) => {
    setSelectedAlert(alert);
    setIsResolveModalOpen(true);
  };

  const handleAlertResolved = () => {
    setIsResolveModalOpen(false);
    setSelectedAlert(null);
    void refetch();
    toast.success('Alert updated successfully');
  };

  const tabs = [
    { id: 'open' as TabType, label: 'Open', icon: AlertTriangle, color: 'text-red-600' },
    { id: 'in_progress' as TabType, label: 'In Progress', icon: Clock, color: 'text-amber-600' },
    { id: 'resolved' as TabType, label: 'Resolved', icon: CheckCircle, color: 'text-green-600' },
    { id: 'all' as TabType, label: 'All', icon: Bell, color: 'text-gray-600' },
  ];

  const priorities: { value: AlertPriority | 'all'; label: string; color: string }[] = [
    { value: 'all', label: 'All Priorities', color: 'bg-gray-100 text-gray-700' },
    { value: 'critical', label: 'Critical', color: 'bg-red-100 text-red-700' },
    { value: 'high', label: 'High', color: 'bg-red-50 text-red-600' },
    { value: 'medium', label: 'Medium', color: 'bg-amber-100 text-amber-700' },
    { value: 'low', label: 'Low', color: 'bg-gray-100 text-gray-600' },
  ];

  // Count alerts by status for badges
  const { data: rawOpenAlerts = [] } = useSOSAlerts({ status: 'open' });
  const openAlerts = Array.isArray(rawOpenAlerts) ? rawOpenAlerts : [];
  
  const { data: rawInProgressAlerts = [] } = useSOSAlerts({ status: 'in_progress' });
  const inProgressAlerts = Array.isArray(rawInProgressAlerts) ? rawInProgressAlerts : [];

  return (
    <div className="space-y-6">
      {/* Header */}
      <PageHeader
        title="SOS Alerts"
        subtitle="Manage and respond to machine emergency alerts"
        actions={
          <Button
            variant="outline"
            onClick={() => { void refetch(); }}
            disabled={isRefetching}
            className="gap-2"
          >
            <RefreshCw className={`w-4 h-4 ${isRefetching ? 'animate-spin' : ''}`} />
            Refresh
          </Button>
        }
      />

      {/* Stats Overview */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        <Card className="bg-red-50 border-red-200">
          <CardContent className="p-4">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-xs text-red-600 font-medium">Open Alerts</p>
                <p className="text-2xl font-bold text-red-800">{openAlerts.length}</p>
              </div>
              <AlertTriangle className="w-8 h-8 text-red-400" />
            </div>
          </CardContent>
        </Card>
        <Card className="bg-amber-50 border-amber-200">
          <CardContent className="p-4">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-xs text-amber-600 font-medium">In Progress</p>
                <p className="text-2xl font-bold text-amber-800">{inProgressAlerts.length}</p>
              </div>
              <Clock className="w-8 h-8 text-amber-400" />
            </div>
          </CardContent>
        </Card>
        <Card className="bg-red-50 border-red-300">
          <CardContent className="p-4">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-xs text-red-600 font-medium">Critical</p>
                <p className="text-2xl font-bold text-red-800">
                  {openAlerts.filter((a: SOSAlert) => a.priority === 'critical').length}
                </p>
              </div>
              <AlertTriangle className="w-8 h-8 text-red-500 animate-pulse" />
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="p-4">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-xs text-gray-600 font-medium">Total Today</p>
                <p className="text-2xl font-bold text-gray-800">{alerts.length}</p>
              </div>
              <Bell className="w-8 h-8 text-gray-400" />
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Tabs */}
      <div className="border-b border-gray-200">
        <div className="flex gap-1">
          {tabs.map((tab) => {
            const Icon = tab.icon;
            const count = tab.id === 'open'
              ? openAlerts.length
              : tab.id === 'in_progress'
              ? inProgressAlerts.length
              : undefined;

            return (
              <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id)}
                className={`flex items-center gap-2 px-4 py-3 border-b-2 transition-colors ${
                  activeTab === tab.id
                    ? 'border-chocolate-600 text-chocolate-700 bg-chocolate-50'
                    : 'border-transparent text-gray-500 hover:text-gray-700 hover:bg-gray-50'
                }`}
              >
                <Icon className={`w-4 h-4 ${activeTab === tab.id ? tab.color : ''}`} />
                <span className="font-medium">{tab.label}</span>
                {count !== undefined && count > 0 && (
                  <Badge
                    variant={tab.id === 'open' ? 'error' : 'warning'}
                    className="text-xs"
                  >
                    {count}
                  </Badge>
                )}
              </button>
            );
          })}
        </div>
      </div>

      {/* Filters */}
      <div className="flex flex-col md:flex-row gap-4">
        {/* Search */}
        <div className="flex-1 relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
          <Input
            type="text"
            placeholder="Search by machine name or code..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="pl-10"
          />
        </div>

        {/* Priority Filter */}
        <div className="flex items-center gap-2">
          <Filter className="w-4 h-4 text-gray-400" />
          <select
            value={priorityFilter}
            onChange={(e) => setPriorityFilter(e.target.value as AlertPriority | 'all')}
            className="px-3 py-2 bg-white border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-2 focus:ring-chocolate-500 focus:border-chocolate-500 text-sm"
          >
            {priorities.map((p) => (
              <option key={p.value} value={p.value}>
                {p.label}
              </option>
            ))}
          </select>
        </div>
      </div>

      {/* Alerts List */}
      <div className="space-y-4">
        {isLoading ? (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {Array.from({ length: 4 }).map((_, i) => (
              <div key={i} className="h-48 bg-gray-100 rounded-xl animate-pulse" />
            ))}
          </div>
        ) : sortedAlerts.length === 0 ? (
          <Card className="py-12">
            <CardContent className="text-center">
              <Bell className="w-16 h-16 text-gray-300 mx-auto mb-4" />
              <h3 className="text-lg font-semibold text-gray-700 mb-2">
                No alerts found
              </h3>
              <p className="text-gray-500">
                {activeTab === 'open'
                  ? 'Great news! There are no open alerts at this time.'
                  : searchQuery
                  ? 'No alerts match your search criteria.'
                  : `No ${activeTab.replace('_', ' ')} alerts to display.`}
              </p>
            </CardContent>
          </Card>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {sortedAlerts.map((alert: SOSAlert) => (
              <SOSAlertCard
                key={alert.id}
                alert={alert}
                onRespond={() => handleRespond(alert)}
                onResolve={() => handleRespond(alert)}
              />
            ))}
          </div>
        )}
      </div>

      {/* Results count */}
      {!isLoading && sortedAlerts.length > 0 && (
        <p className="text-sm text-gray-500 text-center">
          Showing {sortedAlerts.length} alert{sortedAlerts.length !== 1 ? 's' : ''}
        </p>
      )}

      {/* Resolve Modal */}
      {selectedAlert && (
        <ResolveAlertModal
          isOpen={isResolveModalOpen}
          onClose={() => {
            setIsResolveModalOpen(false);
            setSelectedAlert(null);
          }}
          alert={selectedAlert}
          onResolved={handleAlertResolved}
        />
      )}
    </div>
  );
};

export default SOSAlertsPage;

import { useEffect, useState } from 'react';
import { mechanicService } from '../../services/mechanicService';
import { MachineFix } from '../../types';
import { Card, CardHeader, CardTitle, CardContent } from '../../components/ui/Card';
import { Button } from '../../components/ui/Button';
import { Wrench, CheckCircle2 } from 'lucide-react';
import { Input } from '../../components/ui/Input';

const MechanicPage = () => {
    const [logs, setLogs] = useState<MachineFix[]>([]);
    const [itemsLoading, setItemsLoading] = useState(true);

    useEffect(() => {
        const fetchLogs = async () => {
            try {
                const data = await mechanicService.getAllFixes();
                setLogs(data);
            } catch (error) {
                console.error('Failed to load fixes:', error);
            } finally {
                setItemsLoading(false);
            }
        };
        void fetchLogs();
    }, []);

    const isOpen = (status: MachineFix['status']) => status !== 'FIXED';

    return (
        <div className="space-y-6">
            <h1 className="text-3xl font-bold tracking-tight">Mechanic Maintenance Logs</h1>

             <Card className="bg-slate-50 border-slate-200">
                <CardHeader>
                    <CardTitle className="text-lg">Report New Issue</CardTitle>
                </CardHeader>
                <CardContent>
                    <div className="flex gap-4">
                        <Input placeholder="Machine ID (e.g. M-101)" className="w-40" />
                        <Input placeholder="Describe the issue..." className="flex-1" />
                        <Button className="bg-red-600 hover:bg-red-700">Report</Button>
                    </div>
                </CardContent>
            </Card>
            
            <div className="grid gap-4">
                {itemsLoading ? <p>Loading...</p> : logs.length === 0 ? (
                    <p className="text-muted-foreground">No maintenance logs found</p>
                ) : logs.map(log => (
                    <Card key={log.id} className={isOpen(log.status) ? 'border-l-4 border-l-red-500' : 'border-l-4 border-l-green-500'}>
                        <CardContent className="p-6 flex items-center justify-between">
                            <div className="flex items-start gap-4">
                                <div className={`p-3 rounded-full ${isOpen(log.status) ? 'bg-red-100 text-red-600' : 'bg-green-100 text-green-600'}`}>
                                    <Wrench className="h-6 w-6" />
                                </div>
                                <div>
                                    <h3 className="font-bold text-lg">{log.machine_name ?? 'Unknown Machine'}</h3>
                                    <p className="text-slate-600">{log.description}</p>
                                    <p className="text-xs text-muted-foreground mt-1">
                                        Reported: {new Date(log.created_at).toLocaleString()} • Status: {log.status}
                                    </p>
                                </div>
                            </div>
                            <div>
                                {isOpen(log.status) ? (
                                    <Button>Mark as Fixed</Button>
                                ) : (
                                    <span className="flex items-center gap-1 text-green-600 font-medium">
                                        <CheckCircle2 className="h-4 w-4" /> Resolved
                                    </span>
                                )}
                            </div>
                        </CardContent>
                    </Card>
                ))}
            </div>
        </div>
    );
};

export default MechanicPage;

import React from 'react';
import { useParams, Link } from 'react-router-dom';
import { useProduction } from '../../hooks/useProduction';
import { 
  ArrowLeft, 
  CheckCircle2, 
  XCircle, 
  Play, 
  Clock,
  FlaskConical,
  Flame,
  ThermometerSnowflake,
  Box,
  Loader2,
  ChevronRight
} from 'lucide-react';
import { toast } from 'sonner';
import { BatchStatus } from '../../types';

const BatchDetailPage: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const { useBatch, useUpdateBatchStatus } = useProduction();
  
  const { data: batch, isLoading } = useBatch(id!);
  const updateStatusMutation = useUpdateBatchStatus();

  const handleStatusUpdate = async (newStatus: BatchStatus) => {
    if (!batch) return;
    try {
      await updateStatusMutation.mutateAsync({ id: batch.id, status: newStatus });
      toast.success(`Batch updated to ${newStatus}`);
    } catch (error) {
      toast.error('Failed to update batch status.');
    }
  };

  if (isLoading) {
    return (
      <div className="flex h-96 items-center justify-center">
        <Loader2 className="w-8 h-8 animate-spin text-primary" />
      </div>
    );
  }

  if (!batch) {
    return (
      <div className="text-center py-20">
        <h3 className="text-xl font-bold text-chocolate-900">Batch not found</h3>
        <Link to="/batches" className="text-chocolate-600 hover:text-chocolate-800 mt-2 inline-block font-medium">Back to list</Link>
      </div>
    );
  }

  const steps = [
    { status: 'pending', label: 'Draft', icon: Clock },
    { status: 'mixing', label: 'Mixing', icon: FlaskConical },
    { status: 'cooking', label: 'Cooking', icon: Flame },
    { status: 'cooling', label: 'Cooling', icon: ThermometerSnowflake },
    { status: 'packaging', label: 'Packaging', icon: Box },
    { status: 'completed', label: 'Completed', icon: CheckCircle2 },
  ];

  const currentStepIndex = steps.findIndex(s => s.status === batch.status);

  return (
    <div className="space-y-6 pb-20">
      <Link to="/batches" className="flex items-center gap-1 text-sm text-chocolate-600 hover:text-chocolate-900 transition-colors font-medium">
        <ArrowLeft className="w-4 h-4" /> Back to Batches
      </Link>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Progress & Controls */}
        <div className="lg:col-span-2 space-y-6">
          <div className="bg-white p-8 rounded-[2rem] border border-chocolate-100 shadow-sm relative overflow-hidden">
            <div className="absolute top-0 right-0 w-32 h-32 bg-chocolate-50/50 rounded-full blur-3xl -translate-y-1/2 translate-x-1/2" />
            <div className="flex justify-between items-center mb-10 relative z-10">
              <div>
                <h1 className="text-3xl font-black text-chocolate-900 tracking-tight">Batch #{batch.batchNumber}</h1>
                <p className="text-sm font-medium text-chocolate-600 mt-1">{batch.recipeName ?? 'Premium Recipe'}</p>
              </div>
              <div className="text-right">
                <p className="text-[10px] text-chocolate-400 uppercase tracking-[0.2em] font-black">Planned Quantity</p>
                <div className="flex items-baseline justify-end gap-1">
                  <p className="text-3xl font-black text-chocolate-900">{batch.targetQuantity}</p>
                  <span className="text-xs font-bold text-chocolate-400 uppercase">UNITS</span>
                </div>
              </div>
            </div>

            {/* Stepper Progress */}
            <div className="relative mb-12">
              <div className="absolute top-5 left-0 right-0 h-1 bg-chocolate-50 rounded-full" />
              <div 
                className="absolute top-5 left-0 h-1 bg-gradient-to-r from-chocolate-500 to-gold-500 rounded-full transition-all duration-700 ease-out shadow-[0_0_10px_#cf9a3c]" 
                style={{ width: `${(currentStepIndex / (steps.length - 1)) * 100}%` }}
              />
              
              <div className="relative flex justify-between">
                {steps.slice(0, 6).map((step, idx) => {
                  const Icon = step.icon;
                  const isActive = idx === currentStepIndex;
                  const isCompleted = idx < currentStepIndex;
                  
                  return (
                    <div key={idx} className="flex flex-col items-center group cursor-default">
                      <div 
                        className={`w-10 h-10 rounded-full flex items-center justify-center z-10 border-2 transition-all duration-300 ${
                          isActive 
                            ? 'bg-chocolate-900 border-chocolate-900 text-gold-500 shadow-lg shadow-chocolate-900/30 scale-125' 
                            : isCompleted 
                              ? 'bg-chocolate-500 border-chocolate-500 text-white' 
                              : 'bg-white border-chocolate-100 text-chocolate-200'
                        }`}
                      >
                        {isCompleted ? <CheckCircle2 className="w-5 h-5" /> : <Icon className="w-5 h-5" />}
                      </div>
                      <span className={`mt-4 text-[10px] font-black uppercase tracking-widest transition-colors ${
                        isActive ? 'text-chocolate-900 translate-y-0 opacity-100' : 'text-chocolate-300'
                      }`}>
                        {step.label}
                      </span>
                    </div>
                  );
                })}
              </div>
            </div>

            {/* Interactive Area */}
            <div className="p-8 bg-chocolate-50/50 rounded-3xl border border-chocolate-100/50 relative overflow-hidden">
               <div className="absolute top-0 right-0 w-64 h-64 bg-white/40 rounded-full blur-3xl -translate-y-1/2 translate-x-1/2" />
               <h3 className="text-sm font-black text-chocolate-950 mb-6 uppercase tracking-widest relative z-10">Production Gateway</h3>
               
               {batch.status === 'completed' || batch.status === 'failed' ? (
                 <div className="text-center py-6 relative z-10">
                    <CheckCircle2 className={`w-16 h-16 mx-auto mb-4 ${batch.status === 'completed' ? 'text-emerald-500' : 'text-red-500'}`} />
                    <h4 className="text-2xl font-black capitalize text-chocolate-900">Batch {batch.status}</h4>
                    <p className="text-chocolate-500 mt-2 font-medium">Workflow cycle finalized.</p>
                 </div>
               ) : (
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 relative z-10">
                  {currentStepIndex < steps.length - 1 && (
                    <button 
                      onClick={() => handleStatusUpdate(steps[currentStepIndex + 1].status as BatchStatus)}
                      className="flex items-center justify-center gap-2 bg-chocolate-900 text-gold-500 py-4 rounded-xl font-black hover:bg-chocolate-800 transition-all shadow-lg shadow-chocolate-900/10 active:scale-[0.98] uppercase tracking-wide text-sm"
                    >
                      <Play className="w-4 h-4" />
                      Start {steps[currentStepIndex + 1].label}
                    </button>
                  )}
                  
                  <button 
                    onClick={() => handleStatusUpdate('completed')}
                    className="flex items-center justify-center gap-2 bg-emerald-600 text-white py-4 rounded-xl font-bold hover:bg-emerald-700 transition-all shadow-lg shadow-emerald-600/20 active:scale-[0.98] uppercase tracking-wide text-sm"
                  >
                    <CheckCircle2 className="w-4 h-4" />
                    Quick Complete
                  </button>
                  
                  <button 
                    onClick={() => handleStatusUpdate('failed')}
                    className="flex items-center justify-center gap-2 bg-white border border-red-200 text-red-600 py-4 rounded-xl font-bold hover:bg-red-50 transition-all sm:col-span-2 uppercase tracking-wide text-sm hover:border-red-300"
                  >
                    <XCircle className="w-4 h-4" />
                    Abort & Quarantine
                  </button>
                </div>
               )}
            </div>
          </div>
        </div>

        {/* Info & Logs Column */}
        <div className="space-y-6">
           <div className="bg-white p-8 rounded-[2rem] border border-chocolate-100 shadow-sm">
             <h4 className="text-xs font-black text-chocolate-950 mb-6 uppercase tracking-[0.2em] border-b border-chocolate-50 pb-4">Specifications</h4>
             <dl className="space-y-5">
               <div>
                  <dt className="text-[10px] uppercase tracking-wider font-bold text-chocolate-400">Standard Operator</dt>
                  <dd className="text-sm font-bold text-chocolate-900 mt-1">Automatic Allocation</dd>
               </div>
               <div>
                  <dt className="text-[10px] uppercase tracking-wider font-bold text-chocolate-400">Assigned Production Line</dt>
                  <dd className="text-sm font-bold text-chocolate-900 mt-1">Central Processor #1</dd>
               </div>
               <div>
                  <dt className="text-[10px] uppercase tracking-wider font-bold text-chocolate-400">Batch Notes</dt>
                  <dd className="text-sm italic text-chocolate-700 mt-1 bg-chocolate-50 p-3 rounded-xl">"{batch.notes ?? 'No notes available'}"</dd>
               </div>
             </dl>
           </div>
           
           <div className="bg-white p-8 rounded-[2rem] border border-chocolate-100 shadow-sm">
             <h4 className="text-xs font-black text-chocolate-950 mb-6 uppercase tracking-[0.2em]">Quality Assurance</h4>
             <div className="p-6 bg-chocolate-50/50 rounded-2xl border border-dashed border-chocolate-200 text-center">
                <ShieldCheck className="w-8 h-8 text-gold-500 mx-auto mb-3" />
                <p className="text-xs text-chocolate-600 font-medium leading-relaxed mb-4">
                  QC inspections trigger automatically. Protocol V4.2 requires double-sampling.
                </p>
                <button className="text-chocolate-900 text-[10px] font-black uppercase tracking-widest flex items-center justify-center gap-2 hover:text-gold-600 transition-colors mx-auto group">
                   Run Prevention Check <ChevronRight className="w-3 h-3 group-hover:translate-x-1 transition-transform" />
                </button>
             </div>
           </div>
        </div>
      </div>
    </div>
  );
};

export default BatchDetailPage;

import React, { useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { 
  Clock, Users, ChefHat, ArrowLeft, Play, 
  CheckCircle2, AlertTriangle, Scale, Info 
} from 'lucide-react';
import { useProduction } from '../../hooks/useProduction';
import { useInventory } from '../../hooks/useInventory';
import { Button } from '../../components/ui/Button';
import { Badge } from '../../components/ui/Badge';
import { Card, CardContent, CardHeader, CardTitle } from '../../components/ui/Card';
import StartBatchModal from '../../components/production/StartBatchModal';
import { RecipeIngredient } from '../../types';

const RecipeDetailPage: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { useRecipe } = useProduction();
  const { useInventoryItems } = useInventory(); // To check stock levels if needed
  
  const { data: recipe, isLoading, error } = useRecipe(id!);
  const [isStartBatchModalOpen, setIsStartBatchModalOpen] = useState(false);

  if (isLoading) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary"></div>
      </div>
    );
  }

  if (error || !recipe) {
    return (
      <div className="text-center py-12">
        <h3 className="text-lg font-medium text-gray-900">Recipe not found</h3>
        <Button variant="ghost" onClick={() => navigate('/production/recipes')} className="mt-4">
          <ArrowLeft className="w-4 h-4 mr-2" />
          Back to Recipes
        </Button>
      </div>
    );
  }

  return (
    <div className="space-y-6 pb-20">
      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 bg-white p-6 rounded-[2rem] border border-chocolate-100 shadow-sm relative overflow-hidden">
        <div className="absolute top-0 right-0 w-64 h-64 bg-gold-500/5 rounded-full blur-3xl -translate-y-1/2 translate-x-1/2" />
        <div className="flex items-center gap-4 relative z-10">
          <Button variant="ghost" size="icon" onClick={() => navigate('/production/recipes')} className="text-chocolate-500 hover:text-chocolate-800 hover:bg-chocolate-50 rounded-xl">
            <ArrowLeft className="w-6 h-6" />
          </Button>
          <div>
            <h1 className="text-4xl font-black text-chocolate-900 tracking-tight uppercase">{recipe.name}</h1>
            <div className="flex items-center gap-4 mt-2 text-chocolate-600/80 font-medium">
              <span className="flex items-center gap-1.5 bg-chocolate-50 px-3 py-1 rounded-full text-xs font-bold uppercase tracking-wide">
                <Clock className="w-3 h-3 text-gold-600" /> {recipe.duration} mins
              </span>
              <span className="flex items-center gap-1.5 bg-chocolate-50 px-3 py-1 rounded-full text-xs font-bold uppercase tracking-wide">
                <Users className="w-3 h-3 text-gold-600" /> {recipe.yield} units
              </span>
              <Badge variant={recipe.difficulty === 'Easy' ? 'success' : recipe.difficulty === 'Medium' ? 'warning' : 'error'} className="shadow-sm">
                {recipe.difficulty}
              </Badge>
            </div>
          </div>
        </div>
        <Button 
          onClick={() => setIsStartBatchModalOpen(true)} 
          className="relative z-10 bg-gradient-to-r from-gold-500 to-gold-600 hover:from-gold-600 hover:to-gold-700 text-white shadow-lg shadow-gold-500/20 px-8 py-6 rounded-xl font-black uppercase tracking-widest transition-all active:scale-95"
        >
          <Play className="w-5 h-5 mr-2 fill-current" />
          Start Production Batch
        </Button>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Left Column: Details & Instructions */}
        <div className="lg:col-span-2 space-y-6">
          <Card className="border-chocolate-100 overflow-hidden shadow-sm">
            <CardHeader className="bg-chocolate-50/50 border-b border-chocolate-100/50 pb-4">
              <CardTitle className="flex items-center gap-2 text-lg font-black text-chocolate-900 uppercase tracking-wide">
                <Info className="w-5 h-5 text-gold-500" />
                Recipe Profile
              </CardTitle>
            </CardHeader>
            <CardContent className="p-6">
              <p className="text-chocolate-600 leading-relaxed font-medium">{recipe.description}</p>
            </CardContent>
          </Card>

          <Card className="border-chocolate-100 overflow-hidden shadow-sm">
            <CardHeader className="bg-chocolate-50/50 border-b border-chocolate-100/50 pb-4">
              <CardTitle className="flex items-center gap-2 text-lg font-black text-chocolate-900 uppercase tracking-wide">
                <ChefHat className="w-5 h-5 text-gold-500" />
                Production Workflow
              </CardTitle>
            </CardHeader>
            <CardContent className="p-6">
              <div className="space-y-6">
                {recipe.instructions.map((step, index) => (
                  <div key={index} className="flex gap-4 group">
                    <div className="flex-shrink-0 w-8 h-8 rounded-xl bg-chocolate-100 text-chocolate-800 flex items-center justify-center font-black text-sm shadow-sm group-hover:bg-gold-500 group-hover:text-white transition-colors duration-300">
                      {index + 1}
                    </div>
                    <p className="text-chocolate-700 mt-1 font-medium leading-relaxed">{step}</p>
                  </div>
                ))}
              </div>
            </CardContent>
          </Card>
        </div>

        {/* Right Column: Ingredients */}
        <div className="space-y-6">
          <Card className="h-full border-chocolate-100 overflow-hidden shadow-sm">
            <CardHeader className="bg-chocolate-50/50 border-b border-chocolate-100/50 pb-4">
              <CardTitle className="flex items-center gap-2 text-lg font-black text-chocolate-900 uppercase tracking-wide">
                <Scale className="w-5 h-5 text-gold-500" />
                Bill of Materials
              </CardTitle>
            </CardHeader>
            <CardContent className="p-6">
              <div className="space-y-3">
                {recipe.ingredients.map((ingredient: RecipeIngredient) => (
                  <div key={ingredient.id} className="flex items-center justify-between p-4 bg-white rounded-xl border border-chocolate-100 shadow-sm hover:border-gold-300 transition-colors">
                    <div>
                      <p className="font-bold text-chocolate-900">{ingredient.name}</p>
                      <p className="text-[10px] font-black text-chocolate-400 uppercase tracking-wider">{ingredient.code ?? 'NO CODE'}</p>
                    </div>
                    <div className="text-right">
                      <p className="font-black text-xl text-chocolate-800">
                        {ingredient.quantity} <span className="text-[10px] uppercase text-chocolate-400 font-bold">{ingredient.unit}</span>
                      </p>
                    </div>
                  </div>
                ))}
              </div>
              
              <div className="mt-8 p-6 bg-gradient-to-br from-gold-50 to-white rounded-2xl border border-gold-200/50 shadow-inner">
                <h4 className="text-xs font-black text-gold-700 mb-2 uppercase tracking-widest flex items-center gap-2">
                  <AlertTriangle className="w-3 h-3" /> Master Chocolatier Tip
                </h4>
                <p className="text-xs text-chocolate-600/80 font-medium italic leading-relaxed">
                  "Maintain ingredient acclimation at 22°C ambient temperature for optimal crystallization phases."
                </p>
              </div>
            </CardContent>
          </Card>
        </div>
      </div>

      {/* Start Batch Modal */}
      {recipe && (
        <StartBatchModal
          isOpen={isStartBatchModalOpen}
          onClose={() => setIsStartBatchModalOpen(false)}
          recipe={recipe}
        />
      )}
    </div>
  );
};

