    category: categoryFilter
  });

  const recipes = recipesData?.recipes ?? [];

  return (
    <div className="space-y-8 pb-20">
      {/* Header */}
      <PageHeader 
        title="Recipe Collections" 
        subtitle="Manage standard operating procedures, formulations, and production variants."
