        <div className="text-center py-20 bg-chocolate-50/30 rounded-[2.5rem] border border-dashed border-chocolate-200">
          <div className="w-16 h-16 bg-white rounded-full flex items-center justify-center mx-auto mb-4 border border-chocolate-100 shadow-sm">
            <ChefHat className="w-8 h-8 text-chocolate-300" />
          </div>
          <h3 className="text-lg font-bold text-chocolate-900">No recipes found</h3>
          <p className="text-chocolate-500 mt-1 font-medium">Try adjusting your search or filters, or create a new formulation.</p>
        </div>
      )}
    </div>
  );
};

export default RecipesPage;

import { useEffect, useState } from 'react';
import { qcService } from '../../services/qcService';
import { Batch } from '../../types';
import { Card, CardHeader, CardTitle, CardContent, CardFooter } from '../../components/ui/Card';
import { Button } from '../../components/ui/Button';
import { Input } from '../../components/ui/Input';
import { ClipboardCheck, Check, X } from 'lucide-react';

const QCPage = () => {
    const [batches, setBatches] = useState<Batch[]>([]);
    const [loading, setLoading] = useState(true);
    const [notes, setNotes] = useState<Record<string, string>>({});

    useEffect(() => {
        const fetchBatches = async () => {
            try {
                const data = await qcService.getPendingBatches();
                setBatches(data);
            } catch (error) {
                console.error('Failed to load pending batches:', error);
            } finally {
                setLoading(false);
            }
        };
        void fetchBatches();
    }, []);

    const handleAction = async (id: string, status: 'APPROVED' | 'REJECTED') => {
        try {
            await qcService.updateQualityStatus(id, {
                batch_id: id,
                status,
                notes: notes[id] ?? ''
            });
            // Optimistic update
            setBatches(prev => prev.filter(b => b.id !== id));
        } catch (error) {
            console.error('Failed to update status:', error);
        }
    };

    return (
        <div className="space-y-6">
            <h1 className="text-3xl font-bold tracking-tight">Quality Control</h1>
            <p className="text-muted-foreground">Verify production batches before release.</p>

            {loading ? (
                <div className="text-center py-10 text-muted-foreground">Loading...</div>
            ) : (
                <div className="grid gap-6 md:grid-cols-2 lg:grid-cols-3">
                    {batches.length === 0 ? (
                        <div className="col-span-full text-center py-10 text-muted-foreground">
                            No batches pending Quality Control.
                        </div>
                    ) : batches.map(batch => (
                        <Card key={batch.id} className="border-yellow-200 bg-yellow-50/20">
                             <CardHeader className="pb-2">
                                 <div className="flex items-center gap-2 text-yellow-800">
                                     <ClipboardCheck className="h-5 w-5" />
                                     <CardTitle className="text-lg">Batch #{batch.batch_number ?? batch.id}</CardTitle>
                                 </div>
                            </CardHeader>
                            <CardContent className="space-y-4">
                                <div>
                                    <div className="text-2xl font-bold">{batch.recipe_name ?? 'Unknown Recipe'}</div>
                                    <div className="text-sm text-slate-600">{batch.quantity_produced} Units</div>
                                </div>
                                
                                <div className="space-y-2">
                                    <label className="text-sm font-medium">QC Notes</label>
                                    <Input 
                                        placeholder="Enter findings..." 
                                        value={notes[batch.id] ?? ''}
                                        onChange={(e) => setNotes({...notes, [batch.id]: e.target.value})}
                                    />
                                </div>
                            </CardContent>
                            <CardFooter className="gap-2">
                                <Button 
                                    className="w-full bg-red-100 text-red-700 hover:bg-red-200" 
                                    variant="ghost"
                                    onClick={() => void handleAction(batch.id, 'REJECTED')}
                                >
                                    <X className="h-4 w-4 mr-2" /> Reject
                                </Button>
                                <Button 
                                    className="w-full bg-green-600 hover:bg-green-700"
                                    onClick={() => void handleAction(batch.id, 'APPROVED')}
                                >
                                    <Check className="h-4 w-4 mr-2" /> Approve
                                </Button>
                            </CardFooter>
                        </Card>
                    ))}
                </div>
            )}
        </div>
    );
};

export default QCPage;

import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Card, CardHeader, CardContent, CardTitle } from '../../components/ui/Card';
import { Button } from '../../components/ui/Button';
import { Input } from '../../components/ui/Input';
import { Select } from '../../components/ui/Select';
import { Textarea } from '../../components/ui/Textarea';
import { Badge } from '../../components/ui/Badge';
import { 
  Bot, 
  Sparkles, 
  Save,
  Loader2,
  Plus,
  Trash2,
  ChefHat
} from 'lucide-react';
import { toast } from 'sonner';
import { useProduction } from '../../hooks/useProduction';
import { useInventory } from '../../hooks/useInventory';

// Types for form state
interface RecipeFormState {
  name: string;
  description: string;
  yield_quantity: number;
  yield_unit: string;
  duration_minutes: number;
  difficulty_level: 'easy' | 'medium' | 'hard';
  category: string;
  instructions: string;
}

interface IngredientEntry {
  tempId: string; // for key
  ingredient_id: string; // from inventory
  name: string; // display name
  amount: string; // string mainly for input, parsed to number
  unit: string;
  notes: string;
}

const CreateRecipe = () => {
    const navigate = useNavigate();
    const { useCreateRecipe } = useProduction();
    const createRecipe = useCreateRecipe();
    
    // Inventory Data for dropdown
    const { useInventoryItems } = useInventory();
    const { data: inventoryData } = useInventoryItems({ limit: 100 }); // Increase limit to show more items
    const inventoryItems = inventoryData?.items ?? [];

    // AI State
    const [prompt, setPrompt] = useState('');
    const [isGenerating, setIsGenerating] = useState(false);

    // Form State
    const [formData, setFormData] = useState<RecipeFormState>({
      name: '',
      description: '',
      yield_quantity: 100,
      yield_unit: 'kg',
      duration_minutes: 60,
      difficulty_level: 'medium',
      category: 'bars',
      instructions: ''
    });

    const [ingredients, setIngredients] = useState<IngredientEntry[]>([]);

    // New Ingredient State
    const [newIngredient, setNewIngredient] = useState<IngredientEntry>({
      tempId: '',
      ingredient_id: '',
      name: '',
      amount: '',
      unit: 'kg',
      notes: ''
    });

    // --- AI Handler ---
    const handleGenerate = async () => {
        if (!prompt) return;
        setIsGenerating(true);
        try {
            // Simulate AI Generation
            await new Promise(resolve => setTimeout(resolve, 2500));
            
            const generatedName = 'AI Generated: ' + prompt.split(' ').slice(0, 3).join(' ') + '...';
            const generatedDesc = `Optimized formulation for ${prompt}. Focused on cost-efficiency and texture stability.`;
            
            // Update Form
            setFormData(prev => ({
              ...prev,
              name: generatedName,
              description: generatedDesc,
              instructions: `1. Melt cocoa mass at 50°C.\n2. Mix in sugar and emulsifiers.\n3. Refine to 20 microns.\n4. Conche for 12 hours.\n5. Temper and mold.`
            }));

            // Mock Ingredients - In a real app, AI would return structured data we'd map to inventory
            const mockIngredients: IngredientEntry[] = [
                { tempId: crypto.randomUUID(), ingredient_id: '', name: 'Cocoa Mass', amount: '50', unit: 'kg', notes: 'Fino de Aroma' },
                { tempId: crypto.randomUUID(), ingredient_id: '', name: 'Sugar', amount: '35', unit: 'kg', notes: 'Fine white' },
                { tempId: crypto.randomUUID(), ingredient_id: '', name: 'Cocoa Butter', amount: '15', unit: 'kg', notes: 'Deodorized' }
            ];
            setIngredients(mockIngredients);

            toast.success("Recipe generated by AI! Review and edit details below.");
        } catch {
            toast.error("Generation failed");
        } finally {
            setIsGenerating(false);
        }
    };

    // --- Ingredient Handlers ---
    const handleAddIngredient = () => {
      // Basic validation
      if (!newIngredient.name && !newIngredient.ingredient_id) {
        toast.error("Please select an ingredient or enter a name");
        return;
      }
      if (!newIngredient.amount || isNaN(parseFloat(newIngredient.amount))) {
        toast.error("Please enter a valid amount");
        return;
      }

      setIngredients([...ingredients, { ...newIngredient, tempId: crypto.randomUUID() }]);
      
      // Reset form
      setNewIngredient({
        tempId: '',
        ingredient_id: '',
        name: '', 
        amount: '',
        unit: 'kg',
        notes: ''
      });
      toast.success("Ingredient added");
    };

    const handleRemoveIngredient = (tempId: string) => {
      setIngredients(ingredients.filter(i => i.tempId !== tempId));
    };

    const handleInventorySelect = (itemId: string) => {
      const item = inventoryItems.find(i => i.id === itemId);
      if (item) {
        setNewIngredient(prev => ({
          ...prev,
          ingredient_id: item.id,
          name: item.name,
          unit: item.unit 
        }));
      } else {
         setNewIngredient(prev => ({ ...prev, ingredient_id: itemId, name: '' }));
      }
    };

    // --- Save Handler ---
    const handleSave = () => {
        if (!formData.name) {
          toast.error("Recipe name is required");
          return;
        }

        const recipePayload = {
          name: formData.name,
          description: formData.description,
          category: formData.category,
          yield_quantity: formData.yield_quantity,
          yield_unit: formData.yield_unit,
          duration_minutes: formData.duration_minutes,
          difficulty_level: formData.difficulty_level,
          instructions: formData.instructions,
          is_active: true,
          ingredients: ingredients.map(ing => ({
            inventory_item_id: ing.ingredient_id ?? null,
            custom_name: ing.ingredient_id ? null : ing.name,
            quantity: parseFloat(ing.amount),
            unit: ing.unit,
            notes: ing.notes
          }))
        };

        createRecipe.mutate(recipePayload as any, {
            onSuccess: () => {
                toast.success("Recipe saved successfully!");
                navigate('/production/recipes');
            },
            onError: (err) => {
                console.error(err);
                toast.error("Failed to save recipe");
            }
        });
    };

    return (
        <div className="max-w-5xl mx-auto space-y-8 pb-12 animate-fade-in px-4">
            {/* Header / AI Prompt */}
            <div className="text-center space-y-4 pt-8">
                <div className="bg-gold-100 p-4 rounded-full w-fit mx-auto animate-bounce-slow">
                    <Sparkles className="h-8 w-8 text-gold-600" />
                </div>
                <h1 className="text-4xl font-bold font-serif text-cocoa-900">Formulation Architect</h1>
                <p className="text-xl text-slate-600 max-w-2xl mx-auto italic font-serif">
                   "Mastering the alchemy of chocolate, one ingredient at a time."
                </p>
            </div>

            <Card className="border-gold-200 shadow-xl border-2 bg-gradient-to-br from-white to-gold-50/30 overflow-hidden">
                <div className="h-2 bg-gold-400 w-full" />
                <CardContent className="pt-8">
                    <div className="flex flex-col md:flex-row gap-4">
                        <Input 
                            placeholder="Describe a new chocolate creation (e.g. '70% Dark with Sea Salt')..." 
                            className="flex-1 h-14 text-lg border-gold-200 focus:ring-gold-500 bg-white"
                            value={prompt}
                            onChange={(e) => setPrompt(e.target.value)}
                            onKeyDown={(e) => e.key === 'Enter' && void handleGenerate()}
                        />
                        <Button 
                            className="h-14 px-8 bg-gold-600 hover:bg-gold-700 text-white text-lg font-bold shadow-lg transition-all transform hover:scale-105 active:scale-95 flex items-center gap-2"
                            onClick={() => void handleGenerate()}
                            disabled={isGenerating || !prompt}
                        >
                            {isGenerating ? <Loader2 className="h-6 w-6 animate-spin" /> : <Bot className="h-6 w-6" />}
                            {isGenerating ? "Generating..." : "AI Generate"}
                        </Button>
                    </div>
                </CardContent>
            </Card>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                {/* Left Column: Recipe Details */}
                <div className="lg:col-span-2 space-y-8">
                    <Card className="border-cocoa-100 shadow-md">
                        <CardHeader className="bg-cocoa-50/30 border-b border-cocoa-100">
                            <CardTitle className="text-xl text-cocoa-900 flex items-center gap-2">
                                <ChefHat className="w-6 h-6 text-gold-600" />
                                Recipe Blueprint
                            </CardTitle>
                        </CardHeader>
                        <CardContent className="p-6 space-y-6">
                            <Input 
                                label="Recipe Title"
                                value={formData.name}
                                onChange={(e) => setFormData({...formData, name: e.target.value})}
                                placeholder="e.g., Mountain Peak Dark Truffle"
                                required
                            />
                            
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                <Select 
                                    label="Category"
                                    value={formData.category}
                                    onChange={(e) => setFormData({...formData, category: e.target.value})}
                                    options={[
                                        { label: "Bars", value: "bars" },
                                        { label: "Truffles", value: "truffles" },
                                        { label: "Bonbons", value: "bonbons" },
                                        { label: "Gift Boxes", value: "gift_boxes" },
                                        { label: "Pralines", value: "pralines" }
                                    ]}
                                />
                                <Select 
                                    label="Difficulty Level"
                                    value={formData.difficulty_level}
                                    onChange={(e) => setFormData({...formData, difficulty_level: e.target.value as any})}
                                    options={[
                                        { label: "Easy - Apprentice", value: "easy" },
                                        { label: "Medium - Artisan", value: "medium" },
                                        { label: "Hard - Master", value: "hard" }
                                    ]}
                                />
                            </div>

                            <div className="grid grid-cols-3 gap-4">
                                <Input 
                                    label="Yield Qty"
                                    type="number"
                                    value={formData.yield_quantity}
                                    onChange={(e) => setFormData({...formData, yield_quantity: parseFloat(e.target.value)})}
                                />
                                <Select 
                                    label="Yield Unit"
                                    value={formData.yield_unit}
                                    onChange={(e) => setFormData({...formData, yield_unit: e.target.value})}
                                    options={[
                                        { label: "kg", value: "kg" },
                                        { label: "g", value: "g" },
                                        { label: "pcs", value: "pcs" },
                                        { label: "units", value: "units" }
                                    ]}
                                />
                                <Input 
                                    label="Time (min)"
                                    type="number"
                                    value={formData.duration_minutes}
                                    onChange={(e) => setFormData({...formData, duration_minutes: parseFloat(e.target.value)})}
                                />
                            </div>

                            <Textarea 
                                label="Description"
                                value={formData.description}
                                onChange={(e) => setFormData({...formData, description: e.target.value})}
                                placeholder="The sensory profile and intended audience for this masterpiece..."
                            />

                            <Textarea 
                                label="Preparation Instructions"
                                className="min-h-[200px] font-mono text-sm leading-relaxed"
                                value={formData.instructions}
                                onChange={(e) => setFormData({...formData, instructions: e.target.value})}
                                placeholder="1. Temper the chocolate to 31°C...\n2. Prepare the ganache center..."
                            />
                        </CardContent>
                    </Card>
                </div>

                {/* Right Column: Ingredients */}
                <div className="space-y-6">
                    <Card className="border-cocoa-100 shadow-md">
                        <CardHeader className="bg-cocoa-50/30 border-b border-cocoa-100">
                             <CardTitle className="text-lg text-cocoa-900 flex items-center justify-between">
                                <span>Ingredient Vault</span>
                                <Badge className="bg-gold-600">{ingredients.length}</Badge>
                            </CardTitle>
                        </CardHeader>
                        <CardContent className="p-4 space-y-6">
                            {/* Ingredients List */}
                            <div className="space-y-3 max-h-[400px] overflow-y-auto pr-2 custom-scrollbar">
                                {ingredients.length === 0 ? (
                                    <div className="text-center py-12 text-slate-400 text-sm italic bg-slate-50/50 rounded-lg border border-dashed border-slate-200">
                                        No materials selected yet.
                                    </div>
                                ) : (
                                    ingredients.map((ing) => (
                                        <div key={ing.tempId} className="flex justify-between items-center p-3 bg-white rounded-lg border border-slate-200 shadow-sm group hover:border-gold-300 transition-all">
                                            <div>
                                                <div className="font-bold text-cocoa-900">{ing.name}</div>
                                                <div className="text-xs text-cocoa-600 flex items-center gap-2">
                                                    <span className="font-mono bg-gold-50 text-gold-700 px-1.5 py-0.5 rounded">{ing.amount}{ing.unit}</span>
                                                    {ing.notes && <span className="truncate max-w-[120px]">• {ing.notes}</span>}
                                                </div>
                                            </div>
                                            <Button 
                                                variant="ghost" 
                                                size="sm" 
                                                onClick={() => handleRemoveIngredient(ing.tempId)}
                                                className="h-8 w-8 p-0 text-slate-300 hover:text-red-500"
                                            >
                                                <Trash2 className="w-4 h-4" />
                                            </Button>
                                        </div>
                                    ))
                                )}
                            </div>

                            {/* Add Ingredient Card (Requested User Feature) */}
                            <div className="p-4 rounded-xl border-2 border-dashed border-gold-300 bg-gold-50/20 space-y-4 shadow-inner relative">
                                <div className="absolute -top-3 left-4 bg-white px-2 py-0.5 border border-gold-300 rounded text-[10px] font-bold text-gold-600 uppercase">
                                    Ingredient Card
                                </div>
                                
                                <Select 
                                    label="Selection"
                                    value={newIngredient.ingredient_id}
                                    onChange={(e) => handleInventorySelect(e.target.value)}
                                    options={[
                                        { label: "Choose from Inventory...", value: "" },
                                        ...inventoryItems.map(item => ({ 
                                            label: `${item.name} (${item.quantity} ${item.unit} available)`, 
                                            value: item.id 
                                        }))
                                    ]}
                                />

                                {!newIngredient.ingredient_id && (
                                    <Input 
                                        label="Custom Name"
                                        placeholder="Enter name for manual entry..."
                                        value={newIngredient.name}
                                        onChange={(e) => setNewIngredient({...newIngredient, name: e.target.value, ingredient_id: ''})}
                                    />
                                )}

                                <div className="grid grid-cols-2 gap-3">
                                    <Input 
                                        label="Amount" 
                                        type="number" 
                                        placeholder="0.00"
                                        value={newIngredient.amount}
                                        onChange={(e) => setNewIngredient({...newIngredient, amount: e.target.value})}
                                    />
                                    <Select 
                                        label="Unit"
                                        value={newIngredient.unit}
                                        onChange={(e) => setNewIngredient({...newIngredient, unit: e.target.value})}
                                        options={[
                                            { label: "kg", value: "kg" },
                                            { label: "g", value: "g" },
                                            { label: "L", value: "L" },
                                            { label: "pcs", value: "pcs" },
                                            { label: "units", value: "units" }
                                        ]}
                                    />
                                </div>

                                <Input 
                                    label="Notes / Description"
                                    placeholder="e.g. melted, room temp..."
                                    value={newIngredient.notes}
                                    onChange={(e) => setNewIngredient({...newIngredient, notes: e.target.value})}
                                />

                                <Button 
                                    onClick={handleAddIngredient} 
                                    className="w-full bg-cocoa-900 hover:bg-black text-gold-100 h-10 font-bold shadow-md hover:shadow-lg transition-all"
                                    disabled={!newIngredient.name && !newIngredient.ingredient_id}
                                >
                                    <Plus className="w-4 h-4 mr-2" />
                                    Add Ingredient
                                </Button>
                            </div>
                        </CardContent>
                    </Card>

                    <Button 
                        onClick={handleSave} 
                        className="w-full h-14 bg-green-600 hover:bg-green-700 text-white text-xl font-bold shadow-xl flex items-center justify-center gap-3 transition-all hover:scale-[1.02] active:scale-95"
                        disabled={createRecipe.isPending}
                    >
                        {createRecipe.isPending ? <Loader2 className="w-6 h-6 animate-spin" /> : <Save className="w-6 h-6" />}
                        Archive Recipe
                    </Button>
                </div>
            </div>
        </div>
    );
};

export default CreateRecipe;

import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Button } from '../../components/ui/Button';
import {
    Search,
    ChefHat,
    Scale,
    Clock,
    Plus,
    Utensils,
    Star
} from 'lucide-react';
import { useQuery } from '@tanstack/react-query';
import { Recipe } from '../../types';
import { fetchRecipes } from '../../services/recipeService';
import RecipeModal from '../../components/recipes/RecipeModal';

const RecipeList = () => {
    const navigate = useNavigate();
    const [searchTerm, setSearchTerm] = useState('');
    const [selectedRecipe, setSelectedRecipe] = useState<Recipe | null>(null);

    const { data: recipes = [], isLoading } = useQuery<Recipe[]>({
        queryKey: ['recipes'],
        queryFn: fetchRecipes,
    });

    const filteredRecipes = recipes.filter(recipe =>
        recipe.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
        recipe.code?.toLowerCase().includes(searchTerm.toLowerCase())
    );

    // Helper to render difficulty stars
    const renderDifficulty = (level: string) => {
        const count = level === 'hard' ? 3 : level === 'medium' ? 2 : 1;
        return (
            <div className="flex gap-0.5" title={`Difficulty: ${level}`}>
                {[...Array(3)].map((_, i) => (
                    <Star 
                        key={i} 
                        className={`w-3 h-3 ${i < count ? 'fill-gold-500 text-gold-500' : 'text-chocolate-200'}`} 
                    />
                ))}
            </div>
        );
    };

    return (
        <div className="space-y-6 pb-12 animate-fade-in relative">
             {/* Decorative Background Elements */}
             <div className="fixed top-20 right-0 w-96 h-96 bg-gold-400/5 rounded-full blur-3xl pointer-events-none -z-10" />

            {/* Header Section */}
            <div className="flex flex-col md:flex-row justify-between items-start md:items-end gap-4">
                <div>
                   <div className="items-center gap-2 mb-2 hidden md:flex">
                        <span className="h-px w-8 bg-gold-500/50"></span>
                        <span className="text-[10px] font-black tracking-[0.3em] text-gold-600 uppercase">Production Standards</span>
                   </div>
                    <h1 className="text-3xl md:text-4xl font-black text-chocolate-950 tracking-tight leading-tight">
                        The Chocolatier's <span className="text-chocolate-600/20 block md:inline">Ledger</span>
                    </h1>
                    <p className="text-chocolate-900/40 font-medium mt-3 max-w-xl">
                        Master collection of couverture formulas, ganache fillings, and production methodologies.
                    </p>
                </div>
                
                <Button 
                    className="h-12 px-6 bg-chocolate-900 text-white hover:bg-chocolate-800 shadow-lg shadow-chocolate-900/20 rounded-xl font-bold tracking-wide transition-all hover:scale-105 active:scale-95"
                    onClick={() => navigate('/recipes/new')}
                >
                    <Plus className="h-5 w-5 mr-2" />
                    New Formula
                </Button>
            </div>

            {/* Search Bar */}
            <div className="relative max-w-2xl">
                <div className="absolute inset-0 bg-white/40 backdrop-blur-md rounded-2xl shadow-sm border border-white/20"></div>
                <div className="relative flex items-center px-4 h-14">
                    <Search className="h-5 w-5 text-chocolate-400 mr-3" />
                    <input 
                        type="text"
                        placeholder="Search formulas by name, code, or ingredients..."
                        className="w-full bg-transparent border-none outline-none text-chocolate-900 placeholder:text-chocolate-900/30 font-medium"
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                    />
                </div>
            </div>

            {/* Recipe Grid */}
            {isLoading ? (
                <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
                     {[1,2,3].map(i => (
                         <div key={i} className="h-80 rounded-2xl bg-chocolate-100 animate-pulse border border-chocolate-200" />
                     ))}
                </div>
            ) : filteredRecipes.length === 0 ? (
                <div className="text-center py-20 bg-white/30 rounded-3xl border border-white/40 backdrop-blur-sm">
                    <div className="h-20 w-20 bg-chocolate-100 rounded-full flex items-center justify-center mx-auto mb-6 text-chocolate-400">
                        <Utensils className="h-10 w-10" />
                    </div>
                    <h3 className="text-xl font-bold text-chocolate-900 mb-2">No Formulas Found</h3>
                    <p className="text-chocolate-600/60 mb-8 max-w-md mx-auto">
                        Your ledger is currently empty. Start by creating a new formula to standardize your production.
                    </p>
                    <Button 
                        variant="outline" 
                        className="border-chocolate-200 text-chocolate-700 hover:bg-chocolate-50"
                        onClick={() => navigate('/recipes/new')}
                    >
                        Create First Formula
                    </Button>
                </div>
            ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
                    {filteredRecipes.map((recipe) => (
                        <div
                            key={recipe.id}
                            className="group relative bg-white rounded-2xl shadow-md hover:shadow-xl hover:shadow-chocolate-900/10 transition-all duration-300 cursor-pointer border border-chocolate-200 hover:-translate-y-1"
                            onClick={() => setSelectedRecipe(recipe)}
                        >
                            {/* Card Header / Image Area */}
                            <div className="h-40 bg-gradient-to-br from-chocolate-50 to-chocolate-100 relative overflow-hidden rounded-t-2xl">
                                {recipe.image_url ? (
                                    <img
                                        src={recipe.image_url}
                                        alt={recipe.name}
                                        className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500"
                                    />
                                ) : (
                                    <div className="absolute inset-0 flex items-center justify-center">
                                         <ChefHat className="h-14 w-14 text-chocolate-300" />
                                    </div>
                                )}

                                {/* Status Badge */}
                                <div className="absolute top-3 right-3">
                                    <span className={`px-2.5 py-1 rounded-full text-[10px] font-bold uppercase tracking-wide ${
                                        recipe.is_active
                                        ? 'bg-vibrant-green/10 text-vibrant-green border border-vibrant-green/30'
                                        : 'bg-chocolate-900/80 text-white'
                                    }`}>
                                        {recipe.is_active ? 'Active' : 'Draft'}
                                    </span>
                                </div>

                                {/* Recipe Code Badge */}
                                <div className="absolute top-3 left-3">
                                    <span className="px-2.5 py-1 rounded-full text-[10px] font-bold text-gold-700 bg-gold-100/90 backdrop-blur-sm uppercase tracking-wide">
                                        {recipe.code ?? 'REC-___'}
                                    </span>
                                </div>
                            </div>

                            {/* Card Content */}
                            <div className="p-5">
                                <div className="flex justify-between items-start gap-2 mb-3">
                                    <h3 className="text-lg font-bold text-chocolate-950 group-hover:text-gold-600 transition-colors leading-tight">
                                        {recipe.name}
                                    </h3>
                                    {renderDifficulty(recipe.difficulty_level)}
                                </div>

                                <p className="text-sm text-chocolate-600 mb-4 leading-relaxed">
                                    {recipe.description ?? 'No description provided.'}
                                </p>

                                {/* Stats Grid */}
                                <div className="grid grid-cols-2 gap-3 pt-4 border-t border-chocolate-100">
                                    <div className="flex items-center gap-2 text-xs">
                                        <div className="w-8 h-8 rounded-lg bg-chocolate-50 flex items-center justify-center">
                                            <Scale className="w-4 h-4 text-chocolate-500" />
                                        </div>
                                        <div>
                                            <p className="font-bold text-chocolate-900">{recipe.yield_quantity} {recipe.yield_unit}</p>
                                            <p className="text-chocolate-400 text-[10px] uppercase">Yield</p>
                                        </div>
                                    </div>
                                    <div className="flex items-center gap-2 text-xs">
                                        <div className="w-8 h-8 rounded-lg bg-chocolate-50 flex items-center justify-center">
                                            <Clock className="w-4 h-4 text-chocolate-500" />
                                        </div>
                                        <div>
                                            <p className="font-bold text-chocolate-900">{recipe.duration_minutes} min</p>
                                            <p className="text-chocolate-400 text-[10px] uppercase">Duration</p>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            )}

            <RecipeModal 
                recipe={selectedRecipe} 
                isOpen={!!selectedRecipe} 
                onClose={() => setSelectedRecipe(null)} 
            />
        </div>
    );
};

export default RecipeList;

import React, { useEffect, useState } from 'react';
import { loadStripe } from '@stripe/stripe-js';
import { Elements } from '@stripe/react-stripe-js';
import { salesService } from '../../services/salesService';
import { OnlineOrder, EmployeeSale, Product } from '../../types';
import { Card, CardHeader, CardTitle, CardContent } from '../../components/ui/Card';
import { Button } from '../../components/ui/Button';
import { Badge } from '../../components/ui/Badge';
import StripePaymentForm from '../../components/sales/StripePaymentForm';
import {
  ShoppingBag,
  TrendingUp,
  CreditCard,
  DollarSign,
  ChevronRight,
  Filter,
  Package,
  Plus,
  Minus,
  X,
  ShoppingCart,
