} from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';

// Load Stripe - Only if publishable key is configured
const stripeKey = import.meta.env.VITE_STRIPE_PUBLISHABLE_KEY as string;
const isStripeConfigured = stripeKey && stripeKey.startsWith('pk_');
const stripePromise = isStripeConfigured ? loadStripe(stripeKey) : null;



interface CartItem {
  product: Product;
  quantity: number;
}

const containerVariants = {
  hidden: { opacity: 0 },
  visible: {
    opacity: 1,
    transition: { staggerChildren: 0.1 }
  }
};

const itemVariants = {
  hidden: { y: 20, opacity: 0 },
  visible: { y: 0, opacity: 1 }
};

const SalesPage: React.FC = () => {
    const [sales, setSales] = useState<EmployeeSale[]>([]);
    const [orders, setOrders] = useState<OnlineOrder[]>([]);
    const [products, setProducts] = useState<Product[]>([]);
    const [categoryList, setCategoryList] = useState<string[]>(['All']);
    const [loading, setLoading] = useState(true);
    const [activeTab, setActiveTab] = useState<'hub' | 'catalog' | 'pos'>('hub');
    const [cart, setCart] = useState<CartItem[]>([]);
    const [showCart, setShowCart] = useState(false);
    const [showPayment, setShowPayment] = useState(false);
    const [paymentMethod, setPaymentMethod] = useState<'CASH' | 'CARD' | 'TRANSFER'>('CARD');
    const [paymentSuccess, setPaymentSuccess] = useState(false);
    const [selectedCategory, setSelectedCategory] = useState<string>('All');
    const [clientSecret, setClientSecret] = useState<string | null>(null);
    const [paymentLoading, setPaymentLoading] = useState(false);
    const [paymentError, setPaymentError] = useState<string | null>(null);
    const [stripeAvailable, setStripeAvailable] = useState<boolean | null>(null);
    const [currentPage, setCurrentPage] = useState(1);
    const itemsPerPage = 8;

    useEffect(() => {
        const fetchData = async () => {
            try {
                const [salesData, ordersData, productsData, categoriesData, paymentConfig] = await Promise.all([
                    salesService.getAllSales(),
                    salesService.getAllOrders(),
                    salesService.getProducts(),
                    salesService.getProductCategories(),
                    salesService.getPaymentConfig()
                ]);
                setSales(salesData);
                setOrders(ordersData);
                setProducts(productsData);
                setCategoryList(['All', ...categoriesData]);
                setStripeAvailable(paymentConfig.configured && isStripeConfigured);
            } catch (error) {
                console.error('Failed to load sales data:', error);
                setStripeAvailable(false);
            } finally {
                setLoading(false);
            }
        };
        void fetchData();
    }, []);

    // Cart functions
    const addToCart = (product: Product) => {
        setCart(prev => {
            const existing = prev.find(item => item.product.id === product.id);
            if (existing) {
                return prev.map(item =>
                    item.product.id === product.id
                        ? { ...item, quantity: item.quantity + 1 }
                        : item
                );
            }
            return [...prev, { product, quantity: 1 }];
        });
    };

    const removeFromCart = (productId: string) => {
        setCart(prev => prev.filter(item => item.product.id !== productId));
    };

    const updateQuantity = (productId: string, delta: number) => {
        setCart(prev => prev.map(item => {
            if (item.product.id === productId) {
                const newQty = item.quantity + delta;
                if (newQty <= 0) return item;
                return { ...item, quantity: newQty };
            }
            return item;
        }));
    };

    const cartTotal = cart.reduce((sum, item) => sum + (item.product.price * item.quantity), 0);
    const cartItemCount = cart.reduce((sum, item) => sum + item.quantity, 0);
    const cartTotalWithTax = cartTotal * 1.08;

    // Create Stripe payment intent when card payment is selected
    const initiateStripePayment = async () => {
        if (cart.length === 0) return;

        setPaymentLoading(true);
        setPaymentError(null);

        try {
            const items = cart.map(item => ({
                id: item.product.id,
                name: item.product.name,
                price: item.product.price,
                quantity: item.quantity,
                image_url: item.product.image_url,
            }));

            const result = await salesService.createPaymentIntent(items);
            setClientSecret(result.clientSecret);
        } catch (error) {
            console.error('Failed to create payment intent:', error);
            setPaymentError(error instanceof Error ? error.message : 'Failed to initialize payment');
        } finally {
            setPaymentLoading(false);
        }
    };

    // Handle cash/transfer payment (mock)
    const processCashPayment = async () => {
        setPaymentSuccess(false);
        setPaymentLoading(true);

        // Simulate processing
        await new Promise(resolve => setTimeout(resolve, 1500));

        setPaymentSuccess(true);
        setPaymentLoading(false);

        // Clear cart after successful payment
        setTimeout(() => {
            setCart([]);
            setShowPayment(false);
            setPaymentSuccess(false);
            setShowCart(false);
            setClientSecret(null);
        }, 2000);
    };

    // Handle payment method selection
    const handlePaymentMethodSelect = (method: 'CASH' | 'CARD' | 'TRANSFER') => {
        setPaymentMethod(method);
        setPaymentError(null);
        if (method === 'CARD') {
            void initiateStripePayment();
        } else {
            setClientSecret(null);
        }
    };

    // Handle successful Stripe payment
    const handleStripeSuccess = () => {
        setPaymentSuccess(true);
        setTimeout(() => {
            setCart([]);
            setShowPayment(false);
            setPaymentSuccess(false);
            setShowCart(false);
            setClientSecret(null);
        }, 2000);
    };

    // Close payment modal
    const closePaymentModal = () => {
        if (!paymentLoading && !paymentSuccess) {
            setShowPayment(false);
            setClientSecret(null);
            setPaymentError(null);
        }
