                                                        disabled={paymentLoading}
                                                        className={`p-5 rounded-2xl border-2 transition-all flex flex-col items-center gap-3 ${
                                                            paymentMethod === method
                                                                ? 'border-amber-500 bg-amber-500/5 shadow-inner'
