                                            {/* Stripe Card Payment Form */}
                                            {paymentMethod === 'CARD' && (
                                                <div className="border-t border-chocolate-100 pt-6">
                                                    {/* Accepted Cards Display */}
                                                    <div className="flex items-center justify-center gap-3 mb-6 pb-4 border-b border-chocolate-50">
                                                        <span className="text-[10px] font-bold text-chocolate-400 uppercase tracking-widest">Accepted Cards:</span>
                                                        <div className="flex items-center gap-2">
                                                            {/* Visa */}
                                                            <div className="w-10 h-6 bg-[#1A1F71] rounded flex items-center justify-center">
                                                                <span className="text-white text-[8px] font-bold italic">VISA</span>
                                                            </div>
                                                            {/* Mastercard */}
                                                            <div className="w-10 h-6 bg-gradient-to-r from-[#EB001B] to-[#F79E1B] rounded flex items-center justify-center">
                                                                <div className="flex">
                                                                    <div className="w-3 h-3 rounded-full bg-[#EB001B] -mr-1"></div>
                                                                    <div className="w-3 h-3 rounded-full bg-[#F79E1B]"></div>
                                                                </div>
                                                            </div>
                                                            {/* Amex */}
                                                            <div className="w-10 h-6 bg-[#006FCF] rounded flex items-center justify-center">
                                                                <span className="text-white text-[6px] font-bold">AMEX</span>
                                                            </div>
                                                        </div>
                                                    </div>

                                                    {!stripeAvailable ? (
                                                        /* Demo Mode - Stripe not configured */
                                                        <div className="text-center py-8 space-y-4">
                                                            <div className="w-16 h-16 bg-amber-100 rounded-2xl flex items-center justify-center mx-auto">
                                                                <CreditCard className="w-8 h-8 text-amber-600" />
                                                            </div>
                                                            <div>
                                                                <h4 className="font-bold text-chocolate-900 mb-2">Demo Mode</h4>
                                                                <p className="text-chocolate-500 text-sm max-w-xs mx-auto">
                                                                    Card payments require Stripe configuration. Use Cash or Transfer for now.
                                                                </p>
                                                            </div>
                                                            <Button
                                                                onClick={() => { void processCashPayment(); }}
                                                                className="bg-amber-500 text-chocolate-950 font-bold px-8 py-3 rounded-xl"
                                                            >
                                                                Simulate Card Payment
                                                            </Button>
                                                        </div>
                                                    ) : paymentLoading ? (
                                                        <div className="flex flex-col items-center justify-center py-12">
                                                            <Loader2 className="w-10 h-10 text-amber-500 animate-spin mb-4" />
                                                            <p className="text-chocolate-500 font-bold text-sm">Initializing secure payment...</p>
                                                        </div>
                                                    ) : clientSecret && stripePromise ? (
                                                        <Elements
                                                            stripe={stripePromise}
                                                            options={{
                                                                clientSecret,
                                                                appearance: {
                                                                    theme: 'stripe',
                                                                    variables: {
                                                                        colorPrimary: '#f59e0b',
                                                                        colorBackground: '#ffffff',
                                                                        colorText: '#1f1f1f',
                                                                        colorDanger: '#ef4444',
                                                                        fontFamily: 'system-ui, sans-serif',
                                                                        borderRadius: '12px',
                                                                    },
                                                                },
                                                            }}
                                                        >
                                                            <StripePaymentForm
                                                                amount={cartTotalWithTax}
                                                                onSuccess={handleStripeSuccess}
                                                                onCancel={closePaymentModal}
                                                            />
                                                        </Elements>
                                                    ) : (
                                                        <div className="text-center py-8">
                                                            <p className="text-chocolate-400 text-sm mb-4">Click the button below to load the payment form</p>
                                                            <Button
                                                                onClick={() => { void initiateStripePayment(); }}
                                                                className="bg-amber-500 text-chocolate-950 font-bold px-8 py-3 rounded-xl"
                                                            >
                                                                Load Secure Payment
                                                            </Button>
                                                        </div>
                                                    )}
                                                </div>
                                            )}

                                            {/* Cash/Transfer Payment Button */}
                                            {(paymentMethod === 'CASH' || paymentMethod === 'TRANSFER') && (
                                                    <Button
                                                        className="w-full bg-chocolate-950 text-amber-500 font-black py-8 rounded-[2rem] text-lg uppercase tracking-[0.2em] group relative overflow-hidden active:scale-95 disabled:opacity-50"
                                                        onClick={() => { void processCashPayment(); }}
                                                    disabled={paymentLoading}
                                                >
                                                    <span className="relative z-10 flex items-center justify-center gap-4">
                                                        {paymentLoading ? (
                                                            <>
                                                                <Loader2 className="w-6 h-6 animate-spin" />
                                                                Processing...
                                                            </>
                                                        ) : (
                                                            <>
                                                                {paymentMethod === 'CASH' ? 'Confirm Cash Payment' : 'Confirm Transfer'}
                                                                <ChevronRight className="w-6 h-6 group-hover:translate-x-1 transition-transform" />
                                                            </>
                                                        )}
                                                    </span>
                                                </Button>
                                            )}
                                        </div>
                                    </motion.div>
                                )}
                            </AnimatePresence>
                        </motion.div>
                    </motion.div>
                )}
            </AnimatePresence>
        </motion.div>
    );
};

