import React from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import LoginPage from './pages/auth/LoginPage';
import DashboardPage from './pages/dashboard/DashboardPage';
import InventoryPage from './pages/inventory/InventoryPage';
import ProductionPage from './pages/production/ProductionPage';
import SalesPage from './pages/sales/SalesPage';
import AppLayout from './components/layout/AppLayout';
import { useAuthStore } from './store/auth';

function ProtectedRoute({ children }: { children: React.ReactElement }) {
  const isAuth = useAuthStore((s: any) => s.isAuthenticated());
  return isAuth ? children : <Navigate to="/login" replace />;
}

function App() {
  return (
    <Router>
      <Routes>
        <Route path="/login" element={<LoginPage />} />

        <Route element={<ProtectedRoute><AppLayout /></ProtectedRoute>}>
          <Route path="/" element={<DashboardPage />} />
          <Route path="/inventory" element={<InventoryPage />} />
          <Route path="/production" element={<ProductionPage />} />
          <Route path="/sales" element={<SalesPage />} />
          <Route path="/chat" element={<div>Chat Full Page (Coming Soon)</div>} />
        </Route>

         {/* Catch all */}
         <Route path="*" element={<Navigate to="/" replace />} />
      </Routes>
    </Router>
  );
}

export default App;

import { useState } from 'react';
import { Edit2, Save, X } from 'lucide-react';
import Input from '@/presentation/components/ui/Input';

interface EditableStockCellProps {
  item: {
    id: string;
    current_stock: number;
    [key: string]: any;
  };
  updateStock: {
    mutate: (data: { id: string; current_stock: number }, options?: { onSuccess?: () => void }) => void;
    isLoading: boolean;
  };
}

export default function EditableStockCell({
  item,
  updateStock,
}: EditableStockCellProps) {
  const [editing, setEditing] = useState(false);
  const [value, setValue] = useState(item.current_stock.toString());

  const handleSave = () => {
    const num = Number(value);
    if (isNaN(num) || num < 0) return;

    updateStock.mutate(
      { id: item.id, current_stock: num },
      { onSuccess: () => setEditing(false) }
    );
  };

  if (editing) {
    return (
      <div className="flex items-center gap-2">
        <Input
          value={value}
          onChange={e => setValue(e.target.value)}
          className="w-20 px-2 py-1 text-sm"
          autoFocus
        />

        <button
          onClick={handleSave}
          disabled={updateStock.isLoading}
          className="text-green-600 hover:text-green-800"
        >
          <Save className="h-4 w-4" />
        </button>

        <button
          onClick={() => {
            setValue(item.current_stock.toString());
            setEditing(false);
          }}
          className="text-red-600 hover:text-red-800"
        >
          <X className="h-4 w-4" />
        </button>
      </div>
    );
  }

  return (
    <div className="flex items-center gap-2">
      <span>{item.current_stock}</span>
      <button
        onClick={() => setEditing(true)}
        className="text-blue-600 hover:text-blue-800"
      >
        <Edit2 className="h-4 w-4" />
      </button>
    </div>
  );
}

import { useState } from 'react';
import { useInventory } from '../../hooks/useInventory';
import { Search, AlertTriangle, ArrowUpDown, Loader2, Edit2, Save, X } from 'lucide-react';
import { toast } from 'sonner';
import { InventoryItem } from '../../../domain/models/InventoryItem';

export default function InventoryPage() {
  const limit = 15;
  const [page, setPage] = useState(1);
  const [search, setSearch] = useState('');
  const [lowStockOnly, setLowStockOnly] = useState(false);
  const [sortBy, setSortBy] = useState<string | null>(null);
  const [sortDir, setSortDir] = useState<'asc' | 'desc'>('asc');
  
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editValue, setEditValue] = useState<number | ''>('');

  const { 
    items, 
    pagination, 
    isLoading, 
    error, 
    updateStock, 
    isUpdating 
  } = useInventory({
    page,
    limit,
    search: search ? search : undefined,
    low_stock: lowStockOnly, // Ensure simple parameter name match
    sortBy: sortBy ? sortBy : undefined,
    sortDir: sortBy ? sortDir : undefined,
  });

  const handleSort = (field: string) => {
    if (sortBy === field) {
      setSortDir(prev => prev === 'asc' ? 'desc' : 'asc');
    } else {
      setSortBy(field);
      setSortDir('asc');
    }
    setPage(1);
  };

  const startEdit = (item: InventoryItem) => {
    setEditingId(item.id);
    setEditValue(item.current_stock);
  };

  const cancelEdit = () => {
    setEditingId(null);
    setEditValue('');
  };

  const handleSaveEdit = async (id: string) => {
    if (editValue === '' || isNaN(Number(editValue))) return;

    try {
      await updateStock({ id, quantity: Number(editValue) });
      toast.success('Stock updated');
      setEditingId(null);
      setEditValue('');
    } catch (err) {
      console.error(err);
      toast.error('Failed to update stock');
    }
  };

  return (
    <div className="space-y-6 p-6">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <h1 className="text-3xl font-serif font-bold text-primary">Inventory Management</h1>

        <div className="flex flex-col sm:flex-row gap-4">
          <div className="relative">
            <Search className="absolute right-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
            <input
              type="text"
              placeholder="Search by name or SKU..."
              value={search}
              onChange={(e) => {
                setSearch(e.target.value);
                setPage(1);
              }}
              className="w-full sm:w-64 pl-4 pr-10 py-2 border rounded bg-input text-foreground focus:outline-none focus:ring-2 focus:ring-ring"
            />
          </div>

          <label className="flex items-center gap-2 whitespace-nowrap cursor-pointer">
            <input
              type="checkbox"
              checked={lowStockOnly}
              onChange={(e) => {
                setLowStockOnly(e.target.checked);
                setPage(1);
              }}
              className="h-4 w-4 text-primary rounded border-input"
            />
            <span className="text-sm font-medium">Low stock only</span>
          </label>
        </div>
      </div>

      {error && (
        <div className="bg-destructive/10 border border-destructive/20 rounded-lg p-4 text-destructive text-center">
          Failed to load inventory
        </div>
      )}

      <div className="bg-card shadow rounded-lg overflow-hidden border border-border">
        <table className="min-w-full divide-y divide-border">
          <thead className="bg-muted/50">
            <tr>
              <th
                className="px-6 py-3 text-left text-xs font-medium text-muted-foreground uppercase tracking-wider cursor-pointer hover:text-foreground"
                onClick={() => handleSort('name')}
              >
                Name / SKU
                {sortBy === 'name' && <ArrowUpDown className="inline h-4 w-4 ml-1" />}
              </th>
              <th
                className="px-6 py-3 text-left text-xs font-medium text-muted-foreground uppercase tracking-wider cursor-pointer hover:text-foreground"
                onClick={() => handleSort('current_stock')}
              >
                Current Stock
                {sortBy === 'current_stock' && <ArrowUpDown className="inline h-4 w-4 ml-1" />}
              </th>
              <th className="px-6 py-3 text-left text-xs font-medium text-muted-foreground uppercase tracking-wider">
                Min Stock
              </th>
              <th className="px-6 py-3 text-left text-xs font-medium text-muted-foreground uppercase tracking-wider">
                Unit
              </th>
              <th className="px-6 py-3 text-left text-xs font-medium text-muted-foreground uppercase tracking-wider">
                Status
              </th>
              <th className="px-6 py-3 text-left text-xs font-medium text-muted-foreground uppercase tracking-wider">
                Actions
              </th>
            </tr>
          </thead>
          <tbody className="divide-y divide-border bg-card">
            {isLoading ? (
              <tr>
                <td colSpan={6} className="h-32 text-center">
                  <Loader2 className="inline animate-spin h-8 w-8 text-primary" />
                  <span className="ml-2">Loading inventory...</span>
                </td>
              </tr>
            ) : items.length === 0 ? (
              <tr>
                <td colSpan={6} className="h-32 text-center text-muted-foreground">
                  No items found
                </td>
              </tr>
            ) : (
              items.map(item => {
                const isLow = item.current_stock <= item.minimum_stock;
                const isEditing = editingId === item.id;

                return (
                  <tr key={item.id} className="hover:bg-muted/30 transition-colors">
                    <td className="px-6 py-4 whitespace-nowrap">
                      <div className="font-medium text-foreground">{item.name}</div>
                      <div className="text-sm text-muted-foreground">{item.sku}</div>
                    </td>

                    <td className="px-6 py-4 whitespace-nowrap">
                      {isEditing ? (
                        <div className="flex items-center gap-2">
                          <input
                            type="number"
                            value={editValue}
                            onChange={e => setEditValue(Number(e.target.value))}
                            className="w-24 px-2 py-1 border rounded bg-input text-foreground"
                            min={0}
                            step="0.01"
                            autoFocus
                          />
                          <button
                            onClick={() => handleSaveEdit(item.id)}
                            className="text-green-600 hover:text-green-800 disabled:opacity-50"
                            disabled={isUpdating}
                          >
                            <Save size={18} />
                          </button>
                          <button
                            onClick={cancelEdit}
                            className="text-destructive hover:text-destructive/80"
                          >
                            <X size={18} />
                          </button>
                        </div>
                      ) : (
                        <div className="flex items-center gap-2">
                          <span className={isLow ? 'text-destructive font-medium' : ''}>{item.current_stock.toFixed(2)}</span>
                          <button
                            onClick={() => startEdit(item)}
                            className="text-primary hover:text-primary/80"
                          >
                            <Edit2 size={16} />
                          </button>
                        </div>
                      )}
                    </td>

                    <td className="px-6 py-4 whitespace-nowrap text-muted-foreground">
                      {item.minimum_stock.toFixed(2)}
                    </td>

                    <td className="px-6 py-4 whitespace-nowrap text-muted-foreground">
                      {item.unit}
                    </td>

                    <td className="px-6 py-4 whitespace-nowrap">
                      {isLow ? (
                        <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-red-100 text-red-800 dark:bg-red-900 dark:text-red-300">
                          <AlertTriangle size={14} className="mr-1" />
                          Low
                        </span>
                      ) : (
                        <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-300">
                          OK
                        </span>
                      )}
                    </td>

                    <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-medium">
                      
                    </td>
                  </tr>
                );
              })
            )}
          </tbody>
        </table>
      </div>

      <div className="flex justify-center gap-4 mt-6">
        <button
          onClick={() => setPage(p => Math.max(1, p - 1))}
          disabled={page === 1 || isLoading}
          className="px-6 py-2 border rounded disabled:opacity-50 hover:bg-muted"
        >
          Previous
        </button>
        <span className="py-2 px-4">Page {page} of {pagination?.totalPages || 1}</span>
        <button
          onClick={() => setPage(p => p + 1)}
          disabled={page === (pagination?.totalPages || 1) || isLoading}
          className="px-6 py-2 border rounded disabled:opacity-50 hover:bg-muted"
        >
          Next
        </button>
      </div>
    </div>
  );
}

import { useState, useEffect, useCallback } from 'react';
import api from '@/data/infrastructure/httpClient';
import { toast } from 'sonner';
import { Plus, Loader2 } from 'lucide-react';

interface Batch {
  id: string;
  recipe_id: string;
  quantity_produced: number;
  status: string;
  created_at: string;
}

interface Ingredient {
  id: string;
  name: string;
  current_stock: number;
  unit: string;
}

export default function ProductionPage() {
  const [batches, setBatches] = useState<Batch[]>([]);
  const [ingredients, setIngredients] = useState<Ingredient[]>([]);
  const [loading, setLoading] = useState(true);
  const [form, setForm] = useState({
    recipe_id: '',
    quantity_produced: '',
    ingredients: [{ ingredient_id: '', quantity: 0 }],
  });

  const fetchData = useCallback(async () => {
    setLoading(true);
    try {
      const [batchesRes, ingRes] = await Promise.all([
        api.get('/production/batches'),
        api.get('/inventory'),
      ]);
      setBatches(batchesRes.data.data ?? []);
      setIngredients(ingRes.data.data ?? []);
    } catch (err: unknown) {
      console.error(err);
      toast.error('Failed to load production data');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchData();
  }, [fetchData]);

  const addIngredient = () => {
    setForm({
      ...form,
      ingredients: [...form.ingredients, { ingredient_id: '', quantity: 0 }],
    });
  };

  const updateIngredient = (index: number, field: 'ingredient_id' | 'quantity', value: string | number) => {
    const newIng = [...form.ingredients];
    newIng[index] = { ...newIng[index], [field]: value };
    setForm({ ...form, ingredients: newIng });
  };

  const createBatch = async () => {
    if (!form.recipe_id || !form.quantity_produced) {
      toast.error('Recipe ID and quantity are required');
      return;
    }

    try {
      await api.post('/production/batches', form);
      
      // Reset form
      setForm({ 
        recipe_id: '', 
        quantity_produced: '', 
        ingredients: [{ ingredient_id: '', quantity: 0 }] 
      });

      // Refresh list
      const res = await api.get('/production/batches');
      setBatches(res.data.data ?? []);
      
      toast.success('Batch created successfully');
    } catch (err) {
      console.error(err);
      toast.error('Failed to create batch');
    }
  };

  return (
    <div className="space-y-8">
      <h1 className="text-2xl font-bold text-gray-900">Production Management</h1>

      {/* Create Batch Form */}
      <div className="bg-white p-6 rounded-xl shadow border border-secondary-200">
        <h2 className="text-xl font-semibold mb-4 text-secondary-900">Create New Batch</h2>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-6">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">Recipe ID</label>
            <input
              type="text"
              value={form.recipe_id}
              onChange={e => setForm({ ...form, recipe_id: e.target.value })}
              className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-amber-500"
              placeholder="recipe-uuid-123"
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">Quantity Produced</label>
            <input
              type="number"
              value={form.quantity_produced}
              onChange={e => setForm({ ...form, quantity_produced: e.target.value })}
              className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-amber-500"
              min="1"
            />
          </div>
        </div>

        <div className="mb-6">
          <div className="flex justify-between items-center mb-3">
            <h3 className="text-lg font-semibold text-secondary-900">Ingredients</h3>
            <button
              type="button"
              onClick={addIngredient}
              className="flex items-center gap-1 text-indigo-600 hover:text-indigo-800 text-sm font-medium"
            >
              <Plus size={16} />
              Add Ingredient
            </button>
          </div>

          {form.ingredients.map((ing, idx) => (
            <div key={idx} className="flex gap-4 mb-3">
              <select
                value={ing.ingredient_id}
                onChange={e => updateIngredient(idx, 'ingredient_id', e.target.value)}
                className="flex-1 px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-amber-500"
              >
                <option value="">Select Ingredient</option>
                {ingredients.map(i => (
                  <option key={i.id} value={i.id}>
                    {i.name} ({i.current_stock} {i.unit} available)
                  </option>
                ))}
              </select>
              <input
                type="number"
                value={ing.quantity}
                onChange={e => updateIngredient(idx, 'quantity', Number(e.target.value))}
                className="w-32 px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-amber-500"
                placeholder="Qty"
                min="0.1"
                step="0.1"
              />
            </div>
          ))}
        </div>

        <button
          onClick={createBatch}
          className="bg-indigo-600 text-white px-6 py-3 rounded-lg hover:bg-indigo-700 transition font-medium"
        >
          Create Batch
        </button>
      </div>

      {/* Batch List */}
      <div className="bg-white rounded-xl shadow border border-secondary-200 overflow-hidden">
        <div className="p-6 border-b border-secondary-200">
          <h2 className="text-xl font-semibold text-secondary-900">Active Batches</h2>
        </div>

        <div className="overflow-x-auto">
          <table className="min-w-full divide-y divide-gray-200">
            <thead className="bg-gray-50">
              <tr>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">ID</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Recipe</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Quantity</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Status</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Created</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-200 bg-white">
              {loading ? (
                <tr>
                  <td colSpan={5} className="px-6 py-8 text-center">
                    <Loader2 className="animate-spin h-8 w-8 text-indigo-600 mx-auto" />
                    <p className="mt-2 text-sm text-gray-500">Loading batches...</p>
                  </td>
                </tr>
              ) : batches.length === 0 ? (
                <tr>
                  <td colSpan={5} className="px-6 py-12 text-center text-gray-500">
                    No active batches found
                  </td>
                </tr>
              ) : (
                batches.map(batch => (
                  <tr key={batch.id} className="hover:bg-gray-50 transition-colors">
                    <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">
                      {batch.id.slice(0, 8)}...
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                      {batch.recipe_id}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                      {batch.quantity_produced}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${
                        batch.status === 'COMPLETED' ? 'bg-green-100 text-green-800' :
                        batch.status === 'IN_PROGRESS' ? 'bg-yellow-100 text-yellow-800' :
                        'bg-gray-100 text-gray-800'
                      }`}>
                        {batch.status}
                      </span>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                      {new Date(batch.created_at).toLocaleDateString()}
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}

import { useState } from 'react';
import { useSales } from '../../hooks/useSales';
import { useInventory } from '../../hooks/useInventory';
import { Plus, Minus, Trash2, Loader2 } from 'lucide-react';
import { InventoryItem } from '../../../domain/models/InventoryItem';

export default function SalesPage() {
  const { orders, isLoadingOrders, recordSale } = useSales({ page: 1, limit: 15 });
  // Fetch ample inventory for the dropdown/grid
  const { items: inventory, isLoading: isLoadingInventory } = useInventory({ limit: 100 }); 

  const [cart, setCart] = useState<{ item: InventoryItem; quantity: number }[]>([]);
  const [employeeId, setEmployeeId] = useState('');
  const [discount, setDiscount] = useState(0);

  const addToCart = (item: InventoryItem) => {
     setCart(prev => {
         const existing = prev.find(i => i.item.id === item.id);
         if (existing) {
             return prev.map(i => i.item.id === item.id ? { ...i, quantity: i.quantity + 1 } : i);
         }
         return [...prev, { item, quantity: 1 }];
     });
  };

  const updateQuantity = (id: string, delta: number) => {
    setCart(prev => prev.map(i => {
        if (i.item.id === id) {
             return { ...i, quantity: Math.max(0, i.quantity + delta) };
        }
        return i;
    }).filter(i => i.quantity > 0));
  };
  
  const removeItem = (id: string) => setCart(prev => prev.filter(i => i.item.id !== id));

  const handleRecordSale = async () => {
      try {
          await recordSale({
              employeeId,
              discountPercentage: discount,
              items: cart.map(i => ({ inventoryId: i.item.id, quantity: i.quantity }))
          });
          setCart([]);
          setEmployeeId('');
          setDiscount(0);
          alert('Sale recorded!');
      } catch (e) {
          console.error(e);
          alert('Failed to record sale');
      }
  };

  const subtotal = cart.reduce((sum, i) => sum + (i.item.price || 0) * i.quantity, 0);
  const total = subtotal * (1 - discount / 100);

  return (
    <div className="space-y-8 p-6">
      <h1 className="text-3xl font-serif font-bold text-primary">Sales Management</h1>
      
      {/* Sales Recording UI */}
      <div className="grid md:grid-cols-2 gap-8">
        <div className="bg-card p-6 rounded-lg shadow border border-border">
           <h2 className="text-xl font-semibold mb-4 text-primary font-serif">New Sale</h2>
           <div className="space-y-4">
               <div>
                   <label className="text-sm font-medium mb-1 block">Employee ID</label>
                   <input 
                      className="w-full p-2 border rounded bg-input text-foreground" 
                      placeholder="e.g. EMP-001" 
                      value={employeeId} 
                      onChange={e => setEmployeeId(e.target.value)} 
                   />
               </div>
               <div>
                   <label className="text-sm font-medium mb-1 block">Discount %</label>
                   <input 
                      type="number" 
                      className="w-full p-2 border rounded bg-input text-foreground" 
                      value={discount} 
                      onChange={e => setDiscount(Number(e.target.value))} 
                      min="0" max="100"
                   />
               </div>
               
               {/* Product Grid */}
               <div>
                   <label className="text-sm font-medium mb-1 block">Select Products</label>
                   <div className="h-64 overflow-y-auto border rounded p-2 grid grid-cols-2 gap-2 bg-muted/20">
                       {isLoadingInventory ? <div className="col-span-2 flex justify-center p-4"><Loader2 className="animate-spin text-primary" /></div> : 
                         inventory.map(item => (
                             <div key={item.id} className="p-3 border rounded hover:bg-muted cursor-pointer transition-colors bg-card" onClick={() => addToCart(item)}>
                                 <div className="font-medium truncate">{item.name}</div>
                                 <div className="text-sm text-secondary font-bold">${(item.price || 0).toFixed(2)}</div>
                                 <div className="text-xs text-muted-foreground">{item.current_stock} {item.unit}</div>
                             </div>
                         ))
                       }
                   </div>
               </div>
           </div>
        </div>

        {/* Cart */}
         <div className="bg-card p-6 rounded-lg shadow border border-border flex flex-col">
             <h2 className="text-xl font-semibold mb-4 text-primary font-serif">Cart Summary</h2>
             <div className="space-y-2 flex-grow overflow-y-auto max-h-96">
                 {cart.length === 0 && <div className="text-center text-muted-foreground py-8">Cart is empty</div>}
                 {cart.map(({ item, quantity }) => (
                     <div key={item.id} className="flex justify-between items-center p-2 border-b">
                         <div>
                             <div className="font-medium">{item.name}</div>
                             <div className="text-sm text-muted-foreground">${(item.price || 0).toFixed(2)} x {quantity}</div>
                         </div>
                         <div className="flex items-center gap-2">
                             <div className="flex border rounded">
                                 <button onClick={() => updateQuantity(item.id, -1)} className="p-1 hover:bg-muted"><Minus size={14} /></button>
                                 <span className="w-8 text-center text-sm leading-6">{quantity}</span>
                                 <button onClick={() => updateQuantity(item.id, 1)} className="p-1 hover:bg-muted"><Plus size={14} /></button>
                             </div>
                             <button onClick={() => removeItem(item.id)} className="text-destructive hover:bg-destructive/10 p-1 rounded"><Trash2 size={16} /></button>
                         </div>
                     </div>
                 ))}
             </div>
             <div className="mt-4 border-t pt-4 bg-muted/10 -mx-6 px-6 -mb-6 pb-6 rounded-b-lg">
                 <div className="flex justify-between text-sm mb-2">
                     <span>Subtotal</span>
                     <span>${subtotal.toFixed(2)}</span>
                 </div>
                 <div className="flex justify-between text-sm mb-2 text-green-600">
                     <span>Discount ({discount}%)</span>
                     <span>-${(subtotal * discount / 100).toFixed(2)}</span>
                 </div>
                 <div className="flex justify-between font-bold text-lg text-primary">
                     <span>Total</span>
                     <span>${total.toFixed(2)}</span>
                 </div>
                 <button 
                    onClick={handleRecordSale}
                    className="w-full mt-4 bg-primary text-primary-foreground py-3 rounded-lg hover:bg-primary/90 transition-colors disabled:opacity-50 font-medium"
                    disabled={cart.length === 0 || !employeeId}
                 >
                     Complete Sale
                 </button>
             </div>
         </div>
      </div>

      {/* Online Orders */}
      <div className="bg-card rounded-lg shadow border border-border overflow-hidden">
          <div className="p-6 border-b">
              <h2 className="text-xl font-semibold text-primary font-serif">Recent Online Orders</h2>
          </div>
          <div className="overflow-x-auto">
              {isLoadingOrders ? <div className="p-12 flex justify-center"><Loader2 className="animate-spin h-8 w-8 text-primary" /></div> : 
                 <table className="w-full text-sm">
                     <thead className="bg-muted/50">
                         <tr className="text-left">
                             <th className="px-6 py-3 font-medium text-muted-foreground uppercase tracking-wider">ID</th>
                             <th className="px-6 py-3 font-medium text-muted-foreground uppercase tracking-wider">Customer</th>
                             <th className="px-6 py-3 font-medium text-muted-foreground uppercase tracking-wider">Total</th>
                             <th className="px-6 py-3 font-medium text-muted-foreground uppercase tracking-wider">Status</th>
                             <th className="px-6 py-3 font-medium text-muted-foreground uppercase tracking-wider">Date</th>
                         </tr>
                     </thead>
                     <tbody className="divide-y divide-border">
                         {orders.map(order => (
                             <tr key={order.id} className="hover:bg-muted/30 transition-colors">
                                 <td className="px-6 py-4 font-mono text-xs">{order.id.split('-')[0]}...</td>
                                 <td className="px-6 py-4">{order.customer_name}</td>
                                 <td className="px-6 py-4 font-medium">${order.total.toFixed(2)}</td>
                                 <td className="px-6 py-4">
                                     <span className={`inline-flex px-2.5 py-0.5 rounded-full text-xs font-medium ${
                                         order.status === 'DELIVERED' ? 'bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-300' :
                                         order.status === 'PENDING' ? 'bg-yellow-100 text-yellow-800 dark:bg-yellow-900 dark:text-yellow-300' :
                                         'bg-gray-100 text-gray-800 dark:bg-gray-800 dark:text-gray-300'
                                     }`}>
                                         {order.status}
                                     </span>
                                 </td>
                                 <td className="px-6 py-4 text-muted-foreground">{new Date(order.created_at).toLocaleDateString()}</td>
                             </tr>
                         ))}
                     </tbody>
                 </table>
              }
          </div>
      </div>
    </div>
  );
}

import axios, { AxiosError, AxiosInstance, InternalAxiosRequestConfig, AxiosResponse } from 'axios';

// Extend the AxiosRequestConfig interface to include our custom property
declare module 'axios' {
  interface AxiosRequestConfig {
    _retry?: boolean;
  }
}

const API_URL = (import.meta?.env?.VITE_API_URL) ?? 'http://127.0.0.1:5003/api';

const api: AxiosInstance = axios.create({
  baseURL: API_URL,
  headers: {
    'Content-Type': 'application/json',
  },
  timeout: 10000,
});

// Request Interceptor
api.interceptors.request.use(
  (config: InternalAxiosRequestConfig) => {
    const token = localStorage.getItem('token');
    if (token) {
      config.headers.Authorization = `Bearer ${token}`;
    }

    // Debug logging in development
    if (import.meta.env.DEV) {
      console.log(`[API Request] ${config.method?.toUpperCase()} ${config.url}`, config.data ?? '');
    }

    return config;
  },
  (error: AxiosError) => {
    return Promise.reject(error);
  }
);

// Response Interceptor
api.interceptors.response.use(
  (response: AxiosResponse) => {
    // Return the "data" part directly if it follows the consistent APIResponse shape
    // Our backend returns { success: boolean, data: any, ... }
    // We want to return that whole object or just the inner data depending on convention.
    // The user requested: "Return data directly (so components don't need .data.data)"
    // If the backend response is { success: true, data: { ... } }, we return { success: true, data: ... }
    // Axios puts the body in response.data.
    // So response.data IS the { success, data, error } object.

    return response.data;
  },
  async (error: AxiosError) => {
    const originalRequest = error.config;

    if (error.response) {
      // Handle 401 Unauthorized
      // Handle 401 Unauthorized OR 404 Not Found on the /me endpoint
      // 404 on /me means the token is valid but the user ID no longer exists (stale session)
      if (error.response.status === 401 || (error.response.status === 404 && originalRequest?.url?.includes('/auth/me'))) {
        // Clear token and redirect to login
        localStorage.removeItem('token');
        localStorage.removeItem('user');

        // Prevent infinite redirect loops if we are already on login
        if (window.location.pathname !== '/login') {
             window.location.href = '/login';
        }
      }

      // Handle 403 Forbidden
      if (error.response.status === 403) {
        console.error('Access Denied: You do not have permission to perform this action.');
        // Optionally trigger a UI toast here
      }
    }

    // Standardize error message
    const responseData = error.response?.data as { message?: string; error?: string } | undefined;
    const errorMessage = 
      responseData?.message ?? 
      responseData?.error ?? 
      error.message ?? 
      'An unexpected error occurred';

    // Construct a consistent error object to return
    // Note: We reject with a proper Error so components can use error.message
    const enhancedError = new Error(errorMessage) as Error & { success?: boolean; originalError?: unknown };
    enhancedError.success = false;
    enhancedError.originalError = error;

    return Promise.reject(enhancedError);
  }
);

export default api;
